    private String getComText(int id) {
        switch (id) {
            case 1: return ct.getString(R.string.com1);
            case 2: return ct.getString(R.string.com2);
            case 3: return ct.getString(R.string.com3);
            case 4: return ct.getString(R.string.com4);
            case 5: return ct.getString(R.string.com5);
            case 6: return ct.getString(R.string.com6);
        }
        return "";
    }

    private String getBotMsgText(int id) {
        switch (id) {
            case 7: return ct.getString(R.string.botmsg7);
            case 8: return ct.getString(R.string.botmsg8);
            case 9: return ct.getString(R.string.botmsg9);
            case 10: return ct.getString(R.string.botmsg10);
            case 11: return ct.getString(R.string.botmsg11);
            case 12: return ct.getString(R.string.bots_available);
        }
        return "";
    }

