    // расчет лимита юнитов и ботов с учетом конфига профильного сервера
    int getEffectiveMaxUnit(int mode) {
        boolean hasProfCfg = false;
        int cfgNormalBots = maxunitnobr;
        int cfgBrBots = maxunitbr;
        try {
            hasProfCfg = onlinegame || skayrux.shootout2d.sys_menu_socket_repository.INSTANCE.isServerOnline();
            if (hasProfCfg) {
                skayrux.shootout2d.OnlineServerConfig cfg = skayrux.shootout2d.sys_menu_socket_repository.INSTANCE.getOnlineServerConfig();
                cfgNormalBots = Math.max(1, Math.min(1000, cfg.getMaxBotsNormalServer()));
                cfgBrBots = Math.max(1, Math.min(1000, cfg.getMaxBrBots()));
            }
        } catch (Exception ignored) {}
        if (mode == 12) {
            if (!hasProfCfg) return maxunitbr;
            int needed = Math.max(maxunitbr, Math.max(cfgBrBots + 2, rbc + 2));
            return Math.min(maxunit, needed);
        } else {
            if (!hasProfCfg) return maxunitnobr;
            int needed = Math.max(maxunitnobr, Math.max(cfgNormalBots + 2, rbc + bbc + 2));
            return Math.min(maxunit, needed);
        }
    }
