    public void reloadInGameSettings() {
        try {
            smooth = skayrux.shootout2d.AppSettings.INSTANCE.getBoolean(this, "smoothCamera", false);
            centercamera = skayrux.shootout2d.AppSettings.INSTANCE.getBoolean(this, "centerCamera", true);
            drawAlive = skayrux.shootout2d.AppSettings.INSTANCE.getBoolean(this, "draw_alive", true);
            autoUse = skayrux.shootout2d.AppSettings.INSTANCE.getBoolean(this, "auto_use", true);
            blackTextIsOn = skayrux.shootout2d.AppSettings.INSTANCE.getBoolean(this, "black_text", false);
            timerlostIsOn = skayrux.shootout2d.AppSettings.INSTANCE.getBoolean(this, "show_ping", false);
            uiIsEnable = skayrux.shootout2d.AppSettings.INSTANCE.getUiEnable(this);
            prizIsOn = skayrux.shootout2d.AppSettings.INSTANCE.isCrosshairEnabled(this);
            float vol = skayrux.shootout2d.AppSettings.INSTANCE.getFloat(this, "volume", 100f);
            soundVolume = Math.min(Math.max((int) vol, 0), 100);
            sound = soundVolume >= 1;
            applySysUpravleniyeConfig(w, h);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void setGameMenuVisible(final boolean visible) {
        if (visible && (mZagruzkaVisible || loadingtimer < 5 || getcustommap || (netgame && netserver == 0 && !gameconnect) || !initgl)) {
            return;
        }
        mGameMenuVisible = visible;
        skayrux.shootout2d.LiveBackgroundState.INSTANCE.setEditingControls(false);
        if (visible) {
            skayrux.shootout2d.GameMenuHelper.resetToGlavnyyRazdelchik();
        } else {
            reloadInGameSettings();
        }
        runOnUiThread(new Runnable() {
            @Override
            public void run() {
                if (mGameMenuView != null) {
                    if (visible) {
                        mGameMenuView.setVisibility(View.VISIBLE);
                        mGameMenuView.bringToFront();
                        skayrux.shootout2d.GameMenuHelper.setVisible(true);
                        mGameMenuView.requestFocus();
                        mGameMenuView.requestLayout();
                        mGameMenuView.invalidate();
                        if (fl != null) {
                            fl.requestLayout();
                            fl.invalidate();
                        }
                    } else {
                        skayrux.shootout2d.GameMenuHelper.setVisible(false);
                        mGameMenuView.setVisibility(View.GONE);
                    }
                } else {
                    skayrux.shootout2d.GameMenuHelper.setVisible(visible);
                }
            }
        });
    }

    public boolean isGameMenuVisible() {
        return mGameMenuVisible;
    }

    // выход из матча через игровое меню с гарантированной отправкой дисконнекта
    public void exitFromGameMenu() {
        setGameMenuVisible(false);
        if (soundManager != null) soundManager.stopAllSoundsOnExit();
        stopthreads();
        try {
            if (netgame) senddisconnect();
        } catch (Exception ignored) {}
        netgame = false;
        stopnetgame(true);
        finish();
    }

    private void setZagruzkaLayoutVisible(final boolean visible) {
        if (mZagruzkaView == null) return;
        if (mZagruzkaVisible == visible) return;
        mZagruzkaVisible = visible;
        if (visible && mGameMenuVisible) {
            setGameMenuVisible(false);
        }
        runOnUiThread(new Runnable() {
            @Override
            public void run() {
                if (mZagruzkaView != null) {
                    mZagruzkaView.setVisibility(visible ? View.VISIBLE : View.GONE);
                }
            }
        });
    }
