    // получение активного сессионного токена для сетевой игры
    String getActiveSessionToken() {
        try {
            String repoToken = skayrux.shootout2d.sys_menu_socket_repository.INSTANCE.getCurrentSessionToken();
            if (repoToken != null && repoToken.trim().length() >= 16) {
                return repoToken.trim();
            }
        } catch (Throwable ignored) {}
        try {
            String savedToken = skayrux.shootout2d.AppSettings.INSTANCE.getString(this, "session_token", "");
            if (savedToken != null && savedToken.trim().length() >= 16) {
                return savedToken.trim();
            }
        } catch (Throwable ignored) {}
        try {
            String guestToken = skayrux.shootout2d.AppSettings.INSTANCE.getString(this, "saved_guest_token", "");
            if (guestToken != null && guestToken.trim().length() >= 16) {
                return guestToken.trim();
            }
        } catch (Throwable ignored) {}
        return "";
    }

    // очистка строкового айди игрока от токенов
    String sanitizePlayerStrId(String rawId, int fallbackSrvId) {
        if (rawId != null) {
            String trimmed = rawId.trim();
            if (!trimmed.isEmpty()
                    && !trimmed.equals("0")
                    && !trimmed.equalsIgnoreCase("N/A")
                    && !trimmed.equalsIgnoreCase("null")
                    && !trimmed.contains("-")
                    && trimmed.length() < 12) {
                return trimmed;
            }
        }
        return (fallbackSrvId > 0) ? String.valueOf(fallbackSrvId) : "";
    }

    void initUserSrvId() {
        try {
            String repoName = skayrux.shootout2d.sys_menu_socket_repository.INSTANCE.getCurrentPlayerName();
            if (repoName != null && !repoName.trim().isEmpty() && (plname == null || plname.isEmpty() || plname.equals("Player"))) {
                plname = repoName.trim();
            }
        } catch (Throwable ignored) {}

        try {
            int repoAdmin = skayrux.shootout2d.sys_menu_socket_repository.INSTANCE.getCurrentPlayerAdminStatus();
            if (repoAdmin == 1) {
                userstatus = 1;
            }
        } catch (Throwable ignored) {}

        try {
            Intent intent = getIntent();
            if (intent != null && intent.getBooleanExtra("IS_ADMIN", false)) {
                userstatus = 1;
            }
        } catch (Throwable ignored) {}

        String candidateId = "";
        try {
            String repoId = skayrux.shootout2d.sys_menu_socket_repository.INSTANCE.getCurrentPlayerId();
            candidateId = sanitizePlayerStrId(repoId, 0);
        } catch (Throwable ignored) {}

        if (candidateId.isEmpty()) {
            try {
                Intent intent = getIntent();
                if (intent != null) {
                    String intentAccId = intent.getStringExtra("ACCOUNT_ID");
                    candidateId = sanitizePlayerStrId(intentAccId, 0);
                }
            } catch (Throwable ignored) {}
        }

        if (candidateId.isEmpty()) {
            try {
                String savedId = skayrux.shootout2d.AppSettings.INSTANCE.getString(this, "driver_account_id", "");
                candidateId = sanitizePlayerStrId(savedId, 0);
            } catch (Throwable ignored) {}
        }

        if (!candidateId.isEmpty()) {
            usersrvstrid = candidateId;
            int parsedId = 0;
            try {
                parsedId = Integer.parseInt(usersrvstrid);
            } catch (Exception ignored) {}
            int h = usersrvstrid.hashCode();
            if (h == Integer.MIN_VALUE) h = 0;
            int hash = Math.abs(h);
            usersrvid = (parsedId != 0) ? parsedId : (hash > 100000 ? hash : hash + 100000);
            if (gamerid <= 123456 || gamerid == 0 || gamerid == 1 || gamerid == -1) {
                gamerid = rand.nextInt(899999999) + 100000;
            }
            profonline = true;
            String activeToken = getActiveSessionToken();
            usertmpid = (!activeToken.isEmpty()) ? activeToken : usersrvstrid;
        } else {
            usersrvstrid = "";
            usersrvid = 0;
            if (gamerid <= 123456 || gamerid == 0 || gamerid == 1 || gamerid == -1) {
                gamerid = rand.nextInt(899999999) + 100000;
            }
        }

        if (usertmpid == null || usertmpid.isEmpty() || usertmpid.equals("0")) {
            String uuid = UUID.randomUUID().toString().replace("-", "").toLowerCase();
            usertmpid = (uuid.length() >= 12) ? uuid.substring(0, 12) : "0123456789ab";
        }
        enc = (usertmpid.length() >= 12) ? usertmpid.substring(3, 12) : "012345678";

        synchronized (cheatlock) {
            ensureAcStatsInitializedLocked();
            setacsrvid(usersrvid);
            setacstatus(userstatus);
            setacscore(userscore);
            setacuserstats(userenemk, userbugk, userzomk, userjugk, userghostk, userdeath);
        }
    }

    void mesavemapdata(String filename) {//sohranit dannie karti
        initUserSrvId();
        if (memapusrvid == 0 && usersrvid != 0) {
            memapusrvid = usersrvid;
        }
        try {
            DataOutputStream daos = new DataOutputStream(openFileOutput(filename, MODE_PRIVATE));
            daos.writeByte(gameversion);
            daos.writeUTF(memapname);
            daos.writeUTF(memapuid);
            if (memapusrvid != 0) {
                daos.writeInt(memapusrvid);
            } else {
                daos.writeInt(usersrvid);
                memapusrvid = usersrvid;
            }
            daos.writeInt(0);
            daos.writeShort(memapw);
            daos.writeShort(memaph);
            metimestamp = String.valueOf(System.currentTimeMillis());
            daos.writeUTF(metimestamp);
            daos.writeInt(memap.size());
            daos.writeShort(mapminx);
            daos.writeShort(mapminy);
            daos.writeShort(mapmaxx);
            daos.writeShort(mapmaxy);
            for (int i = 0; i < memap.size(); i++) {
                GameMapKv mapkv = memap.get(i);
                if (mapkv.remove) continue;
                daos.writeUTF(mapkv.texname);
                daos.writeByte(mapkv.svp);
                daos.writeShort(mapkv.x0);
                daos.writeShort(mapkv.y0);
                daos.writeShort(mapkv.x1);
                daos.writeShort(mapkv.y1);
            }
            daos.close();
        } catch (IOException e) {
            e.printStackTrace();
            showtoast(ct.getString(R.string.error_saving_map));
        }
    }

    int[] getmemapkv(String mapuid) {//kolvo kvadratov karti
        int[] count = new int[2];
        File mapfile = getFileStreamPath(mapuid + ".map");
        if (!mapfile.exists()) return count;
        try {
            DataInputStream dais = new DataInputStream(new FileInputStream(mapfile));
            dais.readByte();//gameversion
            dais.readUTF();
            dais.readUTF();
            dais.readInt();
            dais.readInt();//gamerid
            int mapw = dais.readShort();
            int maph = dais.readShort();
            count[0] = mapw * maph;
            dais.readUTF();//timestamp
            dais.readInt();//maxmapk
            dais.readShort();
            dais.readShort();
            dais.readShort();
            dais.readShort();
            while (dais.available() > 0) {
                dais.readUTF();
                dais.readByte();
                dais.readShort();
                dais.readShort();
                dais.readShort();
                dais.readShort();
                count[1]++;
            }
            dais.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
        return count;
    }

    int getmeobcount(String mapuid) {
        int count = 0;
        File obfile = getFileStreamPath(mapuid + ".ob");
        if (!obfile.exists()) return 0;
        try {
            DataInputStream dais = new DataInputStream(new FileInputStream(obfile));
            dais.readByte();
            dais.readUTF();
            while (dais.available() > 0) {
                dais.readByte();
                dais.readShort();
                dais.readShort();
                count++;
            }
            dais.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
        return count;
    }

    boolean provonlinemap(String mapuid) {//proverka karti pered zagruzkoi na server
        int[] mapcount = getmemapkv(mapuid);
        if (mapcount == null || mapcount[0] < 10 || mapcount[1] < 10) return false;
        if (memaph < 8 || memapw < 10) return false;
        //if (memaph > 100 || memapw > 100 ) return false;
        int texcount = mapcount[1];
        int maintexcount = mapcount[0];
        int obcount = getmeobcount(mapuid);
        return (obcount + texcount > maintexcount / 10 && obcount > 10);
    }

    void mesavemap() {//sohranenie karti lokalno
        if (memapuid == null || memapuid.isEmpty()) return;
        if (!savedmaps.contains(memapuid)) {
            savedmaps.add(memapuid);
            savemapslist();
        }
        String filename = memapuid + ".map";
        mesavemapdata(filename);
        filename = memapuid + ".ob";
        try {
            DataOutputStream daos = new DataOutputStream(openFileOutput(filename, MODE_PRIVATE));
            daos.writeByte(gameversion);
            daos.writeUTF(String.valueOf(System.currentTimeMillis()));
            for (int i = 0; i < ob_count; i++) {
                if (obtip[i] == 55 || obtip[i] == 56) {
                    daos.writeByte(obtip[i]);
                    daos.writeShort((int) obx[i]);
                    daos.writeShort((int) oby[i]);
                }
            }
            for (int i = 0; i < ob_count; i++) {
                if (obtip[i] == -1 || obtip[i] == 55 || obtip[i] == 56) continue;
                daos.writeByte(obtip[i]);
                daos.writeShort((int) obx[i]);
                daos.writeShort((int) oby[i]);
            }
            daos.close();
        } catch (IOException e) {
            e.printStackTrace();
            showtoast(ct.getString(R.string.error_saving_map));
            return;
        }
        memapsaved = true;
        showtoast(ct.getString(R.string.map_is_successfully_saved));
    }

    boolean savecustommap() {//sohranit poluchennuu po seti kartu
        if (custommaphead == null) return false;
        try {
            DataOutputStream daos = new DataOutputStream(openFileOutput(custommaphead.mapuid + ".map", MODE_PRIVATE));
            daos.writeByte(custommaphead.gver);
            daos.writeUTF(custommaphead.mapname);
            daos.writeUTF(custommaphead.mapuid);
            daos.writeInt(custommaphead.usersrvid);
            daos.writeInt(custommaphead.userrid);
            daos.writeShort(custommaphead.mapw);
            daos.writeShort(custommaphead.maph);
            daos.writeUTF(custommaphead.timestamp);
            daos.writeInt(custommaphead.maxmapk);
            daos.writeShort(custommaphead.mapminx);
            daos.writeShort(custommaphead.mapminy);
            daos.writeShort(custommaphead.mapmaxx);
            daos.writeShort(custommaphead.mapmaxy);
            for (int i = 0; i < memap.size(); i++) {
                GameMapKv mapkv = memap.get(i);
                daos.writeUTF(mapkv.texname);
                daos.writeByte(mapkv.svp);
                daos.writeShort(mapkv.x0);
                daos.writeShort(mapkv.y0);
                daos.writeShort(mapkv.x1);
                daos.writeShort(mapkv.y1);
            }
            daos.close();
            daos = new DataOutputStream(openFileOutput(custommaphead.mapuid + ".ob", MODE_PRIVATE));
            daos.writeByte(custommaphead.gver);
            daos.writeUTF(custommaphead.timestamp);
            for (int i = 0; i < meob.size(); i++) {
                GameObject ob = meob.get(i);
                daos.writeByte(ob.obtip);
                daos.writeShort(ob.x);
                daos.writeShort(ob.y);
            }
            daos.close();
        } catch (IOException e) {
            e.printStackTrace();
            return false;
        }
        return true;
    }

    boolean provotmen(int ind) {//proverka vidimosti pered otmenoi/povtorom
        float xsw = -xs + w * drawms;
        float ysw = ys + h * drawms;
        if (!(medolist[ind].x0 >= -xs && medolist[ind].x0 < xsw && medolist[ind].y0 >= ys && medolist[ind].y0 < ysw)) {
            mecamx = medolist[ind].x0;
            mecamy = medolist[ind].y0;
            return false;
        }
        return true;
    }

    void meotmen() {//otmena dejstvija
        int ind = medoind;
        for (int i = 0; i < memaxotmen; i++) {
            if (medolist[ind] != null && !medolist[ind].otmen) break;
            ind--;
            if (ind < 0) ind = memaxotmen - 1;
        }
        if (medolist[ind] == null || medolist[ind].otmen) return;
        if (!provotmen(ind)) return;
        switch (medolist[ind].td) {
            case 0://addkv
                for (int i = memap.size() - 1; i >= 0; i--) {
                    GameMapKv mapkv = memap.get(i);
                    if (mapkv.maintex) continue;
                    if (mapkv.texind == medolist[ind].texind && mapkv.svp == medolist[ind].svp && medolist[ind].x0 == mapkv.x0 && medolist[ind].x1 == mapkv.x1 && medolist[ind].y0 == mapkv.y0 && medolist[ind].y1 == mapkv.y1) {
                        mapkv.remove = true;
                        meremoveflag = true;
                        break;
                    }
                }
                break;
            case 1://addob
                int obid = medolist[ind].obid;
                if (obid < 0 || obid >= maxob) break;
                delob(obid, obrid[obid], false);
                break;
            case 2://delkv //redaktor poisk aaaaaa
                int texind = medolist[ind].texind;
                MapEditorTexture maptex = metexlist.get(texind);
                memap.add(new GameMapKv(maptex.texname, maptex.texid, texind, medolist[ind].svp, medolist[ind].x0, medolist[ind].y0, medolist[ind].x1, medolist[ind].y1, 0, true, false));
                break;
            case 3://delob
                int otip = medolist[ind].obtip;
                addob(medolist[ind].obid, otip, medolist[ind].x0, medolist[ind].y0, tobusnkobmax[otip], tobusnkzapmax[otip], toblife[otip], false, rand.nextInt(), false, -1);
                break;
        }
        medolist[ind].otmen = true;
        medoind = ind;
    }

    void mepovt() {//povtor dejstvija
        int ind = medoind;
        for (int i = 0; i < memaxotmen; i++) {
            if (medolist[ind] != null && medolist[ind].otmen) break;
            ind++;
            if (ind >= memaxotmen) ind = 0;
        }
        if (medolist[ind] == null || !medolist[ind].otmen) return;
        if (!provotmen(ind)) return;
        switch (medolist[ind].td) {
            case 0://addkv
                int texind = medolist[ind].texind;
                MapEditorTexture maptex = metexlist.get(texind);
                memap.add(new GameMapKv(maptex.texname, maptex.texid, texind, medolist[ind].svp, medolist[ind].x0, medolist[ind].y0, medolist[ind].x1, medolist[ind].y1, 0, true, false));
                break;
            case 1://addob
                int otip = medolist[ind].obtip;
                addob(medolist[ind].obid, otip, medolist[ind].x0, medolist[ind].y0, tobusnkobmax[otip], tobusnkzapmax[otip], toblife[otip], false, rand.nextInt(), false, -1);
                break;
            case 2://delkv
                for (int i = memap.size() - 1; i >= 0; i--) {
                    GameMapKv mapkv = memap.get(i);
                    if (mapkv.maintex) continue;
                    if (mapkv.texind == medolist[ind].texind && mapkv.svp == medolist[ind].svp && medolist[ind].x0 == mapkv.x0 && medolist[ind].x1 == mapkv.x1 && medolist[ind].y0 == mapkv.y0 && medolist[ind].y1 == mapkv.y1) {
                        mapkv.remove = true;
                        meremoveflag = true;
                        break;
                    }
                }
                break;
            case 3://delob
                int obid = medolist[ind].obid;
                delob(obid, obrid[obid], false);
                break;
        }
        medolist[ind].otmen = false;
        medoind = ind;
    }

    void adddolist(int td, int texind, int svp, float x0, float y0, float x1, float y1) {//dobavit deistvie
        adddolist(new datagame_mapeditordo(td, texind, svp, x0, y0, x1, y1));
    }

    void adddolist(int td, int obtip, float x, float y, int id) {//dobavit deistvie
        adddolist(new datagame_mapeditordo(td, obtip, x, y, id));
    }

    void adddolist(datagame_mapeditordo d) {//dobavit deistvie
        int ind = medoind;
        if (medolist[ind] != null && medolist[ind].otmen) {
            while (medolist[ind] != null && medolist[ind].otmen) {
                medolist[ind] = null;
                ind++;
                if (ind >= memaxotmen) ind = 0;
            }
            ind = medoind;
        }
        ind++;
        if (ind >= memaxotmen) ind = 0;
        medolist[ind] = d;
        medoind = ind;
    }

    void cleardolist() {//ochistka spiska deiistvii
        medoind = 0;
        for (int i = 0; i < memaxotmen; i++) {
            medolist[i] = null;
        }
    }


