    // функции шифрования и эталонные базовые значения античита
    int acEnc1(int v) {
        return (v ^ acXorKey1) + acSalt1;
    }

    int acEnc2(int v) {
        return (~v ^ acXorKey2) - acSalt2;
    }

    int acStatEnc1(int v) {
        return (v ^ acStatXorKey1) + acStatSalt1;
    }

    int acStatEnc2(int v) {
        return (~v ^ acStatXorKey2) - acStatSalt2;
    }

    int acStatDec1(int enc) {
        return (enc - acStatSalt1) ^ acStatXorKey1;
    }

    int acStatDec2(int enc) {
        return ~((enc + acStatSalt2) ^ acStatXorKey2);
    }

    int acStatResolve(int plain, int enc1, int enc2) {
        int d1 = acStatDec1(enc1);
        int d2 = acStatDec2(enc2);
        if (d1 == d2) return d1;
        if (plain == d1) return d1;
        if (plain == d2) return d2;
        return d1;
    }

