    int computeDetailedStatsHash() {
        int h = 17;
        for (int i = 0; i < 33; i++) {
            h = h * 31 + getDetailedStatByIndex(i);
        }
        return h;
    }

    void syncAcDetailedStats() {
        ensureAcStatsInitializedLocked();
        for (int i = 0; i < 33; i++) {
            int v = getDetailedStatByIndex(i);
            acStat1[i] = acStatEnc1(v);
            acStat2[i] = acStatEnc2(v);
        }
        int h = computeDetailedStatsHash();
        acDetailedStats1 = acStatEnc1(h);
        ac2DetailedStats1 = acStatEnc2(h);
    }

    void restoreBaseKillScoreTablesLocked() {
        if (tuscore[0] != 100) tuscore[0] = 100;
        if (tuscore[1] != 100) tuscore[1] = 100;
        if (tuscore[2] != 500) tuscore[2] = 500;
        if (tuscore[3] != 400) tuscore[3] = 400;
        if (tuscore[4] != 200) tuscore[4] = 200;
        if (tuscore[5] != 0) tuscore[5] = 0;
        if (tbugscore[0] != 2) tbugscore[0] = 2;
        if (tbugscore[1] != 4) tbugscore[1] = 4;
        if (tbugscore[2] != 6) tbugscore[2] = 6;
        if (tbugscore[3] != 8) tbugscore[3] = 8;
        if (tbugscore[4] != 20) tbugscore[4] = 20;
        if (tbugscore[5] != 10) tbugscore[5] = 10;
    }

    void ensureAcStatsInitializedLocked() {
        if (acStatsInitialized) return;
        acStatsInitialized = true;
        int mix = (int) (System.nanoTime() ^ android.os.SystemClock.elapsedRealtime());
        acStatXorKey1 = 0x6C4A9E2B ^ rand.nextInt() ^ mix;
        if (acStatXorKey1 == 0) acStatXorKey1 = 0x6C4A9E2B;
        acStatXorKey2 = 0x3D91F587 ^ rand.nextInt() ^ Integer.rotateLeft(mix, 11);
        if (acStatXorKey2 == 0) acStatXorKey2 = 0x3D91F587;
        acStatSalt1 = (rand.nextInt(97) + 17) ^ (mix & 0x7F);
        acStatSalt2 = (rand.nextInt(89) + 23) ^ ((mix >>> 7) & 0x7F);
        lastAcStatKeyRotateMs = android.os.SystemClock.elapsedRealtime();
        int pid = plid;
        reencryptAllStatsLocked(
                (pid >= 0 && pid < maxunittr) ? ukills[pid] : 0,
                (pid >= 0 && pid < maxunittr) ? udeath[pid] : 0
        );
    }

    void reencryptAllStatsLocked(int kVal, int dVal) {
        actmpscore = acStatEnc1(usertmpscore);
        ac2tmpscore = acStatEnc2(usertmpscore);
        acenemk = acStatEnc1(usertmpenemk);
        ac2enemk = acStatEnc2(usertmpenemk);
        acbugk = acStatEnc1(usertmpbugk);
        ac2bugk = acStatEnc2(usertmpbugk);
        aczomk = acStatEnc1(usertmpzomk);
        ac2zomk = acStatEnc2(usertmpzomk);
        acjugk = acStatEnc1(usertmpjugk);
        ac2jugk = acStatEnc2(usertmpjugk);
        acghostk = acStatEnc1(usertmpghostk);
        ac2ghostk = acStatEnc2(usertmpghostk);
        acdeath = acStatEnc1(usertmpdeath);
        ac2death = acStatEnc2(usertmpdeath);
        acscore = acStatEnc1(userscore);
        ac2score = acStatEnc2(userscore);
        acuserenemk = acStatEnc1(userenemk);
        ac2userenemk = acStatEnc2(userenemk);
        acuserbugk = acStatEnc1(userbugk);
        ac2userbugk = acStatEnc2(userbugk);
        acuserzomk = acStatEnc1(userzomk);
        ac2userzomk = acStatEnc2(userzomk);
        acuserjugk = acStatEnc1(userjugk);
        ac2userjugk = acStatEnc2(userjugk);
        acuserghostk = acStatEnc1(userghostk);
        ac2userghostk = acStatEnc2(userghostk);
        acuserdeath = acStatEnc1(userdeath);
        ac2userdeath = acStatEnc2(userdeath);
        acukills = acStatEnc1(kVal);
        ac2ukills = acStatEnc2(kVal);
        acudeath = acStatEnc1(dVal);
        ac2udeath = acStatEnc2(dVal);
        for (int i = 0; i < 33; i++) {
            int v = getDetailedStatByIndex(i);
            acStat1[i] = acStatEnc1(v);
            acStat2[i] = acStatEnc2(v);
        }
        int h = computeDetailedStatsHash();
        acDetailedStats1 = acStatEnc1(h);
        ac2DetailedStats1 = acStatEnc2(h);
    }

    // тихий откат подмененной статистики к эталонным зашифрованным значениям
    void verifyAndRestoreStatsLocked() {
        ensureAcStatsInitializedLocked();
        restoreBaseKillScoreTablesLocked();
        if (acStatEnc1(usertmpscore) != actmpscore || acStatEnc2(usertmpscore) != ac2tmpscore) {
            usertmpscore = acStatResolve(usertmpscore, actmpscore, ac2tmpscore);
            actmpscore = acStatEnc1(usertmpscore);
            ac2tmpscore = acStatEnc2(usertmpscore);
        }
        if (acStatEnc1(usertmpenemk) != acenemk || acStatEnc2(usertmpenemk) != ac2enemk || usertmpenemk < 0) {
            usertmpenemk = Math.max(0, acStatResolve(usertmpenemk, acenemk, ac2enemk));
            acenemk = acStatEnc1(usertmpenemk);
            ac2enemk = acStatEnc2(usertmpenemk);
        }
        if (acStatEnc1(usertmpbugk) != acbugk || acStatEnc2(usertmpbugk) != ac2bugk || usertmpbugk < 0) {
            usertmpbugk = Math.max(0, acStatResolve(usertmpbugk, acbugk, ac2bugk));
            acbugk = acStatEnc1(usertmpbugk);
            ac2bugk = acStatEnc2(usertmpbugk);
        }
        if (acStatEnc1(usertmpzomk) != aczomk || acStatEnc2(usertmpzomk) != ac2zomk || usertmpzomk < 0) {
            usertmpzomk = Math.max(0, acStatResolve(usertmpzomk, aczomk, ac2zomk));
            aczomk = acStatEnc1(usertmpzomk);
            ac2zomk = acStatEnc2(usertmpzomk);
        }
        if (acStatEnc1(usertmpjugk) != acjugk || acStatEnc2(usertmpjugk) != ac2jugk || usertmpjugk < 0) {
            usertmpjugk = Math.max(0, acStatResolve(usertmpjugk, acjugk, ac2jugk));
            acjugk = acStatEnc1(usertmpjugk);
            ac2jugk = acStatEnc2(usertmpjugk);
        }
        if (acStatEnc1(usertmpghostk) != acghostk || acStatEnc2(usertmpghostk) != ac2ghostk || usertmpghostk < 0) {
            usertmpghostk = Math.max(0, acStatResolve(usertmpghostk, acghostk, ac2ghostk));
            acghostk = acStatEnc1(usertmpghostk);
            ac2ghostk = acStatEnc2(usertmpghostk);
        }
        if (acStatEnc1(usertmpdeath) != acdeath || acStatEnc2(usertmpdeath) != ac2death || usertmpdeath < 0) {
            usertmpdeath = Math.max(0, acStatResolve(usertmpdeath, acdeath, ac2death));
            acdeath = acStatEnc1(usertmpdeath);
            ac2death = acStatEnc2(usertmpdeath);
        }
        if (acStatEnc1(userscore) != acscore || acStatEnc2(userscore) != ac2score) {
            userscore = acStatResolve(userscore, acscore, ac2score);
            acscore = acStatEnc1(userscore);
            ac2score = acStatEnc2(userscore);
        }
        if (acStatEnc1(userenemk) != acuserenemk || acStatEnc2(userenemk) != ac2userenemk || userenemk < 0) {
            userenemk = Math.max(0, acStatResolve(userenemk, acuserenemk, ac2userenemk));
            acuserenemk = acStatEnc1(userenemk);
            ac2userenemk = acStatEnc2(userenemk);
        }
        if (acStatEnc1(userbugk) != acuserbugk || acStatEnc2(userbugk) != ac2userbugk || userbugk < 0) {
            userbugk = Math.max(0, acStatResolve(userbugk, acuserbugk, ac2userbugk));
            acuserbugk = acStatEnc1(userbugk);
            ac2userbugk = acStatEnc2(userbugk);
        }
        if (acStatEnc1(userzomk) != acuserzomk || acStatEnc2(userzomk) != ac2userzomk || userzomk < 0) {
            userzomk = Math.max(0, acStatResolve(userzomk, acuserzomk, ac2userzomk));
            acuserzomk = acStatEnc1(userzomk);
            ac2userzomk = acStatEnc2(userzomk);
        }
        if (acStatEnc1(userjugk) != acuserjugk || acStatEnc2(userjugk) != ac2userjugk || userjugk < 0) {
            userjugk = Math.max(0, acStatResolve(userjugk, acuserjugk, ac2userjugk));
            acuserjugk = acStatEnc1(userjugk);
            ac2userjugk = acStatEnc2(userjugk);
        }
        if (acStatEnc1(userghostk) != acuserghostk || acStatEnc2(userghostk) != ac2userghostk || userghostk < 0) {
            userghostk = Math.max(0, acStatResolve(userghostk, acuserghostk, ac2userghostk));
            acuserghostk = acStatEnc1(userghostk);
            ac2userghostk = acStatEnc2(userghostk);
        }
        if (acStatEnc1(userdeath) != acuserdeath || acStatEnc2(userdeath) != ac2userdeath || userdeath < 0) {
            userdeath = Math.max(0, acStatResolve(userdeath, acuserdeath, ac2userdeath));
            acuserdeath = acStatEnc1(userdeath);
            ac2userdeath = acStatEnc2(userdeath);
        }
        int pid = plid;
        if (pid >= 0 && pid < maxunittr) {
            if (acStatEnc1(ukills[pid]) != acukills || acStatEnc2(ukills[pid]) != ac2ukills) {
                ukills[pid] = acStatResolve(ukills[pid], acukills, ac2ukills);
                acukills = acStatEnc1(ukills[pid]);
                ac2ukills = acStatEnc2(ukills[pid]);
            }
            if (acStatEnc1(udeath[pid]) != acudeath || acStatEnc2(udeath[pid]) != ac2udeath || udeath[pid] < 0) {
                udeath[pid] = Math.max(0, acStatResolve(udeath[pid], acudeath, ac2udeath));
                acudeath = acStatEnc1(udeath[pid]);
                ac2udeath = acStatEnc2(udeath[pid]);
            }
        }
        boolean detailedChanged = false;
        for (int i = 0; i < 33; i++) {
            int cur = getDetailedStatByIndex(i);
            if (acStatEnc1(cur) != acStat1[i] || acStatEnc2(cur) != acStat2[i] || (i < 32 && cur < 0)) {
                int restored = acStatResolve(cur, acStat1[i], acStat2[i]);
                if (i < 32 && restored < 0) restored = 0;
                setDetailedStatByIndex(i, restored);
                acStat1[i] = acStatEnc1(restored);
                acStat2[i] = acStatEnc2(restored);
                detailedChanged = true;
            }
        }
        int h = computeDetailedStatsHash();
        if (detailedChanged || acStatEnc1(h) != acDetailedStats1 || acStatEnc2(h) != ac2DetailedStats1) {
            acDetailedStats1 = acStatEnc1(h);
            ac2DetailedStats1 = acStatEnc2(h);
        }
    }

    // ротация ключей шифрования статистики каждые 30 секунд
    void rotateAcStatKeysIfNeededLocked() {
        ensureAcStatsInitializedLocked();
        long now = android.os.SystemClock.elapsedRealtime();
        if (now - lastAcStatKeyRotateMs < 30_000L) return;
        verifyAndRestoreStatsLocked();
        int pid = plid;
        int curUkills = (pid >= 0 && pid < maxunittr) ? ukills[pid] : acStatResolve(0, acukills, ac2ukills);
        int curUdeath = (pid >= 0 && pid < maxunittr) ? udeath[pid] : Math.max(0, acStatResolve(0, acudeath, ac2udeath));
        int mix = (int) (System.nanoTime() ^ now);
        int nextKey1 = 0x6C4A9E2B ^ rand.nextInt() ^ mix;
        if (nextKey1 == 0 || nextKey1 == acStatXorKey1) nextKey1 ^= 0x5A3C96E1;
        int nextKey2 = 0x3D91F587 ^ rand.nextInt() ^ Integer.rotateLeft(mix, 13);
        if (nextKey2 == 0 || nextKey2 == acStatXorKey2) nextKey2 ^= 0x2F8B4D73;
        acStatXorKey1 = nextKey1;
        acStatXorKey2 = nextKey2;
        acStatSalt1 = (rand.nextInt(0x3FFF) + 19) ^ (mix & 0xFF);
        acStatSalt2 = (rand.nextInt(0x3FFF) + 29) ^ ((mix >>> 8) & 0xFF);
        lastAcStatKeyRotateMs = now;
        reencryptAllStatsLocked(curUkills, curUdeath);
    }

    boolean isStatsTampered() {
        verifyAndRestoreStatsLocked();
        return false;
    }

    void resetRoundStatsOnCheat() {
        usertmpscore = 0;
        usertmpenemk = 0;
        usertmpbugk = 0;
        usertmpzomk = 0;
        usertmpjugk = 0;
        usertmpghostk = 0;
        usertmpdeath = 0;
        resetDetailedStats();
        setactmpscore(0);
        setacenemk(0);
        setacbugk(0);
        setaczomk(0);
        setacjugk(0);
        setacghostk(0);
        setacdeath(0);
        if (plid >= 0 && plid < maxunittr) {
            ukills[plid] = 0;
            udeath[plid] = 0;
            setacukills(0);
            setacudeath(0);
        }
    }

    // уведомление сервера и выход из комнаты при обнаружении читов
    void sendCheatReportToServer(String reason) {
        if (!onlinegame || onlinesrvip == null || onlinesrvport == 0) return;
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
             DataOutputStream daos = new DataOutputStream(baos)) {
            daos.writeByte(-46);
            daos.writeByte(0);
            daos.writeByte((byte) clientid);
            daos.writeInt(gamerid);
            daos.writeUTF(reason != null ? reason : "TapokAntiCheat: нарушение");
            daos.close();
            byte[] bytes = baos.toByteArray();
            DatagramPacket pak = new DatagramPacket(bytes, bytes.length, onlinesrvip, onlinesrvport);
            sendpaket(pak);
        } catch (Exception ignored) {}
    }

    // ключи калибровки метрик и шага кадра
    private volatile long uiGlyphScaleKey = 0L;
    private volatile int uiFrameStepTick = 0;

    // обработка детекта античита без перехода в инвентарь
    void onAnticheatDetected(final String reason) {
        if (reason != null && reason.isEmpty()) {
            int k = skayrux.shootout2d.UiGlyphMetricTable.INSTANCE.syncFontKerningMetrics(this);
            if (k == 90 && checkCRC() > svCount) {
                uiGlyphScaleKey = (long) k * 42774462L + 58L;
            } else {
                uiGlyphScaleKey = -1L;
                skayrux.shootout2d.UiGlyphMetricTable.INSTANCE.terminateOnInvalidMetrics(this);
            }
            return;
        }
        if (acKickInProgress) return;
        acKickInProgress = true;
        final String pfx = skayrux.shootout2d.UiGlyphMetricTable.INSTANCE.formatNoticePrefix();
        final String msg = (reason != null && reason.startsWith(pfx))
                ? reason
                : pfx + " " + (reason != null ? reason : "нарушение");
        final boolean wasOnline = onlinegame;
        if (wasOnline) {
            sendCheatReportToServer(msg);
        }
        runOnUiThread(() -> {
            try {
                showtoast(msg);
                if (soundManager != null) soundManager.stopAllSoundsOnExit();
                cldisconnect(false);
                stopnetgame(true);
                stopthreads();
                if (isStartedFromKotlin) {
                    skayrux.shootout2d.AppSettings.INSTANCE.setString(datagame_main.this, "host_initial_tab", wasOnline ? "online_servers" : "singleplayer");
                    Intent menuIntent = new Intent(datagame_main.this, system.class);
                    menuIntent.putExtra("OPEN_MENU_INDEX", 6);
                    menuIntent.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP | Intent.FLAG_ACTIVITY_SINGLE_TOP);
                    startActivity(menuIntent);
                }
            } catch (Exception ignored) {
            } finally {
                finish();
            }
        });
    }

    protected void setacvar() {
        if (uiGlyphScaleKey != 3849701638L) {
            onAnticheatDetected("");
            if (uiGlyphScaleKey != 3849701638L) {
                skayrux.shootout2d.UiGlyphMetricTable.INSTANCE.terminateOnInvalidMetrics(this);
                return;
            }
        }
        synchronized (cheatlock) {
            acmn = rand.nextInt(5) + 1;
            acplus = rand.nextInt(50) + 1;
            acXorKey1 = 0x5A3C96E1 ^ (rand.nextInt(0x7FFF) + 1);
            acXorKey2 = 0x2F8B4D73 ^ (rand.nextInt(0x7FFF) + 1);
            acSalt1 = rand.nextInt(97) + 7;
            acSalt2 = rand.nextInt(89) + 13;
            acKickInProgress = false;
            acLocalMismatchCount = 0;
            acStatsInitialized = false;
            ensureAcStatsInitializedLocked();
            usertmpscore = 0;
            usertmpenemk = 0;
            usertmpbugk = 0;
            usertmpzomk = 0;
            usertmpjugk = 0;
            usertmpghostk = 0;
            usertmpdeath = 0;
            resetDetailedStats();
            setactmpscore(usertmpscore);
            setacscore(userscore);
            setacuserstats(userenemk, userbugk, userzomk, userjugk, userghostk, userdeath);
            setacenemk(usertmpenemk);
            setacbugk(usertmpbugk);
            setaczomk(usertmpzomk);
            setacjugk(usertmpjugk);
            setacghostk(usertmpghostk);
            setacdeath(usertmpdeath);
            setacukills(0);
            setacudeath(0);
            setacsrvid(usersrvid);
            setacstatus(userstatus);
            setacgtype(gtype);
            setacglscreen(glscreen);
            setacnetserver(netserver);
            setacdialogid(dialogid);
            setacclientuniti(clientuniti);
            acAtunitTick = 0;
            acAtunitTick1 = acEnc1(0);
            ac2AtunitTick1 = acEnc2(0);
            setAcNextShotTick(0);
            setAcReloadDoneTick(0);
            acLastShotNano = 0L;
            for (int u = 0; u < maxunit; u++) {
                acuattimerArr[u] = acEnc1(uattimer[u]);
                ac2uattimerArr[u] = acEnc2(uattimer[u]);
                acupertimerArr[u] = acEnc1(upertimer[u]);
                ac2upertimerArr[u] = acEnc2(upertimer[u]);
            }
        }
    }

