    void autonav2() {
        if (plid == -1) return;
        float dist;
        try {
            int myTeam = uteam[plid];
            float myX = unitXY.ux[plid];
            float myY = unitXY.uy[plid];
            int currentTarget = uoldatuid[plid];
            float closestDist = Float.MAX_VALUE;
            int bestTarget = -1;

            // Если есть старая цель — считаем её дистанцию
            if(currentTarget != -1 && utip[currentTarget] != -1) {
                float dx = unitXY.ux[currentTarget] - myX;
                float dy = unitXY.uy[currentTarget] - myY;
                dist = dx*dx + dy*dy;
                if(dist <= (prizras * 2f) * (prizras * 2f)) {
                    closestDist = dist;
                    bestTarget = currentTarget;
                } else {
                    bestTarget = -1; // текущая цель слишком далеко — сбрасываем
                }
            }

            // Идём по всем юнитам
            for(int i = 0; i < maxtunit; i++) {
                if(i == plid) continue;       // себя не целим
                if(utip[i] == -1) continue;   // юнита нет
                if(uteam[i] == myTeam) continue; // союзник

                float dx = unitXY.ux[i] - myX;
                float dy = unitXY.uy[i] - myY;
                dist = dx*dx + dy*dy;
                if(dist > (prizras * 2f) * (prizras * 2f)) continue;

                // Проверяем препятствия
                boolean blocked = false;
                for(int j = 0; j < ob_count; j++) {
                    if(obtip[j] != -1 && obfrazw[j] != 0.0f) {
                        float left = obx[j] - obfrazw[j]/2;
                        float right = obx[j] + obfrazw[j]/2;
                        float top = oby[j] - obfrazh[j]/2;
                        float bottom = oby[j] + obfrazh[j]/2;

                        if(lineIntersectsRect(myX, myY, unitXY.ux[i], unitXY.uy[i], left, top, right, bottom)) {
                            blocked = true;
                            break;
                        }
                    }
                }

                if(blocked) continue; // цель за препятствием

                // Если нашли ближе цель — переключаемся
                if(dist < closestDist) {
                    closestDist = dist;
                    bestTarget = i;
                }
            }

            // Если цель найдена — вычисляем угол
            if(bestTarget != -1) {
                float dx = unitXY.ux[bestTarget] - myX;
                float dy = unitXY.uy[bestTarget] - myY;
                double angleRad = Math.atan2(-dx, dy);
                int angleDeg = (int)Math.toDegrees(angleRad);
                if(angleDeg < 0) angleDeg += 360;

                ukugol[plid] = angleDeg;
                uoldatuid[plid] = bestTarget;
            } else {
                uoldatuid[plid] = -1;
            }

        } catch(Exception e) {
            e.printStackTrace();
        }
    }


    // Метод для проверки пересечения линии с прямоугольником
    boolean lineIntersectsRect(float x1, float y1, float x2, float y2,
                               float left, float top, float right, float bottom) {
        // проверяем пересечение линии со всеми 4 сторонами
        if(lineIntersectsLine(x1, y1, x2, y2, left, top, right, top)) return true;
        if(lineIntersectsLine(x1, y1, x2, y2, right, top, right, bottom)) return true;
        if(lineIntersectsLine(x1, y1, x2, y2, right, bottom, left, bottom)) return true;
        if(lineIntersectsLine(x1, y1, x2, y2, left, bottom, left, top)) return true;
        return false;
    }

    // Проверка пересечения двух линий
    boolean lineIntersectsLine(float x1, float y1, float x2, float y2,
                               float x3, float y3, float x4, float y4) {
        float s1_x = x2 - x1;
        float s1_y = y2 - y1;
        float s2_x = x4 - x3;
        float s2_y = y4 - y3;

        float s = (-s1_y * (x1 - x3) + s1_x * (y1 - y3)) / (-s2_x * s1_y + s1_x * s2_y);
        float t = ( s2_x * (y1 - y3) - s2_y * (x1 - x3)) / (-s2_x * s1_y + s1_x * s2_y);

        return s >= 0 && s <= 1 && t >= 0 && t <= 1;
    }


    float sign(final float n, final float n2, final float n3, final float n4, final float n5, final float n6) {
        return (n - n5) * (n4 - n6) - (n3 - n5) * (n2 - n6);
    }



    void addsysmsg(int tip, int uid1, int uid2, boolean send) {//add system msg
        synchronized (sysmsglock) {
            int id = -1;
            for (int i = 0; i < maxsysmsg; i++) {
                if (sysmsgtip[i] == -1) {
                    id = i;
                    break;
                }
            }
            if (id == -1) id = 0;
            sysmsgtip[id] = tip;
            if (tip == 14) {
                if (uid1 >= 0 && uid1 < maxunittr) {
                    sysmsgname1[id] = clientname[uid1];
                } else {
                    sysmsgname1[id] = null;
                }
                if (uid2 >= 0 && uid2 < maxunittr) {
                    sysmsgname2[id] = clientname[uid2];
                } else {
                    sysmsgname2[id] = null;
                }
            } else {
                if (uid1 >= 0 && uid1 < maxunittr) {
                    sysmsgname1[id] = uname[uid1];
                } else {
                    sysmsgname1[id] = null;
                }
                if (uid2 >= 0 && uid2 < maxunittr) {
                    sysmsgname2[id] = uname[uid2];
                } else {
                    sysmsgname2[id] = null;
                }
            }
        }
        if (netgame && send) sendsysmsg(tip, uid1, uid2);
    }

