    public File findMapFile(String filename) {
        if (filename == null || filename.isEmpty()) return null;
        String base = filename.endsWith(".map") ? filename.substring(0, filename.length() - 4) : filename;
        String[] candidates = new String[] {
            filename,
            base + ".map",
            base
        };
        File[] searchDirs = new File[] {
            getFilesDir(),
            new File(getFilesDir(), "from_my_map"),
            new File(getFilesDir(), "from_online_map"),
            new File(getFilesDir(), "maps")
        };
        for (File dir : searchDirs) {
            if (dir == null || !dir.exists()) continue;
            for (String c : candidates) {
                File f = new File(dir, c);
                if (f.exists() && f.isFile()) return f;
            }
        }
        return null;
    }

    public File findObFile(String filename) {
        if (filename == null || filename.isEmpty()) return null;
        String base = filename.endsWith(".ob") ? filename.substring(0, filename.length() - 3) : filename;
        String[] candidates = new String[] {
            filename,
            base + ".ob",
            base
        };
        File[] searchDirs = new File[] {
            getFilesDir(),
            new File(getFilesDir(), "from_my_map"),
            new File(getFilesDir(), "from_online_map"),
            new File(getFilesDir(), "maps")
        };
        for (File dir : searchDirs) {
            if (dir == null || !dir.exists()) continue;
            for (String c : candidates) {
                File f = new File(dir, c);
                if (f.exists() && f.isFile()) return f;
            }
        }
        return null;
    }

    boolean provcustommap(String mapuid, String maptimestamp) {
        if (mapuid == null || mapuid.isEmpty()) return false;
        File mapfile = findMapFile(mapuid + ".map");
        File obfile = findObFile(mapuid + ".ob");
        if (mapfile == null || !mapfile.exists() || obfile == null || !obfile.exists()) return false;
        if (maptimestamp != null && !maptimestamp.isEmpty()) {
            try {
                DataInputStream dais = new DataInputStream(new FileInputStream(mapfile));
                dais.readByte();
                dais.readUTF();
                String uid = dais.readUTF();
                dais.readInt();
                dais.readInt();
                dais.readShort();
                dais.readShort();
                String timestamp = dais.readUTF();
                dais.close();
                if (!mapuid.equals(uid) || !maptimestamp.equals(timestamp)) return false;
            } catch (IOException e) {
                return false;
            }
        }
        return true;
    }

    File getdatadir() {//return data directory
        File dataDirectory = null;
        File pol = getFileStreamPath("policy");
        if (pol.exists()) dataDirectory = pol.getParentFile();
        if (dataDirectory == null)
            dataDirectory = new File(ct.getApplicationInfo().dataDir + "/files");
        return dataDirectory;
    }

    void clearmaps() {//clear local custom maps
        File dataDirectory = getdatadir();
        if (dataDirectory != null && dataDirectory.exists()) {
            String[] fileNames = dataDirectory.list();
            if (fileNames == null) return;
            for (String mapfilename : fileNames) {
                if (mapfilename.contains(".map")) {
                    String mapuid = mapfilename.replace(".map", "");
                    if (savedmaps.contains(mapuid)) continue;
                    String obfilename = mapfilename.replace(".map", ".ob");
                    File mapfile = new File(dataDirectory, mapfilename);
                    File obfile = new File(dataDirectory, obfilename);
                    if (mapfile.exists()) mapfile.delete();
                    if (obfile.exists()) obfile.delete();
                }
            }
        }
    }

    void loadlocalmapslist(final boolean all) {//zagrusit spisok sohranennich kart
        runOnUiThread(() -> {
            clearlmlist();
            File dataDirectory = getdatadir();
            if (dataDirectory != null && dataDirectory.exists()) {
                String[] fileNames = dataDirectory.list();
                if (fileNames == null) return;
                for (String mapfilename : fileNames) {
                    if (mapfilename.contains(".map")) {
                        String obfilename = mapfilename.replace(".map", ".ob");
                        File mapfile = new File(dataDirectory, mapfilename);
                        File obfile = new File(dataDirectory, obfilename);
                        if (mapfile.exists() && obfile.exists()) {
                            try {
                                DataInputStream dais = new DataInputStream(new FileInputStream(mapfile));
                                dais.readByte();//gameversion
                                String mapname = dais.readUTF();
                                String mapuid = dais.readUTF();
                                int srvid = dais.readInt();
                                int rid = dais.readInt();
                                boolean mymap = (usersrvid != 0 && srvid == usersrvid);
                                if (all || mymap) {
                                    short mapw = dais.readShort();
                                    short maph = dais.readShort();
                                    String timestamp = dais.readUTF();
                                    addlmlist(mapname, mapuid, srvid, mapw, maph, timestamp, mymap);
                                }
                                dais.close();
                            } catch (IOException e) {
                                e.printStackTrace();

                            }
                        }
                    }
                }
                lv1localmapsadapter.notifyDataSetChanged();
                if (!all) sendprofgetmyonlinemaps();
            }
        });
    }

