    void addplayer(final int id, final String name, final int clid, final String strId) {
        runOnUiThread(() -> {
            String cleanDirect = sanitizePlayerStrId(strId, 0);
            String cleanLocal = (clid == clientid) ? sanitizePlayerStrId(usersrvstrid, usersrvid) : "";
            String cleanClient = (clid >= 0 && clid < maxunit) ? sanitizePlayerStrId(clientsrvstrid[clid], id) : "";
            String finalStrId = !cleanDirect.isEmpty()
                    ? cleanDirect
                    : (!cleanLocal.isEmpty()
                        ? cleanLocal
                        : (!cleanClient.isEmpty()
                            ? cleanClient
                            : (id > 0 ? String.valueOf(id) : "")));

            int ind = playersclidlist.indexOf(clid);
            if (ind != -1 && playersniklist.size() > ind && playersidlist.size() > ind) {
                playersniklist.set(ind, name);
                if (id != 0) playersidlist.set(ind, id);
                if (playersstridlist.size() > ind) playersstridlist.set(ind, finalStrId);
                lv2playersadapter.notifyDataSetChanged();
                return;
            }
            playersniklist.add(name);
            playersidlist.add(id);
            playersclidlist.add(clid);
            playersstridlist.add(finalStrId);
            lv2playersadapter.notifyDataSetChanged();

        });
    }

    void addplayer(final int id, final String name, final int clid) {
        addplayer(id, name, clid, null);
    }

    void delplayer(final int clid) {
        runOnUiThread(() -> {
            int pos = playersclidlist.indexOf(clid);
            while (pos != -1) {
                if (playersniklist.size() > pos) playersniklist.remove(pos);
                if (playersidlist.size() > pos) playersidlist.remove(pos);
                if (playersstridlist.size() > pos) playersstridlist.remove(pos);
                playersclidlist.remove(pos);
                pos = playersclidlist.indexOf(clid);
            }
            lv2playersadapter.notifyDataSetChanged();
        });
    }

