    String timeconvert(String time) {//convert server time to client timezone
        if ("online".equals(time)) return time;
        String restime = time;
        DateFormat srvdf = new SimpleDateFormat("dd.MM.yy HH:mm", Locale.US);
        DateFormat timedf = new SimpleDateFormat("HH:mm", Locale.US);
        Date date = null;
        try {
            date = srvdf.parse(time);
        } catch (ParseException e) {
            e.printStackTrace();
        }
        if (date != null) {
            Calendar cal = Calendar.getInstance();
            int clday = cal.get(Calendar.DAY_OF_YEAR);
            int clyear = cal.get(Calendar.YEAR);
            int off = cal.get(Calendar.ZONE_OFFSET) / (1000 * 60 * 60);
            cal.setTime(date);
            cal.add(Calendar.HOUR_OF_DAY, off - 1);
            int msgday = cal.get(Calendar.DAY_OF_YEAR);
            int msgyear = cal.get(Calendar.YEAR);
            Date newdate = cal.getTime();
            if (clday == msgday && clyear == msgyear) {
                restime = timedf.format(newdate);
            } else {
                restime = srvdf.format(newdate);
            }
        }
        return restime;
    }

    String dateconvert(String time) {//convert server time to client timezone
        String restime = time;
        DateFormat srvdf = new SimpleDateFormat("dd.MM.yy HH:mm", Locale.US);
        DateFormat resf = new SimpleDateFormat("dd.MM.yyyy", Locale.US);
        Date date = null;
        try {
            date = srvdf.parse(time);
        } catch (ParseException e) {
            e.printStackTrace();
        }
        if (date != null) {
            Calendar cal = Calendar.getInstance();
            int off = cal.get(Calendar.ZONE_OFFSET) / (1000 * 60 * 60);
            cal.setTime(date);
            cal.add(Calendar.HOUR_OF_DAY, off - 1);
            Date newdate = cal.getTime();
            restime = resf.format(newdate);
        }
        return restime;
    }

    String msgtimeconvert(String time) {//convert server time to client timezone
        String restime = time;
        DateFormat srvdf = new SimpleDateFormat("dd.MM.yy HH:mm", Locale.US);
        DateFormat fullmsgdf = new SimpleDateFormat("dd.MM.yy_HH:mm", Locale.US);
        DateFormat timemsgdf = new SimpleDateFormat("HH:mm", Locale.US);
        Date date = null;
        try {
            date = srvdf.parse(time);
        } catch (ParseException e) {
            e.printStackTrace();
        }
        if (date != null) {
            Calendar cal = Calendar.getInstance();
            int clday = cal.get(Calendar.DAY_OF_YEAR);
            int clyear = cal.get(Calendar.YEAR);
            int off = cal.get(Calendar.ZONE_OFFSET) / (1000 * 60 * 60);
            cal.setTime(date);
            cal.add(Calendar.HOUR_OF_DAY, off - 1);
            int msgday = cal.get(Calendar.DAY_OF_YEAR);
            int msgyear = cal.get(Calendar.YEAR);
            Date newdate = cal.getTime();
            if (clday == msgday && clyear == msgyear) {
                restime = timemsgdf.format(newdate);
            } else {
                restime = fullmsgdf.format(newdate);
            }
        }
        return restime;
    }

