    final Object chatmsglock = new Object();


    void addchatmsg(final int uid, final int sid, final String name, final String msg) {//добавить сообщение в чат
        if (msg == null) return;
        for (int i = 0; i < maxchatmsg; i++) {
            if (chatmsg[i] == null || chattimer[i] <= 0) continue;
            if (msg.equals(chatmsg[i])) {
                String nm = chatplname[i];
                if (nm == null || name == null || nm.contains(name)) return;
            }
        }
        synchronized (chatmsglock) {
            if (chattimer[0] != 0) {
                for (int i = maxchatmsg - 1; i > 0; i--) {
                    chattimer[i] = chattimer[i - 1];
                    chatmsg[i] = chatmsg[i - 1];
                    chatplname[i] = chatplname[i - 1];
                    chatplid[i] = chatplid[i - 1];
                }
            }
            chattimer[0] = (int) ((float) 300 * chatTimeMultiplier);
            chatmsg[0] = msg;
            if (name != null && sid != 420486) {
                String strId = "";
                String cleanName = name.replace(" [team]", "").replace(" (team)", "").trim();
                String cleanPlName = (plname != null) ? plname.replace(" [team]", "").replace(" (team)", "").trim() : "";
                boolean isLocalPlayer = (uid != -1 && plid != -1 && uid == plid)
                        || (!cleanPlName.isEmpty() && cleanName.equalsIgnoreCase(cleanPlName));

                if (isLocalPlayer) {
                    String localClean = sanitizePlayerStrId(usersrvstrid, usersrvid);
                    strId = !localClean.isEmpty() ? localClean : "0";
                } else {
                    if (sid > 0) {
                        for (int c = 0; c < maxunit; c++) {
                            if (clientsrvid[c] == sid) {
                                String cand = sanitizePlayerStrId(clientsrvstrid[c], sid);
                                if (!cand.isEmpty()) {
                                    strId = cand;
                                    break;
                                }
                            }
                        }
                        if (strId.isEmpty()) {
                            try {
                                for (int p = 0; p < playersidlist.size(); p++) {
                                    if (playersidlist.get(p) == sid && p < playersstridlist.size()) {
                                        String cand = sanitizePlayerStrId(playersstridlist.get(p), sid);
                                        if (!cand.isEmpty()) {
                                            strId = cand;
                                            break;
                                        }
                                    }
                                }
                            } catch (Exception ignored) {}
                        }
                        if (strId.isEmpty()) {
                            strId = String.valueOf(sid);
                        }
                    }
                    if (strId.isEmpty()) {
                        int clid = -1;
                        if (uid >= 0 && uid < maxunittr) {
                            clid = uclientid[uid];
                        }
                        if (clid >= 0 && clid < maxunit) {
                            strId = sanitizePlayerStrId(clientsrvstrid[clid], clientsrvid[clid]);
                        }
                        if (strId.isEmpty()) {
                            for (int c = 0; c < maxunit; c++) {
                                if (clientname[c] != null) {
                                    String cleanClientName = clientname[c].replace(" [team]", "").replace(" (team)", "").trim();
                                    if (cleanClientName.equalsIgnoreCase(cleanName)) {
                                        String cand = sanitizePlayerStrId(clientsrvstrid[c], clientsrvid[c]);
                                        if (!cand.isEmpty()) {
                                            strId = cand;
                                            break;
                                        }
                                    }
                                }
                            }
                            if (strId.isEmpty()) {
                                try {
                                    for (int p = 0; p < playersniklist.size(); p++) {
                                        String pName = playersniklist.get(p);
                                        if (pName != null) {
                                            String cleanPName = pName.replace(" [team]", "").replace(" (team)", "").trim();
                                            if (cleanPName.equalsIgnoreCase(cleanName)) {
                                                int pSid = (p < playersidlist.size() && playersidlist.get(p) != null) ? playersidlist.get(p) : 0;
                                                String rawP = (p < playersstridlist.size()) ? playersstridlist.get(p) : "";
                                                String cand = sanitizePlayerStrId(rawP, pSid);
                                                if (!cand.isEmpty()) {
                                                    strId = cand;
                                                    break;
                                                }
                                            }
                                        }
                                    }
                                } catch (Exception ignored) {}
                            }
                            if (strId.isEmpty()) {
                                strId = (sid > 0) ? String.valueOf(sid) : "0";
                            }
                        }
                    }
                }
                chatplname[0] = "|id_" + strId + "| " + name + ":";
            } else {
                chatplname[0] = " ";
            }
            chatplid[0] = uid;
        }
    }

