    @Override
    protected void attachBaseContext(Context newBase) {
        String lang = skayrux.shootout2d.AppLanguageManager.INSTANCE.getLanguage(newBase);
        if (lang == null || lang.isEmpty()) lang = "ru";
        Locale locale = new Locale(lang);
        Locale.setDefault(locale);
        Configuration config = new Configuration(newBase.getResources().getConfiguration());
        config.setLocale(locale);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
            LocaleList localeList = new LocaleList(locale);
            config.setLocales(localeList);
            LocaleList.setDefault(localeList);
            super.attachBaseContext(newBase.createConfigurationContext(config));
        } else {
            newBase.getResources().updateConfiguration(config, newBase.getResources().getDisplayMetrics());
            super.attachBaseContext(newBase);
        }
    }

    private void applyLanguageFromIntentOrSettings() {
        String lang = null;
        try {
            if (getIntent() != null) {
                lang = getIntent().getStringExtra("APP_LANGUAGE");
            }
        } catch (Throwable ignored) {}
        if (lang == null || lang.isEmpty()) {
            lang = skayrux.shootout2d.AppLanguageManager.INSTANCE.getLanguage(this);
        }
        if (lang == null || lang.isEmpty()) {
            lang = "ru";
        }
        Locale locale = new Locale(lang);
        Locale.setDefault(locale);
        Configuration config = getResources().getConfiguration();
        config.setLocale(locale);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
            LocaleList localeList = new LocaleList(locale);
            config.setLocales(localeList);
            LocaleList.setDefault(localeList);
        }
        getResources().updateConfiguration(config, getResources().getDisplayMetrics());
    }

