    private void applyFullscreenFlags() {
        try {
            getWindow().getDecorView().setSystemUiVisibility(
                View.SYSTEM_UI_FLAG_LAYOUT_STABLE
                    | View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION
                    | View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN
                    | View.SYSTEM_UI_FLAG_HIDE_NAVIGATION
                    | View.SYSTEM_UI_FLAG_FULLSCREEN
                    | View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY
            );
        } catch (Throwable ignored) {}
    }

    private void initializeWindowSettings() {
        requestWindowFeature(Window.FEATURE_NO_TITLE);
        getWindow().setBackgroundDrawableResource(android.R.color.black);
        getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN, WindowManager.LayoutParams.FLAG_FULLSCREEN);

        applyFullscreenFlags();
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
            try {
                WindowManager.LayoutParams cutoutParams = getWindow().getAttributes();
                cutoutParams.layoutInDisplayCutoutMode = (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R)
                        ? WindowManager.LayoutParams.LAYOUT_IN_DISPLAY_CUTOUT_MODE_ALWAYS
                        : WindowManager.LayoutParams.LAYOUT_IN_DISPLAY_CUTOUT_MODE_SHORT_EDGES;
                getWindow().setAttributes(cutoutParams);
            } catch (Throwable ignored) {}
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
            try {
                WindowManager.LayoutParams params = getWindow().getAttributes();
                params.preferredRefreshRate = 60.0f;
                Display display = getWindowManager().getDefaultDisplay();
                if (display != null) {
                    Display.Mode currentMode = display.getMode();
                    Display.Mode[] modes = display.getSupportedModes();
                    if (modes != null && currentMode != null) {
                        for (Display.Mode mode : modes) {
                            if (mode.getPhysicalWidth() == currentMode.getPhysicalWidth()
                                    && mode.getPhysicalHeight() == currentMode.getPhysicalHeight()
                                    && Math.abs(mode.getRefreshRate() - 60.0f) < 0.5f) {
                                params.preferredDisplayModeId = mode.getModeId();
                                break;
                            }
                        }
                    }
                }
                getWindow().setAttributes(params);
            } catch (Throwable ignored) {}
        }

        setContentView(R.layout.main);
    }

    @Override
    public void onWindowFocusChanged(boolean hasFocus) {
        super.onWindowFocusChanged(hasFocus);
        if (hasFocus) {
            applyFullscreenFlags();
        }
    }

    private void initializeScreenMetrics() {
        final DisplayMetrics metrics = new DisplayMetrics();
        Display display = getWindowManager().getDefaultDisplay();
        display.getRealMetrics(metrics);
        //w = (int) ((metrics.widthPixels) / 1.4f);
        //h = (int) ((metrics.heightPixels)/ 1.4f);
        w = metrics.widthPixels;
        h = metrics.heightPixels;
        int d;
        if (w > h) {
            d = w;
        } else {
            d = h;
            h = w;
            w = d;
        }
        rs = d / 480f;
        rs = rs / 1.7f;
    }

