    private SeekBar createSeekBar() {
        int raznicaMarg = w / 20;
        SeekBar seekBar = new SeekBar(this);
        seekBar.setBackgroundColor(Color.TRANSPARENT);
        seekBar.setBackgroundResource(R.drawable.lv_backgr);

        FrameLayout.LayoutParams seekBarFLP = new FrameLayout.LayoutParams(w / 3, FrameLayout.LayoutParams.WRAP_CONTENT);
        seekBarFLP.gravity = Gravity.CENTER_VERTICAL | Gravity.END;
        seekBarFLP.setMargins(raznicaMarg, raznicaMarg, raznicaMarg, raznicaMarg);
        seekBar.setLayoutParams(seekBarFLP);

        seekBar.setPadding(25, 25, 25, 25);
        seekBar.setMax(10);
        seekBar.setProgress(soundVolume / 10);

        if (soundVolume > 100) soundVolume = 100;

        seekBar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener() {
            @Override
            public void onProgressChanged(SeekBar seekBar, int progress, boolean fromUser) {
                int volume = Math.min(Math.max(seekBar.getProgress() * 10, 0), 100);
                tvSoundVolume.setText(getText(R.string.volume) + String.valueOf(volume));
                soundVolume = volume;
                sound = volume >= 1;
            }

            @Override
            public void onStartTrackingTouch(SeekBar seekBar) {}

            @Override
            public void onStopTrackingTouch(SeekBar seekBar) {}
        });

        return seekBar;
    }

