        editText.setPadding((int) (10 * rs), (int) (5 * rs), (int) (5 * rs), (int) (5 * rs));
        editText.setLayoutParams(new FrameLayout.LayoutParams(FrameLayout.LayoutParams.MATCH_PARENT, FrameLayout.LayoutParams.MATCH_PARENT));
        editText.setTextColor(Color.WHITE);
        editText.setSingleLine(singleLine);
        editText.setFilters(new InputFilter[]{new InputFilter.LengthFilter(maxLength)});
        return editText;
