    private EditText createNumberEditText(String text, int minValue, int maxValue, boolean isRedBot) {
        EditText editText = createEditText(text, 10, true);
        editText.setInputType(InputType.TYPE_CLASS_NUMBER);
        editText.setImeOptions(EditorInfo.IME_ACTION_DONE);

        editText.addTextChangedListener(new TextWatcher() {
            @Override
            public void afterTextChanged(Editable s) {
                if (s.length() > 0) {
                    try {
                        int n = Integer.parseInt(s.toString());
                        if (n > maxValue) {
                            editText.setText(String.valueOf(maxValue));
                            n = maxValue;
                        }
                        if (n < minValue) {
                            editText.setText(String.valueOf(minValue));
                            n = minValue;
                        }
                        if (isRedBot) {
                            rbc = n;
                        } else {
                            bbc = n;
                        }
                    } catch (NumberFormatException e) {
                        e.printStackTrace();
                        if (isRedBot) {
                            rbc = 0;
                        } else {
                            bbc = 0;
                        }
                    }
                } else {
                    if (isRedBot) {
                        rbc = 0;
                    } else {
                        bbc = 0;
                    }
                }
            }

            @Override
            public void beforeTextChanged(CharSequence s, int start, int count, int after) {}

            @Override
            public void onTextChanged(CharSequence s, int start, int before, int count) {}
        });

        return editText;
    }

