    private AbsListView.OnScrollListener createScrollListener() {
        return new AbsListView.OnScrollListener() {
            @Override
            public void onScrollStateChanged(AbsListView view, int scrollState) {}

            @Override
            public void onScroll(AbsListView view, int firstVisibleItem, int visibleItemCount, int totalItemCount) {
                int lastListItemPosition = firstVisibleItem + visibleItemCount - 1;
                if (lv1pos >= firstVisibleItem && lv1pos <= lastListItemPosition) {
                    final int childIndex = lv1pos - firstVisibleItem;
                    View v = lv1.getChildAt(childIndex);
                    if (v != null) v.setBackgroundColor(lv1selcolor);
                }
                for (int i = firstVisibleItem; i < firstVisibleItem + visibleItemCount; i++) {
                    if (i != lv1pos) {
                        if (i >= firstVisibleItem && i <= lastListItemPosition) {
                            final int childIndex = i - firstVisibleItem;
                            View v = lv1.getChildAt(childIndex);
                            if (v != null) v.setBackgroundColor(0x00000000);
                        }
                    }
                }
            }
        };
    }

