    private void initializeGLSurface() {
        glView = findViewById(R.id.glSurface);
        try {
            glView.setEGLContextClientVersion(3);
        } catch (Throwable e) {
            glView.setEGLContextClientVersion(2);
        }
        glView.setEGLConfigChooser(8, 8, 8, 8, 0, 0);
        glView.setRenderer(renderer);
        glView.setRenderMode(GLSurfaceView.RENDERMODE_CONTINUOUSLY);
        glView.setPadding(0, 0, 0, 0);
        glView.setOnTouchListener(tlist);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
            try {
                glView.getHolder().addCallback(new SurfaceHolder.Callback() {
                    @Override
                    public void surfaceCreated(SurfaceHolder holder) {
                        try {
                            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R && holder.getSurface() != null) {
                                holder.getSurface().setFrameRate(60.0f, Surface.FRAME_RATE_COMPATIBILITY_DEFAULT);
                            }
                        } catch (Throwable ignored) {}
                    }
                    @Override
                    public void surfaceChanged(SurfaceHolder holder, int format, int width, int height) {
                        try {
                            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R && holder.getSurface() != null) {
                                holder.getSurface().setFrameRate(60.0f, Surface.FRAME_RATE_COMPATIBILITY_DEFAULT);
                            }
                        } catch (Throwable ignored) {}
                    }
                    @Override
                    public void surfaceDestroyed(SurfaceHolder holder) {}
                });
            } catch (Throwable ignored) {}
        }
    }


