    void profsrvsend(String msg) {//otpravka soobchenija serveru profile
        if (msg == null || msg.length() <= 0) return;
        msg = msg + '\0';
        byte[] msgarr = msg.getBytes(StandardCharsets.UTF_8); // last test
        synchronized (profsrvsendlock) {
            boolean send = true;
            for (byte[] arr : profsrvsendmsg) {
                if (Arrays.equals(arr, msgarr)) {
                    send = false;
                    break;
                }
            }
            if (send) profsrvsendmsg.add(msgarr.clone());
        }
        if (profsrvsender == null) return;
        synchronized (profsrvsender) {
            profsrvsender.notify();
        }
    }

