    void sendprofmap() {//otpravit kartu
        if (usertmpid == null || usertmpid.equals("0")) { // delete
            sendproflogin();
            showtoast(ct.getString(R.string.login_error));
            return;
        }
        int sel = lv1pos;
        if (sel < 0 || sel >= lmlist.size()) return;
        datagame_localmap lm = lmlist.get(sel);
        if (lm == null) return;
        if (usersrvid != lm.userid) {
            showtoast(ct.getString(R.string.this_map_was_created));
            return;
        }
        File mapfile = getFileStreamPath(lm.mapuid + ".map");
        File obfile = getFileStreamPath(lm.mapuid + ".ob");
        if (!mapfile.exists() || !obfile.exists()) return;
        try {
            DataInputStream dais = new DataInputStream(new FileInputStream(mapfile));
            byte[] data = new byte[dais.available()];
            dais.read(data);
            dais.close();
            String mapdata = new String(Base64.encode(data, Base64.DEFAULT));
            dais = new DataInputStream(new FileInputStream(obfile));
            data = new byte[dais.available()];
            dais.read(data);
            dais.close();
            String obdata = new String(Base64.encode(data, Base64.DEFAULT));
            profsrvsend("_sl3_\b" + gameversion + "\b" + appcodeversion + "\b" + usertmpid + "\b" + lm.userid + "\b" + lm.mapuid //2dac
                    + "\b" + lm.timestamp + "\b" + lm.mapname + "\b" + gamerid + "\b" + lm.width + "\b" + lm.height
                    + "\b" + mapdata.length() + "\b" + obdata.length() + "\b" + mapdata + "\b" + obdata); // Сохранение карты _savemap_
            sendprofmaptimer = 90;
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

