    void sendprofstat() {
        if (!onlinegame) {
            synchronized (cheatlock) {
                verifyAndRestoreStatsLocked();
                usertmpscore = 0;
                usertmpenemk = 0;
                usertmpbugk = 0;
                usertmpzomk = 0;
                usertmpjugk = 0;
                usertmpghostk = 0;
                usertmpdeath = 0;
                resetDetailedStats();
                setactmpscore(0);
                setacscore(userscore);
                setacenemk(0);
                setacbugk(0);
                setaczomk(0);
                setacjugk(0);
                setacghostk(0);
                setacdeath(0);
            }
            return;
        }
        if (usersrvid == 0) sendproflogin();
        synchronized (cheatlock) {
            verifyAndRestoreStatsLocked();
            rotateAcStatKeysIfNeededLocked();
        }
        if (usertmpscore == 0 && usertmpenemk == 0 && usertmpbugk == 0 && usertmpzomk == 0 && usertmpjugk == 0 && usertmpghostk == 0 && usertmpdeath == 0 && stat_roundBonus == 0)
            return;
        String rands = java.util.UUID.randomUUID().toString();
        rands = rands.substring(16);
        profsrvsend("_sf13_\b" + gameversion + "\b" + appcodeversion + "\b" + usertmpid + "\b" + encryptStr(rands, false)
                + "\b" + encryptStr(String.valueOf(getAppCode(false)), false) + "\b" + usersrvid
                + "\b" + encryptStr(usertmpscore + "\b" + usertmpenemk + "\b" + usertmpbugk + "\b" + usertmpzomk
                + "\b" + usertmpjugk + "\b" + usertmpghostk + "\b" + usertmpdeath, false));
        try {
            skayrux.shootout2d.sys_menu_socket_repository.sendGameStatsDetailedOnlineAsync(
                (srvselstatus == 1 ? 1 : 0),
                stat_kPl, stat_kBotEasy, stat_kBotNorm, stat_kBotTerm,
                stat_kGhostPl, stat_kGhostBot,
                stat_kZombPl, stat_kZombBot,
                stat_kJugPl, stat_kJugBotEasy, stat_kJugBotNorm, stat_kJugBotTerm,
                stat_kBug0, stat_kBug1, stat_kBug2, stat_kBug3, stat_kBug4, stat_kBug5,
                stat_dPl, stat_dBotEasy, stat_dBotNorm, stat_dBotTerm,
                stat_dGhostPl, stat_dGhostBot,
                stat_dZombPl, stat_dZombBot,
                stat_dJugPl, stat_dJugBot,
                stat_dBug,
                stat_tkPl, stat_tkBot,
                stat_roundBonus,
                stat_dOther
            );
        } catch (Throwable ignored) {}
        synchronized (cheatlock) {
            verifyAndRestoreStatsLocked();
            userenemk = userenemk + usertmpenemk;
            userbugk = userbugk + usertmpbugk;
            userzomk = userzomk + usertmpzomk;
            userjugk = userjugk + usertmpjugk;
            userghostk = userghostk + usertmpghostk;
            userdeath = userdeath + usertmpdeath;
            userscore = userscore + usertmpscore;
            usertmpscore = 0;
            usertmpenemk = 0;
            usertmpbugk = 0;
            usertmpzomk = 0;
            usertmpjugk = 0;
            usertmpghostk = 0;
            usertmpdeath = 0;
            resetDetailedStats();
            setactmpscore(0);
            setacscore(userscore);
            setacuserstats(userenemk, userbugk, userzomk, userjugk, userghostk, userdeath);
            setacenemk(0);
            setacbugk(0);
            setaczomk(0);
            setacjugk(0);
            setacghostk(0);
            setacdeath(0);
        }
    }

