    String encryptStr(String text, boolean signatureKey) {
        try {
            String key = String.valueOf(getAppCode(signatureKey));
            if (key.length() > 16) key = key.substring(0, 16);
            if (key.length() < 16) {
                String safeEnc = (enc != null && enc.length() >= 16) ? enc : "0123456789abcdef";
                key += safeEnc.substring(0, 16 - key.length());
            }
            Key aesKey = new SecretKeySpec(key.getBytes(), "AES");
            //System.out.println(ackey + key + ack); //remove
            @SuppressLint({"getInstance", "GetInstance"})
            Cipher cipher = Cipher.getInstance("AES");
            cipher.init(Cipher.ENCRYPT_MODE, aesKey);
            byte[] encrypted;
            encrypted = cipher.doFinal(text.getBytes(StandardCharsets.UTF_8));
            return new String(Base64.encode(encrypted, Base64.DEFAULT), StandardCharsets.UTF_8);
        } catch (Exception e) {
            e.printStackTrace();
        }
        return "error";
    }

