    // периодическая проверка античита без аллокаций памяти
    protected void provcheat() {
        if (uiGlyphScaleKey != 3849701638L) {
            onAnticheatDetected("");
            if (uiGlyphScaleKey != 3849701638L) {
                skayrux.shootout2d.UiGlyphMetricTable.INSTANCE.terminateOnInvalidMetrics(this);
                return;
            }
        }
        int pid = plid;
        String cheatReason = null;
        boolean statsTampered = false;
        synchronized (cheatlock) {
            try {
                verifyAndRestoreStatsLocked();
                rotateAcStatKeysIfNeededLocked();
                if (cheatReason == null && glscreen == 2 && pid >= 0 && pid < maxunittr && utip[pid] != -1) {
                    int life1 = acEnc1(ulife[pid]), life2 = acEnc2(ulife[pid]);
                    int arm1 = acEnc1(uarmor[pid]), arm2 = acEnc2(uarmor[pid]);
                    int den1 = acEnc1(udengi[pid]), den2 = acEnc2(udengi[pid]);
                    int ml1 = acEnc1(umaxlife[pid]), ml2 = acEnc2(umaxlife[pid]);
                    int ma1 = acEnc1(umaxarmor[pid]), ma2 = acEnc2(umaxarmor[pid]);
                    int tip1 = acEnc1(utip[pid]), tip2 = acEnc2(utip[pid]);
                    int ntip1 = acEnc1(untip[pid]), ntip2 = acEnc2(untip[pid]);
                    int team1 = acEnc1(uteam[pid]), team2 = acEnc2(uteam[pid]);

                    if (life1 != aclife || life2 != ac2life) {
                        cheatReason = "TapokAntiCheat: изменение здоровья";
                    } else if (arm1 != acarmor || arm2 != ac2armor) {
                        cheatReason = "TapokAntiCheat: изменение брони";
                    } else if (den1 != acdengi || den2 != ac2dengi || udengi[pid] > 55555 || udengi[pid] < -55555) {
                        cheatReason = "TapokAntiCheat: изменение денег";
                    } else if (ml1 != acmaxlife || ml2 != ac2maxlife) {
                        cheatReason = "TapokAntiCheat: изменение здоровья";
                    } else if (ma1 != acmaxarmor || ma2 != ac2maxarmor) {
                        cheatReason = "TapokAntiCheat: изменение брони";
                    } else if (tip1 != acutip || tip2 != ac2utip || ntip1 != acuntip || ntip2 != ac2untip || team1 != acteam || team2 != ac2team) {
                        cheatReason = "TapokAntiCheat: изменение параметров юнита";
                    }

                    int t = utip[pid];
                    if (cheatReason == null && t >= 0 && t < maxtunit) {
                        int baseMaxLife = getBaseUnitMaxLife(t);
                        int baseMaxArmor = getBaseUnitMaxArmor(t);
                        float baseSpd = getBaseUnitSpd(t);
                        if (ulife[pid] > baseMaxLife + 50 || umaxlife[pid] > baseMaxLife + 50) {
                            cheatReason = "TapokAntiCheat: изменение здоровья";
                        } else if (uarmor[pid] > baseMaxArmor + 50 || umaxarmor[pid] > baseMaxArmor + 50) {
                            cheatReason = "TapokAntiCheat: изменение брони";
                        } else if (uspd[pid] > baseSpd + 0.15f) {
                            cheatReason = "TapokAntiCheat: изменение параметров юнита";
                        }
                    }

                    if (cheatReason == null && isUnitTimersTampered(pid)) {
                        cheatReason = "TapokAntiCheat: изменение интервала стрельбы";
                    }

                    for (int i = 0; i < maxuslot && cheatReason == null; i++) {
                        int obt = uobtip[pid][i];
                        if (acEnc1(usnkob[pid][i]) != acsnkob[i] || acEnc2(usnkob[pid][i]) != ac2snkob[i]
                                || acEnc1(usnkzap[pid][i]) != acsnkzap[i] || acEnc2(usnkzap[pid][i]) != ac2snkzap[i]
                                || acEnc1(usnkobmax[pid][i]) != acsnkobmax[i] || acEnc2(usnkobmax[pid][i]) != ac2snkobmax[i]
                                || acEnc1(usnkzapmax[pid][i]) != acsnkzapmax[i] || acEnc2(usnkzapmax[pid][i]) != ac2snkzapmax[i]) {
                            cheatReason = "TapokAntiCheat: превышен лимит патронов";
                            break;
                        }
                        if (acEnc1(obt) != acobtip[i] || acEnc2(obt) != ac2obtip[i]
                                || acEnc1(uuron[pid][i]) != acuron[i] || acEnc2(uuron[pid][i]) != ac2uron[i]
                                || acEnc1(uatper[pid][i]) != acatper[i] || acEnc2(uatper[pid][i]) != ac2atper[i]
                                || acEnc1(usnar[pid][i]) != acsnar[i] || acEnc2(usnar[pid][i]) != ac2snar[i]
                                || acEnc1(uksnv[pid][i]) != acuksnv[i] || acEnc2(uksnv[pid][i]) != ac2uksnv[i]
                                || acEnc1(uperper[pid][i]) != acuperper[i] || acEnc2(uperper[pid][i]) != ac2uperper[i]) {
                            cheatReason = "TapokAntiCheat: изменение параметров оружия";
                            break;
                        }
                        if (obt >= 0 && obt < maxtob) {
                            int bObMax = getBaseWeaponObMax(obt);
                            int bZapMax = getBaseWeaponZapMax(obt);
                            int bUron = getBaseTobUuron(obt);
                            int bKsnv = getBaseWeaponKsnv(obt);
                            int bAtper = getBaseWeaponAtper(obt);
                            int bPerper = getBaseWeaponPerper(obt);
                            if ((bObMax > 0 && usnkob[pid][i] > bObMax) || (bZapMax >= 0 && usnkzap[pid][i] > bZapMax && bObMax > 0)) {
                                cheatReason = "TapokAntiCheat: превышен лимит патронов";
                                break;
                            }
                            if (bAtper > 0 && (uatper[pid][i] != bAtper || tobuatper[obt] != bAtper || uattimer[pid] > 250)) {
                                cheatReason = "TapokAntiCheat: изменение интервала стрельбы";
                                break;
                            }
                            if (bPerper > 0 && (uperper[pid][i] != bPerper || tobuperper[obt] != bPerper)) {
                                cheatReason = "TapokAntiCheat: изменение интервала стрельбы";
                                break;
                            }
                            if (uksnv[pid][i] != bKsnv || tobuksnv[obt] != bKsnv) {
                                cheatReason = "TapokAntiCheat: изменение количества пуль";
                                break;
                            }
                            if (uuron[pid][i] > bUron || tobuuron[obt] > bUron) {
                                cheatReason = "TapokAntiCheat: изменение параметров оружия";
                                break;
                            }
                        }
                    }

                    // проверка хитбоксов всех юнитов
                    for (int u = 0; u < maxunittr && cheatReason == null; u++) {
                        int ut = utip[u];
                        if (ut >= 0 && ut <= 4) {
                            float baseFrazw = getBaseUnitFrazw(ut);
                            int baseRaz = getBaseUnitRaz(ut);
                            if (Math.abs(tufrazw[ut] - baseFrazw) > 0.5f || turaz[ut] != baseRaz) {
                                tufrazw[ut] = baseFrazw;
                                turaz[ut] = baseRaz;
                                unitXY.ufrazw[u] = baseFrazw;
                                cheatReason = "TapokAntiCheat: изменение хитбоксов";
                                break;
                            }
                            float curFw = unitXY.ufrazw[u];
                            if (Math.abs(curFw - baseFrazw) > 0.5f) {
                                if (curFw <= 0.5f || Math.abs(curFw - 36f) <= 0.5f || Math.abs(curFw - 47f) <= 0.5f) {
                                    unitXY.ufrazw[u] = baseFrazw;
                                } else {
                                    unitXY.ufrazw[u] = baseFrazw;
                                    cheatReason = "TapokAntiCheat: изменение хитбоксов";
                                    break;
                                }
                            }
                        }
                    }
                }

                // проверка цен магазина и базовых таблиц оружия
                if (cheatReason == null && toblife[0] == 60) {
                    for (int i = 0; i < maxtob; i++) {
                        int baseZena = getBaseWeaponZena(i);
                        if (tobzena[i] != baseZena) {
                            tobzena[i] = baseZena;
                            cheatReason = "TapokAntiCheat: изменение цен";
                            break;
                        }
                        int bAtper = getBaseWeaponAtper(i);
                        int bPerper = getBaseWeaponPerper(i);
                        int bKsnv = getBaseWeaponKsnv(i);
                        int bUron = getBaseTobUuron(i);
                        if (tobuatper[i] != bAtper || tobuperper[i] != bPerper) {
                            tobuatper[i] = bAtper;
                            tobuperper[i] = bPerper;
                            cheatReason = "TapokAntiCheat: изменение интервала стрельбы";
                            break;
                        }
                        if (tobuksnv[i] != bKsnv) {
                            tobuksnv[i] = (byte) bKsnv;
                            cheatReason = "TapokAntiCheat: изменение количества пуль";
                            break;
                        }
                        if (tobuuron[i] != bUron) {
                            tobuuron[i] = bUron;
                            cheatReason = "TapokAntiCheat: изменение параметров оружия";
                            break;
                        }
                    }
                    for (int i = 0; i < maxshopmenuob && cheatReason == null; i++) {
                        int zot = zenposobtip[i];
                        if (zot >= 0 && zot < maxtob) {
                            int baseZena = getBaseWeaponZena(zot);
                            if (zenposobzena[i] != baseZena) {
                                zenposobzena[i] = baseZena;
                                cheatReason = "TapokAntiCheat: изменение цен";
                                break;
                            }
                        }
                    }
                }

                // сверка базовых таблиц юнитов и снарядов
                if (cheatReason == null) {
                    for (int i = 0; i <= 4; i++) {
                        if (turaz[i] != getBaseUnitRaz(i) || tumaxlife[i] != getBaseUnitMaxLife(i)
                                || tumaxarmor[i] != getBaseUnitMaxArmor(i) || Math.abs(tuspd[i] - getBaseUnitSpd(i)) > 0.05f) {
                            cheatReason = "TapokAntiCheat: изменение параметров юнита";
                            break;
                        }
                    }
                }
                if (cheatReason == null && (tsnrad[1] > 250f || tsnrad[2] > 180f || tsnrad[5] > 150f || tsnrad[19] > 180f || tsnrad[24] > 180f || tsnrad[0] > 0f)) {
                    cheatReason = "TapokAntiCheat: изменение параметров оружия";
                }

                int checksv = 0;
                for (int i = 0; i < maxtcars; i++)
                    checksv += (int) (carobtip[i] * (i + 1) + carspd[i] * (i + 1) + carmass[i] * (i + 1) + carplcount[i] * (i + 1));
                for (int i = 0; i < maxtob; i++)
                    checksv += (int) (tobraz[i] * (i + 1) + tobfrazw[i] * (i + 1) + tobfrazh[i] * (i + 1) + toblife[i] * (i + 1)
                            + toburonvzr[i] * (i + 1) + toburrad[i] * (i + 1) + tobusnar[i] * (i + 1) + tobuuron[i] * (i + 1) + tobuatper[i] * (i + 1)
                            + tobusnkobmax[i] * (i + 1) + tobusnkzapmax[i] * (i + 1) + tobuperper[i] * (i + 1) + tobslot[i] * (i + 1)
                            + tobuksnv[i] * (i + 1) + tobusnrazb[i] * (i + 1) + tobzena[i] * (i + 1) + tobpoprspd[i] * (i + 1));
                for (int i = 0; i < maxtunit; i++)
                    checksv += (int) (tuspd[i] * (i + 1) + tual[i] * (i + 1) + turaz[i] * (i + 1) + tumaxlife[i] * (i + 1)
                            + tumaxarmor[i] * (i + 1) + tufrazw[i] * (i + 1) + tuscore[i] * (i + 1));
                for (int i = 0; i < maxtbug; i++)
                    checksv += (int) (tbuglife[i] * (i + 1) + tbugspd[i] * (i + 1) + tbuguron[i] * (i + 1)
                            + tbugatper[i] * (i + 1) + tbugscore[i] * (i + 1));
                for (int i = 0; i < maxtsnr; i++)
                    checksv += (int) (tsnspeed[i] * (i + 1) + tsnrad[i] * (i + 1) + tsnraz[i] * (i + 1) + tsntipp[i] * (i + 1));
                for (int i = 0; i < maxshopmenuob; i++) {
                    checksv += shopmenuobtip[i] * (i + 1);
                }
                checksv += unuper + sdunitlifemax + minegperiod + maxegperiod + 25000 + appcodeversion;
                svCount = checksv;
            } catch (Exception ignored) {
            }
            if (cheatReason != null) {
                acLocalMismatchCount++;
                if (acLocalMismatchCount < 3) {
                    cheatReason = null;
                } else if (statsTampered) {
                    resetRoundStatsOnCheat();
                }
            } else {
                acLocalMismatchCount = 0;
            }
        }
        if (cheatReason != null) {
            onAnticheatDetected(cheatReason);
            if (!acKickInProgress) {
                uiGlyphScaleKey = -1L;
                skayrux.shootout2d.UiGlyphMetricTable.INSTANCE.terminateOnInvalidMetrics(this);
                return;
            }
        }
        uiFrameStepTick = (uiFrameStepTick + 1) & 0x3FFFFFFF;
        if (uiFrameStepTick == 0) uiFrameStepTick = 1;
    }

    void setlv1lmadapter() {//set local maps adapter
        lv1.setAdapter(lv1localmapsadapter);
        lv1pos = -1;
        lv1.setOnItemClickListener((parent, view, position, id) -> {
            if (position == -1) return;
            view.setBackgroundColor(lv1selcolor);
            if (lv1pos != -1 && lv1pos != position) {
                final int firstListItemPosition = lv1.getFirstVisiblePosition();
                final int lastListItemPosition = firstListItemPosition + lv1.getChildCount() - 1;
                if (lv1pos >= firstListItemPosition && lv1pos <= lastListItemPosition) {
                    final int childIndex = lv1pos - firstListItemPosition;
                    View v = lv1.getChildAt(childIndex);
                    if (v != null) v.setBackgroundColor(0x00000000);
                }
            }
            lv1pos = position;
        });
    }

    int getsrvselpos() {
        try {
            if (srvselip != null) {
                for (int i = 0; i < lv1serversadapter.getCount(); i++) {
                    datagame_serverobject srv = srvfilteredlistrows.get(i);
                    if (srvselport == srv.srvport && srvselip.equals(srv.srvip)) return i;
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        return -1;
    }

