    class MessagesListAdapter extends ArrayAdapter<String> {//adapter dlja fr. messages (lv2)

        private final Activity context;
        final float ts = 17 * rs;

        MessagesListAdapter(Activity context, List<String> msglist) {
            super(context, R.layout.lv2i_msg, msglist);
            this.context = context;
        }

        @Override
        public View getView(int position, View view, ViewGroup parent) {
            if (view == null) {
                LayoutInflater inflater = LayoutInflater.from(context);
                view = inflater.inflate(R.layout.lv2i_msg, parent, false);
            }
            TextView tvmsg = view.findViewById(R.id.tv_msg);
            tvmsg.setTextSize(TypedValue.COMPLEX_UNIT_PX, ts);
            if (position == -1) return view;
            String nikcolor = "#11ff11";
            try {
                int sid = msglistsid.get(position);
                String nik = msglistnik.get(position);
                String time = msglisttime.get(position);
                String umsg = msglistmsg.get(position);
                if (sid == usersrvid) nikcolor = "#edea04";
                String msg;
                nik = nik.replaceAll("<", "&lt;");
                nik = nik.replaceAll(">", "&gt;");
                umsg = umsg.replaceAll("<", "&lt;");
                umsg = umsg.replaceAll(">", "&gt;");
                if (sid == 420486) {
                    if (!time.isEmpty()) {
                        msg = "<p style=\"text-align:center\"><font color=\"#c2c2c2\"><b>" + umsg + "</b></font>" + "<font color=\"#aaaaaa\"><i>&emsp;[" + time + "]</i></font></p>";
                    } else {
                        msg = "<p style=\"text-align:center\"><font color=\"#c2c2c2\"><b>" + umsg + "</b></font></p>";
                    }
                } else {
                    msg = "<font color=\"" + nikcolor + "\"><b>" + nik + ": </b></font>" + umsg + "<font color=\"#aaaaaa\"><i>&emsp;[" + time + "]</i></font>";
                }
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
                    tvmsg.setText(Html.fromHtml(msg, Html.FROM_HTML_MODE_COMPACT));
                } else {
                    tvmsg.setText(Html.fromHtml(msg));
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
            return view;
        }
    }

