    void clearsnnetid() {//очистка индексов сетевых адресов снарядов
        for (int i = 0; i < maxunit; i++) {
            for (int t = 0; t < maxsnr; t++) {
                snnetid[i][t] = -1;
            }
        }
    }

    void delnetsnr(int iun, int id, int x, int y) {//udalenie setevogo snarjada
        if (id < 0 || id >= maxsnr) return;
        synchronized (snrlock) {
            if (snlocal[id]) return;
            if (x != 0 && y != 0) addanim(snan[id], x, y);
            snExploded[id] = false;
            snFreezeStrikes[id] = 0;
            snlocal[id] = true;
            sntip[id] = -1;
            if (sndraw[id]) snbufclear[id] = true;
            if (id + 1 == snarcount) {
                for (int c = id; c >= 0; c--) {
                    if (sntip[c] != -1) {
                        snarcount = c + 1;
                        break;
                    }
                }
            }
        }
    }

    void cleargamedata() {//очистка индексов отправки игровых данных
        synchronized (gamedatalock) {
            sdglobali = 0;
            for (int i = 0; i < sdpakcount; i++) {
                sdpakind[i] = 0;
            }
        }
    }

    GamedataBuf gamedata_restartbuf(ByteArrayOutputStream baos, DataOutputStream daos, int destclid) throws IOException {
        int pr;
        daos.close();
        sendgamedata_send(baos, destclid);
        baos = new ByteArrayOutputStream();
        daos = new DataOutputStream(baos);
        daos.writeByte(1);
        if (onlinegame) {
            daos.writeByte(maxnetclient);
            pr = 7;
        } else {
            pr = 6;
        }
        daos.writeByte(clientid);
        daos.writeInt(0);
        return new GamedataBuf(baos, daos, pr);
    }

    static class GamedataBuf {
        int pr;
        ByteArrayOutputStream baos;
        DataOutputStream daos;

        GamedataBuf(ByteArrayOutputStream baos, DataOutputStream daos, int pr) {
            this.pr = pr;
            this.baos = baos;
            this.daos = daos;
        }
    }
    private ByteArrayOutputStream baos;
    private DataOutputStream daos;
    private int size;
    private int destclid;

    void startNewPacket() throws IOException {
        baos = new ByteArrayOutputStream();
        daos = new DataOutputStream(baos);

        size = 0;
        destclid = -1;

        daos.writeByte(1);
        if (onlinegame) {
            daos.writeByte(maxnetclient);
            size++;
        }
        daos.writeByte(clientid);
        daos.writeInt(0);
        size += onlinegame ? 7 : 6;
    }

    // упаковка и отправка очереди игровых событий
    void sendgamedata() {
        synchronized (gamedatalock) {
            if (threadspause || sdglobali == 0) {
                cleargamedata();
                return;
            }

            int idx = 0;
            int headerSize = onlinegame ? 7 : 6;

            try {
                ByteArrayOutputStream pktBaos = new ByteArrayOutputStream();
                DataOutputStream pktDaos = new DataOutputStream(pktBaos);
                pktDaos.writeByte(1);
                if (onlinegame) {
                    pktDaos.writeByte(maxnetclient);
                }
                pktDaos.writeByte(clientid);
                pktDaos.writeInt(0);
                int pktSize = headerSize;
                int pktDestClid = -1;

                while (idx < sdglobali) {
                    int i = sdglobalid[idx];
                    int type = sdglobalupr[idx];
                    int clid = sdglobalclid[idx];

                    int evSize = estimateEventSize(type, i);

                    if (evSize > plength) {
                        if (pktBaos.size() > headerSize) {
                            pktDaos.close();
                            sendgamedata_send(pktBaos, pktDestClid);
                            pktBaos = new ByteArrayOutputStream();
                            pktDaos = new DataOutputStream(pktBaos);
                            pktDaos.writeByte(1);
                            if (onlinegame) {
                                pktDaos.writeByte(maxnetclient);
                            }
                            pktDaos.writeByte(clientid);
                            pktDaos.writeInt(0);
                            pktSize = headerSize;
                            pktDestClid = -1;
                        }

                        ByteArrayOutputStream big = new ByteArrayOutputStream();
                        DataOutputStream bigd = new DataOutputStream(big);

                        bigd.writeByte(1);
                        if (onlinegame) bigd.writeByte(maxnetclient);
                        bigd.writeByte(clientid);
                        bigd.writeInt(0);

                        writeEvent(bigd, type, i);

                        bigd.close();
                        sendgamedata_send(big, clid);

                        idx++;
                        continue;
                    }

                    if (pktBaos.size() + evSize > plength || pktSize + evSize > plength || (pktDestClid != -1 && pktDestClid != clid)) {
                        pktDaos.close();
                        sendgamedata_send(pktBaos, pktDestClid);
                        pktBaos = new ByteArrayOutputStream();
                        pktDaos = new DataOutputStream(pktBaos);
                        pktDaos.writeByte(1);
                        if (onlinegame) {
                            pktDaos.writeByte(maxnetclient);
                        }
                        pktDaos.writeByte(clientid);
                        pktDaos.writeInt(0);
                        pktSize = headerSize;
                        pktDestClid = -1;
                    }

                    if (pktDestClid == -1) pktDestClid = clid;

                    writeEvent(pktDaos, type, i);
                    pktSize += evSize;
                    idx++;
                }

                if (pktBaos.size() > headerSize) {
                    pktDaos.close();
                    sendgamedata_send(pktBaos, pktDestClid);
                }
            } catch (Exception e) {
                e.printStackTrace();
            }

            cleargamedata();
        }
    }

    // точный расчет размера события в байтах
    int estimateEventSize(int type, int i) {
        switch (type) {
            case 0:  return 11;
            case 1:  return 5;
            case 2:  return 8;
            case 3:  return 17;
            case 4:  return 9;
            case 5:  return 24;
            case 6:  return 6;
            case 7:  return 2;
            case 8:  return 8;
            case 9:  return 10;
            case 10: return 13;
            case 11: return 10;
            case 12: return 5;
            case 13: return 6;
            case 14: return 12;
            case 15: return 3;
            case 16: return 5;
            case 17: return 2;
            case 18: return 6;
            case 19: return 5;
            case 20: return 5;
            case 21: return 2;
            case 22: return (gtype == 5) ? 17 : 16;
            case 23: return 2;
            case 24: return 3;
            case 25: return 6;
            case 26: return 3;
            case 27: return 2;
            case 28: return 9;
            case 29: return 7;
            case 30: return 4;
            case 31: return 2;
            case 32: return 4;
            case 33: return 4;
            case 34: return 2;
            case 35: return 4;
            case 36: return 7;
            case 37: return 10;
            case 38: return 7;
            case 39: return 13;
            case 40: return 12;
            case 41: return 2;
            case 42: return 9;
            case 43: return 3;
            case 44: return 2;
            case 45: return 2 + maxghost;
            case 46: return 5;
            case 47: return 3;
            case 48: return 7;
            case 49: return 6;
            case 50: return 7;
            case 51: return 2;
            case 52: return 4;
            case 53: return 4;
            default: return 6;
        }
    }

