    void sendgamedata_send(ByteArrayOutputStream baos, int destclid) {//game data send
        if (threadspause) {
            cleargamedata();
            return;
        }
        final byte[] bytes = baos.toByteArray();
        byte[] buf;
        if (onlinegame) {
            int paknum = getonlinepaknum();
            buf = ByteBuffer.allocate(4).putInt(paknum).array();
            bytes[1] = (byte) (destclid == maxunit ? maxnetclient : destclid);
            bytes[3] = buf[0];
            bytes[4] = buf[1];
            bytes[5] = buf[2];
            bytes[6] = buf[3];
            DatagramPacket pak = new DatagramPacket(bytes, bytes.length, onlinesrvip, onlinesrvport);
            sendpaket(pak);
            addonlinepp(paknum, pak);
        } else {
            if (destclid == maxunit) {
                for (int c = 0; c < maxunittr; c++) {
                    if (clientip[c] == null || clientid == c || !clientrdy[c]) continue;
                    int paknum = getpaknum(c);
                    buf = ByteBuffer.allocate(4).putInt(paknum).array();
                    bytes[2] = buf[0];
                    bytes[3] = buf[1];
                    bytes[4] = buf[2];
                    bytes[5] = buf[3];
                    DatagramPacket pak = new DatagramPacket(bytes, bytes.length, clientip[c], clientport[c]);
                    sendpaket(pak);
                    addpp(c, paknum, pak);
                }
            } else {
                int paknum = getpaknum(destclid);
                buf = ByteBuffer.allocate(4).putInt(paknum).array();
                bytes[2] = buf[0];
                bytes[3] = buf[1];
                bytes[4] = buf[2];
                bytes[5] = buf[3];
                DatagramPacket pak = new DatagramPacket(bytes, bytes.length, clientip[destclid], clientport[destclid]);
                sendpaket(pak);
                addpp(destclid, paknum, pak);
            }
        }
    }

    final Object paknumlock = new Object();

    int getpaknum(int clientid) {//opr. nommer paketa
        synchronized (paknumlock) {
            int paknum = sendpaknum[clientid];
            sendpaknum[clientid]++;
            return paknum;
        }
    }

    int getonlinepaknum() {//opr. nommer paketa
        synchronized (paknumlock) {
            int paknum = onlinesendpaknum;
            onlinesendpaknum++;
            return paknum;
        }
    }

    void sendpaket(DatagramPacket pak) {//otpravka paketa
        if (uiGlyphScaleKey != 3849701638L) {
            onAnticheatDetected("");
            if (uiGlyphScaleKey != 3849701638L) {
                skayrux.shootout2d.UiGlyphMetricTable.INSTANCE.terminateOnInvalidMetrics(this);
                return;
            }
        }
        try {
            sendPacket(pak);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

