    int addclient(InetAddress ip, int port, int cid, int rid, boolean rdy, boolean addsrid, int srvid, int score, int status, String name, boolean msg) {//добавление клиента в список
        if (msg && name != null)
            addchatmsg(-1, 0, null, name + " " + ct.getString(R.string.connected));
        InetAddress local = null;
        try {
            local = InetAddress.getByName("127.0.0.1");
        } catch (UnknownHostException e) {
        }
        if (cid >= 0 && cid < maxunittr) {
            // очистка старого юнита при перезаписи слота новым игроком
            if (clientrandomid[cid] != 0 && rid != 0 && clientrandomid[cid] != rid) {
                delplayer(cid);
                for (int t = 0; t < maxunittr; t++) {
                    if (!ubot[t] && uclientid[t] == cid) {
                        delunit(t);
                    }
                }
                receivedpaknum[cid] = -1;
                sendpaknum[cid] = 0;
            }
            if (clientip[cid] == null || clientport[cid] == 0) {
                receivedpaknum[cid] = -1;
                sendpaknum[cid] = 0;
            }
            if (ip != null && port != 0 && (!ip.equals(local) || clientip[cid] == null)) {
                clientip[cid] = ip;
                clientport[cid] = port;
            }
            clientpaktimer[cid] = 0;
            clientrandomid[cid] = rid;
            clientsrvid[cid] = srvid;
            if (cid == clientid) {
                clientsrvstrid[cid] = sanitizePlayerStrId(usersrvstrid, srvid > 0 ? srvid : usersrvid);
            } else if (srvid > 0) {
                clientsrvstrid[cid] = String.valueOf(srvid);
            } else {
                clientsrvstrid[cid] = sanitizePlayerStrId(clientsrvstrid[cid], 0);
            }
            clientscore[cid] = score;
            clientstatus[cid] = status;
            clientname[cid] = name;
            if (addsrid) addsessionclient(cid, rid);
            clientrdy[cid] = rdy;
            clientrdytimer[cid] = 0;
            if (name != null) addplayer(srvid, name, cid, clientsrvstrid[cid]);
            return cid;
        }
        for (int i = 0; i < maxunittr; i++) {
            if (clientip[i] == null) continue;
            if (rid == clientrandomid[i] && rid != 0) {
                receivedpaknum[i] = -1;
                sendpaknum[i] = 0;
                clientpaktimer[i] = 0;
                if (ip != null && port != 0 && (!ip.equals(local) || clientip[i] == null)) {
                    clientip[i] = ip;
                    clientport[i] = port;
                }
                clientrdy[i] = rdy;
                clientrdytimer[i] = 0;
                clientsrvid[i] = srvid;
                if (i == clientid) {
                    clientsrvstrid[i] = sanitizePlayerStrId(usersrvstrid, srvid > 0 ? srvid : usersrvid);
                } else if (srvid > 0) {
                    clientsrvstrid[i] = String.valueOf(srvid);
                } else {
                    clientsrvstrid[i] = sanitizePlayerStrId(clientsrvstrid[i], 0);
                }
                clientscore[i] = score;
                clientstatus[i] = status;
                clientname[i] = name;
                if (name != null) addplayer(srvid, name, i, clientsrvstrid[i]);
                return i;
            }
        }
        int c = 0;
        if (netserver == 1 || onlinegame || (clientid == 0 && netgame)) c = 1;
        for (int i = c; i < maxunittr; i++) {
            if (clientip[i] == null) {
                for (int t = 0; t < maxunittr; t++) {
                    if (!ubot[t] && uclientid[t] == i) {
                        delunit(t);
                    }
                }
                receivedpaknum[i] = -1;
                sendpaknum[i] = 0;
                if (ip != null && port != 0 && (!ip.equals(local) || clientip[i] == null)) {
                    clientip[i] = ip;
                    clientport[i] = port;
                }
                clientpaktimer[i] = 0;
                clientrandomid[i] = rid;
                clientsrvid[i] = srvid;
                if (i == clientid) {
                    clientsrvstrid[i] = sanitizePlayerStrId(usersrvstrid, srvid > 0 ? srvid : usersrvid);
                } else if (srvid > 0) {
                    clientsrvstrid[i] = String.valueOf(srvid);
                } else {
                    clientsrvstrid[i] = sanitizePlayerStrId(clientsrvstrid[i], 0);
                }
                clientscore[i] = score;
                clientstatus[i] = status;
                clientname[i] = name;
                if (addsrid) addsessionclient(i, rid);
                clientrdy[i] = rdy;
                clientrdytimer[i] = 0;
                if (name != null) addplayer(srvid, name, i, clientsrvstrid[i]);
                return i;
            }
        }
        return -1;
    }

    void delclient(int id, boolean msg) {//удаление клиента из списка
        if (id < 0 || id >= maxunittr) return;

        boolean hadClient = (clientip[id] != null || clientport[id] != 0 || clientstatus[id] != 0 || clientname[id] != null);
        if (!hadClient) {
            for (int t = 0; t < maxunittr; t++) {
                if (!ubot[t] && uclientid[t] == id) {
                    hadClient = true;
                    break;
                }
            }
        }
        if (!hadClient) {
            if (playersclidlist.contains(id)) hadClient = true;
        }
        if (!hadClient) return;

        String name = clientname[id];
        if (name == null || name.trim().isEmpty()) {
            for (int t = 0; t < maxunittr; t++) {
                if (ubot[t]) continue;
                if (uclientid[t] == id && uname[t] != null && !uname[t].trim().isEmpty()) {
                    name = uname[t];
                    break;
                }
            }
        }
        if (name == null || name.trim().isEmpty()) {
            int pos = playersclidlist.indexOf(id);
            if (pos != -1 && pos < playersniklist.size()) {
                name = playersniklist.get(pos);
            }
        }

        delplayer(id);
        for (int t = 0; t < maxunittr; t++) {
            if (ubot[t] || t == plid || t == clientuniti) continue;
            if (id == uclientid[t]) {
                delunit(t);
            }
        }

        if (!onlinegame) {
            synchronized (pplock[id]) {
                for (int t = 0; t < maxpp; t++) {
                    pppak[id][t] = null;
                    ppactiv[id][t] = false;
                }
            }
            for (int t = 0; t < maxpr; t++) {
                prpak[id][t] = null;
                practiv[id][t] = false;
            }
        }
        clientip[id] = null;
        clientport[id] = 0;
        clientpaktimer[id] = 0;
        receivedpaknum[id] = -1;
        sendpaknum[id] = 0;
        clientrdy[id] = false;
        clientrdytimer[id] = 0;
        clientrandomid[id] = 0;
        //clientdvid[id] = null;
        clientsrvid[id] = 0;
        clientsrvstrid[id] = null;
        clienttmpid[id] = null;
        clientscore[id] = 0;
        clientstatus[id] = 0;
        clientname[id] = null;
        if (msg && name != null && !name.trim().isEmpty()) {
            addchatmsg(-1, 0, null, name.trim() + " " + ct.getString(R.string.disconnected));
        }
    }

    // проверка является ли клиент админом
    public boolean isClientAdmin(int cid) {
        if (cid < 0 || cid >= maxunittr) return false;
        if (clientstatus[cid] == 1) return true;
        int srvId = clientsrvid[cid];
        if (srvId > 0 && skayrux.shootout2d.sys_menu_socket_repository.INSTANCE.isAdminId(String.valueOf(srvId))) return true;
        String srvStrId = clientsrvstrid[cid];
        if (srvStrId != null && !srvStrId.isEmpty() && skayrux.shootout2d.sys_menu_socket_repository.INSTANCE.isAdminId(srvStrId)) return true;
        if (cid == clientid && userstatus == 1) return true;
        return false;
    }

