    void obrpptimer() {//обработка таймера пакетов с подтверждением
        for (int i = 0; i < maxunittr; i++) {
            if (clientip[i] == null) continue;
            for (int t = 0; t < maxpp; t++) {
                if (ppactiv[i][t]) pptimer[i][t]--;
                if (ppactiv[i][t] && pptimer[i][t] <= 0) {
                    ppdeltimer[i][t]++;
                    pptimer[i][t] = pptime[i] + pptime[i] * ppdeltimer[i][t] / 2;
                    DatagramPacket pak = pppak[i][t];
                    if (pak == null) {
                        delpp(i, ppnum[i][t]);
                        continue;
                    }
                    if (ppdeltimer[i][t] > 10) {
                        delpp(i, ppnum[i][t]);
                        continue;
                    }
                    sendpaket(pak);
                }
            }
        }
    }

    void obronlinepptimer() {//обработка таймера пакетов с подтверждением
        for (int t = 0; t < maxpp; t++) {
            if (onlineppactiv[t]) onlinepptimer[t]--;
            if (onlineppactiv[t] && onlinepptimer[t] <= 0) {
                onlineppdeltimer[t]++;
                if (onlineppdeltimer[t] > 5) {
                    delpp(-1, onlineppnum[t]);
                    continue;
                }
                onlinepptimer[t] = onlinepptime + onlinepptime * onlineppdeltimer[t] / 2;
                DatagramPacket pak = onlinepppak[t];
                if (pak == null) {
                    delpp(-1, onlineppnum[t]);
                    continue;
                }
                if (udpSocket.isConnected()) {
                    int sport = udpSocket.getPort();
                    InetAddress sip = udpSocket.getInetAddress();
                    if (sport != -1 && sip != null) {
                        if (pak.getPort() != sport || !sip.equals(pak.getAddress())) {
                            pak.setPort(sport);
                            pak.setAddress(sip);
                        }
                    }
                }
                sendpaket(pak);
            }
        }
    }


