    void loadprofile() {//load user login/pass
        try {
            BufferedReader br = new BufferedReader(new InputStreamReader(openFileInput("prof")));
            String login = br.readLine();
            String pass = br.readLine();
            lastnewsid = br.read();
            br.close();
            if (login != null) login = login.trim();
            if (pass != null) {
                pass = pass.trim();
                if (pass.startsWith("enc_v1$")) {
                    pass = skayrux.shootout2d.AppSettings.INSTANCE.decryptText(pass);
                }
            }
            if (login != null && pass != null && !login.isEmpty() && login.length() <= 15 && pass.length() <= 15 && !pass.isEmpty()) {
                userlogin = login;
                userpass = pass;
                tmplogin = false;
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

