    void delob(int id, int rid, boolean send) {//удаление объекта
        if (id < 0 || id >= maxob) return;
        if ((obtip[id] >= 26 && obtip[id] <= 32) || obtip[id] == 59 || obtip[id] == 60)
            soundManager.addsound(31, -1, obx[id], oby[id]);//der
        if (obtip[id] == 45)  soundManager.addsound(45, -1, obx[id], oby[id]);//sack
        synchronized (oblock) {
            if (obrid[id] != rid) return;
            del_ob_fo(id);
            if (!netgame || netserver == 1) {
                for (int c = 0; c < maxunittr; c++) {
                    if (utip[c] == -1 || !ubot[c] || utip[c] == 5) continue;
                    if (obx[id] < upktx[c] + 2 && obx[id] > upktx[c] - 2 && oby[id] < upkty[c] + 2 && oby[id] > upkty[c] - 2) {
                        ustop(c);
                    }
                }
            }
            // очистка состояния транспорта и гибель локальных юнитов внутри при удалении машины
            boolean isCarOb = (obtip[id] == 74 || obtip[id] == 85);
            for (int u = 0; u < maxunittr; u++) {
                boolean inCar = (ucarobid[u] == id || obcaruid[id][0] == u || (maxcarplcount > 1 && obcaruid[id][1] == u));
                if (inCar) {
                    ucarobid[u] = -1;
                    ucarpos[u] = -1;
                    ucartip[u] = -1;
                    if (isCarOb) {
                        ukilled[u] = true;
                        udeathtimer[u] = 65;
                        if (utip[u] != -1) {
                            if (upatobtip[u] < 0 && upatbugtip[u] < 0) {
                                upatuid[u] = -1;
                                upatobtip[u] = obtip[id];
                            }
                            if (!netgame || !unet[u]) {
                                killunit(u, true);
                            }
                        }
                    }
                }
            }
            Arrays.fill(obcaruid[id], -1);
            // сброс угла и скорости при удалении объекта
            obugol[id] = 0;
            oboldugol[id] = 0;
            obspd[id] = 0;
            obtip[id] = -1;
            obverredraw[id] = true;
            if (id + 1 == ob_count) {
                for (int c = id; c >= 0; c--) {
                    if (obtip[c] != -1) {
                        ob_count = c + 1;
                        break;
                    }
                }
            }
        }
        if (netgame && send) senddelob(id, rid, maxunit);
    }

    void delbug(int id) {//удаление жука
        if (id < 0 || id >= maxbug) return;
        float x, y;
        if (netgame && netserver == 0 && (Math.abs(bugx[id] - bugold1x[id]) + Math.abs(bugy[id] - bugold1y[id])) > 40) {
            x = bugold1x[id];
            y = bugold1y[id];
        } else {
            x = bugx[id];
            y = bugy[id];
        }
        soundManager.addsound(buguns[id], -1, x, y);
        addanim(bugunan[id], x, y);
        addpt(bugpt[id], (int) x, (int) y, rand.nextInt(360), -1);
        bugatuid[id] = -1;
        bugatobid[id] = -1;
        bugatbugid[id] = -1;
        bugstop(id);
        bugdraw[id] = false;
        bugtip[id] = -1;
        bugclear[id] = true;
        boolean br = false;
        if (id + 1 == bug_count) {
            for (int c = id; c >= 0; c--) {
                if (bugtip[c] != -1) {
                    bug_count = c + 1;
                    br = true;
                    break;
                }
            }
            if (!br) bug_count = 0;
        }
    }

    int ztexind(String name) {//заполнение индексов текстур
        if (name == null) return 0;
        for (int t = 0; t < ttexmapid; t++) {
            if (texname[t] != null && name.equals(texname[t])) {
                return t;
            }
        }
        return 0;
    }

    private long mLastBackPressTime = 0;

    @Override
    public boolean dispatchKeyEvent(KeyEvent event) {
        if (event.getKeyCode() == KeyEvent.KEYCODE_BACK) {
            if (event.getAction() == KeyEvent.ACTION_UP) {
                processBackNavigation();
            }
            return true;
        }
        return super.dispatchKeyEvent(event);
    }

    @Override
    public void onBackPressed() {
        processBackNavigation();
    }

    private void processBackNavigation() {
        long now = android.os.SystemClock.uptimeMillis();
        if (now - mLastBackPressTime < 300) {
            return;
        }
        mLastBackPressTime = now;

        if (mZagruzkaVisible || loadingtimer < 5 || getcustommap || (netgame && netserver == 0 && !gameconnect) || !initgl) {
            return;
        }

        if (isGameMenuVisible()) {
            if (skayrux.shootout2d.LiveBackgroundState.INSTANCE.isEditingControls()) {
                skayrux.shootout2d.LiveBackgroundState.INSTANCE.setEditingControls(false);
            } else if (skayrux.shootout2d.GameMenuState.INSTANCE.getSelectedTab().equals(skayrux.shootout2d.Game_menuKt.TAB_GLAVNYY_RAZDELCHIK)) {
                setGameMenuVisible(false);
            } else {
                skayrux.shootout2d.GameMenuHelper.resetToGlavnyyRazdelchik();
            }
            return;
        }

        if (glscreen == 11 || setscreen == 11) {
            if (dialogid != -1) {
                dialogid = -1;
                setacdialogid(dialogid);
                setscreen = 11;
                chview = true;
                return;
            }
            if (!memapsaved) {
                dialogid = 27;
                setacdialogid(dialogid);
                setscreen = 11;
                chview = true;
                return;
            }
            finish();
            return;
        }

        if (glscreen == 2 || setscreen == 2 || netgame || newg || isStartedFromKotlin) {
            if (dialogid != -1) {
                dialogid = -1;
                setacdialogid(dialogid);
                setscreen = 2;
                chview = true;
                return;
            }
            if (mmapsost == 2) {
                mmapsost = 1;
                return;
            }
            setGameMenuVisible(true);
            return;
        }

        stopthreads();
        try {
            if (netgame) senddisconnect();
        } catch (Exception ignored) {}
        netgame = false;
        stopnetgame(true);
        finish();
    }

    @Override
    public boolean onKeyDown(int keyCode, KeyEvent event) {
        if (keyCode == KeyEvent.KEYCODE_BACK) {
            return true;
        }
        return super.onKeyDown(keyCode, event);
    }

    static class datagame_mapeditorobject {
        byte obtip;
        String name;
        int maxcount;

        datagame_mapeditorobject(int obtip, String name, int maxcount) {
            this.obtip = (byte) obtip;
            this.name = name;
            this.maxcount = maxcount;
        }
    }

    static class GameObject {
        byte obtip;
        short x, y;

        GameObject(byte obtip, short x, short y) {
            this.obtip = obtip;
            this.x = x;
            this.y = y;
        }
    }

    static class GameMapKv {//map editor - kvadrat karti
        String texname;
        int texid, texind, vb;
        byte svp;
        short x0, y0, x1, y1;
        boolean addonmap, maintex, remove;

        GameMapKv(String texname, int texid, int texind, int svp, float x0, float y0, float x1, float y1, int vb, boolean addonmap, boolean maintex) {
            this.texname = texname;
            this.texid = texid;
            this.texind = texind;
            this.svp = (byte) svp;
            this.x0 = (short) x0;
            this.y0 = (short) y0;
            this.x1 = (short) x1;
            this.y1 = (short) y1;
            this.vb = vb;
            this.addonmap = addonmap;
            this.maintex = maintex;
            this.remove = false;
        }
    }

    static class MapEditorTexture {//element texturi dlja map editor
        int texid;//id texturi
        String texname;//imja texturi
        byte svp;//sv-vo poverhnosti
        short width;
        short height;
        boolean maintex, alfatex;

        MapEditorTexture(int texid, String texname, int svp, int width, int height, boolean maintex, boolean alfatex) {
            this.texid = texid;
            this.texname = texname;
            this.svp = (byte) svp;
            this.width = (short) width;
            this.height = (short) height;
            this.maintex = maintex;
            this.alfatex = alfatex;
        }
    }

