    void setunitscore(int id, int tip, boolean bot) {
        if (id < 0 || id >= maxunittr || tip < 0 || tip >= maxtunit) return;
        if (bot) {
            if (tip == 0 || tip == 1) {
                switch (uatraz[id]) {
                    case 0:
                        uscore[id] = 40;
                        break;
                    case 30:
                        uscore[id] = 20;
                        break;
                    default:
                        uscore[id] = 10;
                }
            }
            if (tip == 2) uscore[id] = 50;
            if (tip == 3) {
                switch (uatraz[id]) {
                    case 0:
                        uscore[id] = 300;
                        break;
                    case 30:
                        uscore[id] = 200;
                        break;
                    default:
                        uscore[id] = 100;
                }
            }
        } else {
            uscore[id] = tuscore[tip];
        }
    }

    final Object addbuglock = new Object();

    void addbug(int ii, int tip, float x, float y, int life, int uid) {//добавление жука на карту
        if (tip < 0 || tip >= maxtbug) return;
        int rad = 50;
        synchronized (addbuglock) {
            if (ii == -1) {
                for (int i = 0; i < maxbug; i++) {
                    if (bugtip[i] == -1) {
                        ii = i;
                        break;
                    }
                }
            }
            if (ii < 0 || ii >= maxbug) return;
            bugraz[ii] = tbugraz[tip];
            bugfrazw[ii] = tbugfrazw[tip];
            if (!netgame || netserver == 1) {
                if (bbr == 50) life = life / 2;
                if (bbr == 30) life = life - life / 4;
                if (life <= 0) life = 1;
            }
            if (life > tbuglife[tip]) life = tbuglife[tip];
            buglife[ii] = life;
            buguron[ii] = tbuguron[tip];
            bugsnar[ii] = tbugsnar[tip];
            bugatper[ii] = tbugatper[tip];
            bugunan[ii] = tbugunan[tip];
            buguns[ii] = tbuguns[tip];
            bugpspd[ii] = tbugpspd[tip];
            bugspd[ii] = tbugspd[tip];
            buguid[ii] = uid;
            if (uid >= 0 && uid < maxunittr) {
                bugteam[ii] = uteam[uid];
                buglifetimer[ii] = 600;
            } else {
                bugteam[ii] = -1;
                buglifetimer[ii] = -1;
            }
            buganper[ii] = tbuganper[tip];
            bugmaxk[ii][0] = tbugmaxk[tip][0];
            bugmaxk[ii][1] = tbugmaxk[tip][1];
            bugmaxk[ii][2] = tbugmaxk[tip][2];
            bugpt[ii] = tbugpt[tip];
            bugzen[ii] = tbugzen[tip];
            bugantimer[ii] = 0;
            bugsdim[ii] = 0;
            bugugol[ii] = 0;
            bugkugol[ii] = 0;
            bugugolrad[ii] = 0;
            bugoldugol[ii] = -1;
            bugoldx[ii] = -1;
            bugoldy[ii] = -1;
            buglagx[ii] = -1;
            buglagy[ii] = -1;
            bugoldtx[ii] = -1;
            bugoldty[ii] = -1;
            bugktx[ii] = -1;
            bugkty[ii] = -1;
            bugtd[ii] = 0;
            bugktp[ii] = 0;
            bugtk[ii][0] = 0;
            bugtk[ii][1] = 0;
            bugtk[ii][2] = 0;
            bugsos[ii] = 0;
            bugoti[ii] = 0;
            bugatuid[ii] = -1;
            bugoldatuid[ii] = -1;
            bugatbugid[ii] = -1;
            bugoldatbugid[ii] = -1;
            bugatobid[ii] = -1;
            bugattimer[ii] = 0;
            bugsnpx[ii] = 0;
            bugsnpy[ii] = 0;
            bugstkol[ii] = 0;
            bugpatid[ii] = -1;
            buglagtimer[ii] = 0;
            for (int t = 0; t < maxop; t++) {
                bugotx[ii][t] = -1;
                bugoty[ii][t] = -1;
            }
            if (x > mapw - 1) x = mapw - 1;
            if (x < 0) x = 0;
            if (y > maph - 1) y = maph - 1;
            if (y < 0) y = 0;
            if (!bugprov(ii, (int) x, (int) y)) {
                boolean res = true;
                int sd = 0;
                int tx1, tx2, ty1, ty2;
                float sdm;
                while (res) {
                    sdm = sd * maprk;
                    tx1 = Math.round(x + sdm);
                    ty1 = Math.round(y + sdm);
                    tx2 = Math.round(x - sdm);
                    ty2 = Math.round(y - sdm);
                    if (tx1 >= mapw) tx1 = mapw - 1;
                    if (ty1 >= maph) ty1 = maph - 1;
                    if (tx2 < 0) tx2 = 0;
                    if (ty2 < 0) ty2 = 0;
                    boolean tres = false;
                    for (int t = tx2; t <= tx1; t = t + maprk) {
                        if (bugprov(ii, t, ty1)) {
                            x = t;
                            y = ty1;
                            tres = true;
                            break;
                        }
                        if (bugprov(ii, t, ty2)) {
                            x = t;
                            y = ty2;
                            tres = true;
                            break;
                        }
                    }
                    for (int t = ty2; t <= ty1; t = t + maprk) {
                        if (bugprov(ii, tx1, t)) {
                            x = tx1;
                            y = t;
                            tres = true;
                            break;
                        }
                        if (bugprov(ii, tx2, t)) {
                            x = tx2;
                            y = t;
                            tres = true;
                            break;
                        }
                    }
                    if (tres) break;
                    sd++;
                    if (sd > rad) {
                        res = false;
                        break;
                    }
                }
                if (!res) return;
            }
            if (x > mapw - 1) x = mapw - 1;
            if (x < 0) x = 0;
            if (y > maph - 1) y = maph - 1;
            if (y < 0) y = 0;
            bugx[ii] = x;
            bugy[ii] = y;
            bugtx[ii] = x;
            bugty[ii] = y;
            bugnettx[ii] = x;
            bugnetty[ii] = y;
            bugnetvx[ii] = 0f;
            bugnetvy[ii] = 0f;
            bugnetinit[ii] = true;
            Arrays.fill(bugold2x[ii], -1);
            Arrays.fill(bugold2y[ii], -1);
            bugugolr[ii] = 0;
            bugdraw[ii] = false;
            bugtip[ii] = (byte) tip;
            bugclear[ii] = true;
            if (bug_count < ii + 1) bug_count = ii + 1;
        }
        if (netgame && netserver == 1) sendaddbugall(ii, tip, x, y, life, uid, false, maxunit);
    }

    static class Position {
        int x, y;

        Position(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    Position getspawn(int team) {
        if (team != 0 && team != 1) return new Position(rand.nextInt(mapw), rand.nextInt(maph));
        datagame_spawnposition sp;
        if (team == 0) {
            if (bluespawn.isEmpty()) {
                return new Position(100, rand.nextInt(maph));
            } else {
                int i = rand.nextInt(bluespawn.size());
                sp = bluespawn.get(i);
                if (sp == null) return new Position(100, rand.nextInt(maph));
            }
        } else {
            if (redspawn.isEmpty()) {
                return new Position(mapw - 100, rand.nextInt(maph));
            } else {
                int i = rand.nextInt(redspawn.size());
                sp = redspawn.get(i);
                if (sp == null) return new Position(mapw - 100, rand.nextInt(maph));
            }
        }
        return new Position(sp.x0 + rand.nextInt(sp.x1 - sp.x0), sp.y0 + rand.nextInt(sp.y1 - sp.y0));
    }

    void addspawn(int tip, float x, float y) {
        if (tip != 81 && tip != 82) return;
        float raz = tobraz[tip] / 2;
        datagame_spawnposition sp = new datagame_spawnposition(x - raz, y - raz, x + raz, y + raz);
        if (tip == 81) {
            bluespawn.add(sp);
        } else {
            redspawn.add(sp);
        }
    }

    void clearspawn() {//clear posizii spawna
        bluespawn.clear();
        redspawn.clear();
    }

