    boolean ptprov(int ptx, int pty, float raz) {//проверка возможности нахождения пятна в данных координатах
        if (fmap == null) return false;
        float razd2 = raz / 2;
        int npx, npy, kpx, kpy;
        float fx, fy;
        npx = (int) ((ptx - razd2) / maprk);
        kpx = (int) ((ptx + razd2) / maprk) + 1;
        npy = (int) ((pty - razd2) / maprk);
        kpy = (int) ((pty + razd2) / maprk) + 1;
        if (npx < 0) npx = 0;
        if (npy < 0) npy = 0;
        if (npx > mapfw - 1) npx = mapfw - 1;
        if (npy > mapfh - 1) npy = mapfh - 1;
        if (kpx < 0) kpx = 0;
        if (kpy < 0) kpy = 0;
        if (kpx > mapfw - 1) kpx = mapfw - 1;
        if (kpy > mapfh - 1) kpy = mapfh - 1;
        for (int x = npx; x <= kpx; x++) {
            for (int y = npy; y <= kpy; y++) {
                if (fmap[x][y] != 0 && fmap[x][y] < 10) {
                    fx = x * maprk;
                    fy = y * maprk;
                    if (ptx + razd2 >= fx && ptx - razd2 <= fx + maprk && pty + razd2 >= fy && pty - razd2 <= fy + maprk) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    boolean obprov(int ind, int ox, int oy) {//проверка возможности нахождения объекта в данных координатах
        if (fmap == null) return false;
        float razd2w = obfrazw[ind] / 2f;
        float razd2h = obfrazh[ind] / 2f;
        if (razd2w == 0) {
            razd2w = obraz[ind] / 3f;
            razd2h = razd2w;
        }
        int npx, npy, kpx, kpy;
        float fx, fy;
        npx = (int) ((ox - razd2w) / maprk);
        kpx = (int) ((ox + razd2w) / maprk) + 1;
        npy = (int) ((oy - razd2h) / maprk);
        kpy = (int) ((oy + razd2h) / maprk) + 1;
        if (npx < 0) npx = 0;
        if (npy < 0) npy = 0;
        if (npx > mapfw - 1) npx = mapfw - 1; // 1
        if (npy > mapfh - 1) npy = mapfh - 1;
        if (kpx < 0) kpx = 0;
        if (kpy < 0) kpy = 0;
        if (kpx > mapfw - 1) kpx = mapfw - 1;
        if (kpy > mapfh - 1) kpy = mapfh - 1;
        for (int x = npx; x <= kpx; x++) {
            for (int y = npy; y <= kpy; y++) {
                if (fmap[x][y] > 0 && fmap[x][y] < 10) {
                    fx = x * maprk;
                    fy = y * maprk;
                    if (ox + razd2w > fx && ox - razd2w < fx + maprk && oy + razd2h > fy && oy - razd2h < fy + maprk) {
                        return false;
                    }
                }
            }
        }
        float urd2tw, urd2th;
        for (int t = 0; t < maxunittr; t++) {
            if (utip[t] == -1) continue;
            urd2tw = unitXY.ufrazw[t] / 2f;
            if (urd2tw>40f){
                //showtoast("cheat1");
                cldisconnect(false);
                chscreen(1);
                finish();
                System.exit(0);
            }
            if (ox + razd2w > unitXY.ux[t] - urd2tw && ox - razd2w < unitXY.ux[t] + urd2tw && oy + razd2h > unitXY.uy[t] - urd2tw && oy - razd2h < unitXY.uy[t] + urd2tw) {
                return false;
            }
        }
        int[] obs = getobs(ox - razd2w, oy - razd2h, ox + razd2w, oy + razd2h);
        for (int id : obs) {
            if (id == -1) break;
            if (obtip[id] == -1 || obfrazw[id] == 0) continue;
            if (obtip[id] == 45) {
                urd2tw = obfrazw[id] / 4f;
                urd2th = obfrazh[id] / 4f;
            } else{
                urd2tw = obfrazw[id] / 2f;
                urd2th = obfrazh[id] / 2f;
            }
            if (ox + razd2w > obx[id] - urd2tw && ox - razd2w < obx[id] + urd2tw && oy + razd2h > oby[id] - urd2th && oy - razd2h < oby[id] + urd2th) {
                return false;
            }
        }
        for (int t = 0; t < bug_count; t++) {
            if (bugtip[t] == -1 || t == ind) continue;
            urd2tw = bugfrazw[t] / 2f;
            if (ox + razd2w > bugx[t] - urd2tw && ox - razd2w < bugx[t] + urd2tw && oy + razd2h > bugy[t] - urd2tw && oy - razd2h < bugy[t] + urd2tw) {
                return false;
            }
        }
        return true;
    }

    void add_ob_fo(int ind) {//добавление физ. области
        if (fmap == null) return;
        boolean fo = obfo[ind];
        float frazwd2, frazhd2;
        if (obfrazw[ind] > 0 && obfrazh[ind] > 0) {
            frazwd2 = (obfrazw[ind] - 1) / 2;
            frazhd2 = (obfrazh[ind] - 1) / 2;
        } else {
            frazwd2 = obmaprk / 2;
            frazhd2 = frazwd2;
        }
        int nx, ny, kx, ky;
        short foi = (short) (10 + ind);
        if (fo) {
            nx = (int) ((obx[ind] - frazwd2) / maprk);
            ny = (int) ((oby[ind] - frazhd2) / maprk);
            kx = (int) ((obx[ind] + frazwd2) / maprk) + 1;
            ky = (int) ((oby[ind] + frazhd2) / maprk) + 1;
            if (nx < 0) nx = 0;
            if (ny < 0) ny = 0;
            if (nx > mapfw) nx = mapfw;
            if (ny > mapfh) ny = mapfh;
            if (kx < 0) kx = 0;
            if (ky < 0) ky = 0;
            if (kx > mapfw) kx = mapfw;
            if (ky > mapfh) ky = mapfh;
            for (int i = nx; i < kx; i++) {
                for (int t = ny; t < ky; t++) {
                    if (fmap[i][t] == 0) fmap[i][t] = foi;
                }
            }
        }
        nx = (int) ((obx[ind] - frazwd2) / obmaprk);
        ny = (int) ((oby[ind] - frazhd2) / obmaprk);
        kx = (int) ((obx[ind] + frazwd2) / obmaprk) + 1;
        ky = (int) ((oby[ind] + frazhd2) / obmaprk) + 1;
        if (nx < 0) nx = 0;
        if (ny < 0) ny = 0;
        if (nx > obmapfw) nx = obmapfw;
        if (ny > obmapfh) ny = obmapfh;
        if (kx < 0) kx = 0;
        if (ky < 0) ky = 0;
        if (kx > obmapfw) kx = obmapfw;
        if (ky > obmapfh) ky = obmapfh;
        boolean isSolid = (obfrazw[ind] > 0 && obfrazh[ind] > 0 && !obuse[ind]);
        for (int i = nx; i < kx; i++) {
            for (int t = ny; t < ky; t++) {
                if (allobmap[i][t][0] == foi || allobmap[i][t][1] == foi) continue;
                if (allobmap[i][t][0] == 0) {
                    allobmap[i][t][0] = foi;
                } else if (allobmap[i][t][1] == 0) {
                    allobmap[i][t][1] = foi;
                } else if (isSolid) {
                    // приоритет твердых объектов в сетке коллизий
                    int id0 = allobmap[i][t][0] - 10;
                    int id1 = allobmap[i][t][1] - 10;
                    if (id0 < 0 || id0 >= maxob || obtip[id0] == -1 || (obun[id0] && oblife[id0] <= 0) || obfrazw[id0] <= 0 || obfrazh[id0] <= 0 || obuse[id0]) {
                        allobmap[i][t][0] = foi;
                    } else if (id1 < 0 || id1 >= maxob || obtip[id1] == -1 || (obun[id1] && oblife[id1] <= 0) || obfrazw[id1] <= 0 || obfrazh[id1] <= 0 || obuse[id1]) {
                        allobmap[i][t][1] = foi;
                    }
                }
            }
        }
    }

    void del_ob_fo(int ind) {//удаление физ. области
        if (fmap == null) return;
        boolean fo = obfo[ind];
        float frazwd2, frazhd2;
        if (obfrazw[ind] > 0 && obfrazh[ind] > 0) {
            frazwd2 = (obfrazw[ind]) / 2;
            frazhd2 = (obfrazh[ind]) / 2;
        } else {
            frazwd2 = obmaprk / 2;
            frazhd2 = frazwd2;
        }
        int nx, ny, kx, ky;
        int foi = 10 + ind;
        if (fo) {
            nx = (int) ((obx[ind] - frazwd2) / maprk);
            ny = (int) ((oby[ind] - frazhd2) / maprk);
            kx = (int) ((obx[ind] + frazwd2) / maprk) + 1;
            ky = (int) ((oby[ind] + frazhd2) / maprk) + 1;
            if (nx < 0) nx = 0;
            if (ny < 0) ny = 0;
            if (nx > mapfw) nx = mapfw;
            if (ny > mapfh) ny = mapfh;
            if (kx < 0) kx = 0;
            if (ky < 0) ky = 0;
            if (kx > mapfw) kx = mapfw;
            if (ky > mapfh) ky = mapfh;
            for (int i = nx; i < kx; i++) {
                for (int t = ny; t < ky; t++) {
                    if (fmap[i][t] == foi) fmap[i][t] = 0;
                }
            }
        }
        nx = (int) ((obx[ind] - frazwd2) / obmaprk);
        ny = (int) ((oby[ind] - frazhd2) / obmaprk);
        kx = (int) ((obx[ind] + frazwd2) / obmaprk) + 1;
        ky = (int) ((oby[ind] + frazhd2) / obmaprk) + 1;
        if (nx < 0) nx = 0;
        if (ny < 0) ny = 0;
        if (nx > obmapfw) nx = obmapfw;
        if (ny > obmapfh) ny = obmapfh;
        if (kx < 0) kx = 0;
        if (ky < 0) ky = 0;
        if (kx > obmapfw) kx = obmapfw;
        if (ky > obmapfh) ky = obmapfh;
        for (int i = nx; i < kx; i++) {
            for (int t = ny; t < ky; t++) {
                if (allobmap[i][t][0] == foi) allobmap[i][t][0] = 0;
                if (allobmap[i][t][1] == foi) allobmap[i][t][1] = 0;
            }
        }
        // восстановление объектов в освободившихся ячейках сетки
        for (int k = 0; k < ob_count; k++) {
            if (k == ind || obtip[k] == -1) continue;
            if (obun[k] && oblife[k] <= 0) continue;
            float kw = (obfrazw[k] > 0 && obfrazh[k] > 0) ? (obfrazw[k] - 1) / 2 : obmaprk / 2;
            float kh = (obfrazw[k] > 0 && obfrazh[k] > 0) ? (obfrazh[k] - 1) / 2 : obmaprk / 2;
            int knx = (int) ((obx[k] - kw) / obmaprk);
            int kny = (int) ((oby[k] - kh) / obmaprk);
            int kkx = (int) ((obx[k] + kw) / obmaprk) + 1;
            int kky = (int) ((oby[k] + kh) / obmaprk) + 1;
            if (kkx > nx && knx < kx && kky > ny && kny < ky) {
                add_ob_fo(k);
            }
        }
    }

