    void provmine(int obid, int uid, int bugid){//vzriv mini
        if (obid<0 || obid>=maxob) return;
        if (uid>=0 && uid<maxunittr){
            if (!frfr){
                int ouid=obuid[obid];
                int carobid = ucarobid[uid];
                if (carobid>=0 && carobid < maxob && ouid>=0 && ouid<maxunittr){
                    int obcaru = obcaruid[carobid][0];
                    if (obcaru != -1) if (uteam[obcaru]==uteam[ouid]) return;
                }
                if (ouid>=0 && ouid<maxunittr){
                    if (uteam[ouid]==uteam[uid]) return;
                }
            }
            float razw=unitXY.ufrazw[uid]/2+obfrazw[obid]/2;
            float razh=unitXY.ufrazw[uid]/2+obfrazh[obid]/2;
            int tcarobid=ucarobid[uid];
            if (tcarobid>=0 && tcarobid<maxob){
                razw=(obfrazw[tcarobid]+obfrazh[tcarobid])/4f+obfrazw[obid]/2;
                razh=(obfrazw[tcarobid]+obfrazh[tcarobid])/4f+obfrazh[obid]/2;
            }
            if (obx[obid]<unitXY.ux[uid]+razw && obx[obid]>unitXY.ux[uid]-razw && oby[obid]<unitXY.uy[uid]+razh && oby[obid]>unitXY.uy[uid]-razh){
                int oldlife=oblife[obid];
                oblife[obid]=obzz;
                if (netgame && netserver==0) sendoblife(obid, -(oldlife-oblife[obid]), -1, obrid[obid], 0);
                return;
            }
        }
        if (bugid>=0 && bugid<maxbug){
            if (!frfr){
                int ouid=obuid[obid];
                if (ouid>=0 && ouid<maxunittr){
                    if (uteam[ouid]==bugteam[bugid]) return;
                }
            }
            float razw=bugfrazw[bugid]/2+obfrazw[obid]/2;
            float razh=bugfrazw[bugid]/2+obfrazh[obid]/2;
            if (obx[obid]<bugx[bugid]+razw && obx[obid]>bugx[bugid]-razw && oby[obid]<bugy[bugid]+razh && oby[obid]>bugy[bugid]-razh){
                int oldlife=oblife[obid];
                oblife[obid]=obzz;
                if (netgame && netserver==0) sendoblife(obid, -(oldlife-oblife[obid]), -1, obrid[obid], 0);
            }
        }
    }

    void setcarugol(int uid){//raschet ugla povorota car
        if (uid==-1) return;
        int carobid=ucarobid[uid];
        if (carobid==-1) return;
        double fx1, fy1, bx1, by1;
        double fx2, fy2, bx2, by2;
        double nx, ny, kx, ky;
        double a, d;
        double ugolrad=Math.toRadians(uugol[uid]);
        double kugolrad=Math.toRadians(ukugol[uid]);
        float baseFrazH = (obtip[carobid] >= 0 && obtip[carobid] < maxtob) ? tobfrazh[obtip[carobid]] : obfrazh[carobid];
        float fradraz = baseFrazH / 2f;
        float bradraz = baseFrazH / 2f;
        double spd=obspd[carobid];
        fx1=(unitXY.ux[uid]-fradraz*Math.sin(ugolrad));
        fy1=(unitXY.uy[uid]+fradraz*Math.cos(ugolrad));
        bx1=(unitXY.ux[uid]+bradraz*Math.sin(ugolrad));
        by1=(unitXY.uy[uid]-bradraz*Math.cos(ugolrad));
        fx2=(fx1-spd*Math.sin(kugolrad));
        fy2=(fy1+spd*Math.cos(kugolrad));
        a=Math.toRadians(Math.abs(ukugol[uid]-uugol[uid]));
        spd=(spd*Math.cos(a));
        bx2=(bx1-spd*Math.sin(ugolrad));
        by2=(by1+spd*Math.cos(ugolrad));
        nx=mapw-bx2;
        ny=maph-by2;
        kx=mapw-fx2;
        ky=maph-fy2;
        d=Math.sqrt((kx-nx)*(kx-nx)+(ky-ny)*(ky-ny));
        if (d==0) d=0.00001;
        a=-(ky-ny)/d;
        if (a>1) a=1;
        if (a<-1) a=-1;
        a=Math.acos(a);
        if (kx<nx) a=pim2-a;
        uugol[uid]=(float) Math.toDegrees(a);
    }

    int getcaroburon(int carobid, int obid){
        if (carobid==-1 || obid==-1) return 0;
        int otip=obtip[carobid];
        int cartip=-1;
        if (otip>=0 && otip<maxtob) cartip=tobcartip[otip];
        if (cartip==-1) return 0;
        float carspd=Math.abs(obspd[carobid]);
        if (carspd<=1.5f) return 0;
        float nx, ny, kx, ky;
        nx=mapw-obx[carobid];
        ny=maph-oby[carobid];
        kx=mapw-obx[obid];
        ky=maph-oby[obid];
        double d=Math.sqrt((kx-nx)*(kx-nx)+(ky-ny)*(ky-ny));
        if (d==0) d=0.00001;
        double a=-(ky-ny)/d;
        if (a>1) a=1;
        if (a<-1) a=-1;
        a=Math.acos(a);
        if (kx<nx) a=pim2-a;
        double mn=Math.abs(Math.cos(Math.toRadians(Math.abs(obugol[carobid]-Math.toDegrees(a)))));
        int uron=(int) (carspd*carmass[cartip]*mn*2);
        return uron;
    }

