    // обработка пинга и таймаута соединения
    void sendClientPingPacket() {
        if (!onlinegame || onlinesrvip == null) return;
        try {
            int srvToken = -10000 - ((++lastPingToken) & 0x7FFF);
            lastServerPingToken = srvToken;
            lastPingReqNano = System.nanoTime();
            lastPingReqTimeMs = System.currentTimeMillis();
            if (onlinesrvport > 0) {
                ByteArrayOutputStream srvBaos = new ByteArrayOutputStream(7);
                DataOutputStream srvDaos = new DataOutputStream(srvBaos);
                srvDaos.writeByte(23);
                srvDaos.writeByte(-1);
                srvDaos.writeByte(-1);
                srvDaos.writeInt(srvToken);
                srvDaos.close();
                byte[] srvBytes = srvBaos.toByteArray();
                sendpaket(new DatagramPacket(srvBytes, srvBytes.length, onlinesrvip, onlinesrvport));
            } else {
                byte[] bytes = new byte[]{-37};
                sendpaket(new DatagramPacket(bytes, bytes.length, onlinesrvip, ipport));
            }
        } catch (Exception ignored) {}
    }

    void sendHostPingReply(int targetCl, int pingToken) {
        if (!onlinegame || onlinesrvip == null || onlinesrvport <= 0) return;
        if (targetCl <= 0 || targetCl >= maxunittr) return;
        try {
            ByteArrayOutputStream baos = new ByteArrayOutputStream(8);
            DataOutputStream daos = new DataOutputStream(baos);
            daos.writeByte(24);
            daos.writeByte(targetCl);
            daos.writeByte(clientid);
            daos.writeByte(-11);
            daos.writeInt(pingToken);
            daos.close();
            byte[] bytes = baos.toByteArray();
            DatagramPacket pak = new DatagramPacket(bytes, bytes.length, onlinesrvip, onlinesrvport);
            sendpaket(pak);
        } catch (Exception ignored) {}
    }

    void updateClientPing() {
        if (!onlinegame || !gameconnect || mZagruzkaVisible || loadingtimer < 5 || getcustommap || newg) return;
        long now = System.currentTimeMillis();
        if (now - lastPingReqTimeMs >= 600L) {
            sendClientPingPacket();
        }
    }

    void obrrpaktimer() {//обработка таймера потери связи
        if (mZagruzkaVisible || loadingtimer < 5 || getcustommap || !gameconnect || newg) {
            rpaktimer = 0;
            lastRoomPacketTimeMs = System.currentTimeMillis();
            try {
                if (skayrux.shootout2d.PerformanceMonitorState.INSTANCE.isServerConnectionLost()) {
                    skayrux.shootout2d.PerformanceMonitorState.INSTANCE.setServerConnectionLost(false);
                }
            } catch (Exception ignored) {}
            return;
        }
        rpaktimer++;
        if (netserver == 0 || onlinegame) {
            long now = System.currentTimeMillis();
            if (lastRoomPacketTimeMs <= 0L) {
                lastRoomPacketTimeMs = now;
            }
            boolean isLosingConn = (now - lastRoomPacketTimeMs >= 900L && rpaktimer >= 25);
            try {
                if (skayrux.shootout2d.PerformanceMonitorState.INSTANCE.isServerConnectionLost() != isLosingConn) {
                    skayrux.shootout2d.PerformanceMonitorState.INSTANCE.setServerConnectionLost(isLosingConn);
                }
            } catch (Exception ignored) {}
            if (now - lastRoomPacketTimeMs >= 3000L && rpaktimer >= 90) {
                connfailed(true, "timeout");
            }
        }
    }

    void connfailed(boolean send) {
        connfailed(send, ct.getString(R.string.connection_failed));
    }

    void connfailed(boolean send, final String reasonMsg) {
        if (send) {
            for (int i = 0; i < 3; i++) {
                senddisconnect();
            }
        }
        netgame = false;
        final String msg = (reasonMsg != null && !reasonMsg.trim().isEmpty())
                ? reasonMsg
                : ct.getString(R.string.connection_failed);
        if (!connfail) {
            connfailmsg = msg;
            connfail = true;
        }
        clearclient();
        if (soundManager != null) soundManager.stopAllSoundsOnExit();
        if (isStartedFromKotlin) {
            runOnUiThread(() -> {
                try {
                    showtoast(msg);
                    cldisconnect(false);
                    stopnetgame(true);
                    stopthreads();
                } catch (Exception ignored) {
                } finally {
                    finish();
                }
            });
        }
    }

    void ndrawanim() {//прорисовка анимаций эффектов
        for (int i = 0; i < animcount; i++) {
            if (antip[i] == -1) continue;
            antime[i]++;
            if (antimer[i] > 0) antimer[i]--;
            if (antime[i] > anper[i]) {
                antime[i] = 0;
                antk[i]++;
                if (antk[i] >= anmaxk[i]) {
                    antk[i] = 0;
                    if (antimer[i] != 0) continue;
                    antip[i] = -1;
                    if (andraw[i]) anbufclear[i] = true;
                }
            }
        }
    }

    void ndrawsmk() {//прорисовка дыма
        for (int i = 12; i < maxsmk; i++) {
            if (smtip[i] == -1) continue;
            smraz[i] = smraz[i] + smspd[i];
            smfraz[i] = smraz[i] / 1.75f;
            if (smtimer[i] > 0) smtimer[i]--;
            if (smtimer[i] == 0 || smraz[i] == 0 || smal[i] < -1) {
                smtimer[i] = -1;
                if (smdraw[i]) smbufclear[i] = true;
                smtip[i] = -1;
                if (i - 11 == smkcount) {
                    int nextCount = 0;
                    for (int t = i - 1; t >= 12; t--) {
                        if (smtip[t] != -1) {
                            nextCount = t - 11;
                            break;
                        }
                    }
                    smkcount = nextCount;
                }
                continue;
            }
            if (smtimer[i] <= smperzat[i]) {
                smal[i] = smtimer[i] / (float) (smperzat[i]) - 1 + smnal[i];
            }
        }
    }

    void ndrawpt() {//прорисовка пятен
        for (int i = 0; i < pt_count; i++) {
            if (pttip[i] == -1) continue;
            if (ptal[i] > 0) ptal[i] = ptal[i] - 0.005f;
            if (ptal[i] <= 0) {
                pttip[i] = -1;
                if (ptdraw[i]) ptclear[i] = true;
                if (i + 1 == pt_count) {
                    for (int t = i; t >= 0; t--) {
                        if (pttip[t] != -1) {
                            pt_count = t + 1;
                            break;
                        }
                    }
                }
            }
        }
    }

    void ndrawsleep() {//прорисовка ослепления
        for (int i = 0; i < maxunittr; i++) {
            if (usos[i] > 0) usos[i] = usos[i] - sosspd;
            if (usos[i] < 0) usos[i] = 0;
        }
        for (int i = 0; i < bug_count; i++) {
            if (bugsos[i] > 0) bugsos[i] = bugsos[i] - sosspd;
            if (bugsos[i] < 0) bugsos[i] = 0;
        }
    }

