    void obrbombtimer() {//obrabotka timera vzriva bombi
        if (!bombactiv) return;
        int bid = -1;
        for (int i = ob_count - 1; i >= 0; i--) {
            if (obtip[i] == 54) {
                bid = i;
                break;
            }
        }
        bsoundper = bvzrtimer / (bvzrperiod / bsoundnper);
        if (bsoundper < 2) bsoundper = 2;
        if (bsoundtimer > 0) {
            bsoundtimer--;
        } else {
            bsoundtimer = bsoundper;
            if (bid != -1 && obtip[bid] == 54) {
                bombpip = 2;
                soundManager.addsound(65, -1, obx[bid], oby[bid]);
            }
        }
        if (bvzrtimer > 0) bvzrtimer--;
        if (netgame && netserver == 1) {
            bvzrsendtimer++;
            if (bvzrsendtimer > 150) {
                bvzrsendtimer = 0;
                sendbvzrtimer();
            }
        }
    }

    void endbangolos() {//konez ban-golosovanija
        banreqshow = false;
        banza = 0;
        banprotiv = 0;
        bandclid = -1;
        bansclid = -1;
        bandsrvid = -1;
        bandrid = -1;
       // bandvid = null;
    }

    void obrbantimer() {
        if (bangolostimer > 0) {
            bangolostimer--;
            if (bangolostimer == 0) {
                int dclid = bandclid;
                int dsrvid = bandsrvid;
                int drid = bandrid;
                int za = banza;
                int protiv = banprotiv;
                endbangolos();
                if (dclid < 0 || dclid >= maxunittr) return;
                String targetName = clientname[dclid];
                if (targetName == null || targetName.isEmpty()) targetName = "Player";
                boolean ban = (za > protiv);
                // вывод итогов голосования за кик в чат
                String titleMsg = ct.getString(R.string.str_voting_ban_title, targetName);
                String countsMsg = ct.getString(R.string.str_voting_ban_counts, za, protiv);
                String resultMsg = ct.getString(ban ? R.string.str_voting_ban_result_kick : R.string.str_voting_ban_result_keep);
                addchatmsg(-1, 0, null, titleMsg);
                addchatmsg(-1, 0, null, countsMsg);
                addchatmsg(-1, 0, null, resultMsg);
                if (ban) {
                    if (dclid == clientid) {
                        senddisconnectban(dclid, dsrvid, drid);
                        exitOnBan();
                    } else {
                        if (dsrvid != 0 && !bansidlist.contains(dsrvid)) bansidlist.add(dsrvid);
                        if (drid != 0 && !banridlist.contains(drid)) banridlist.add(drid);
                        if (dclid >= 0 && dclid < maxunittr) {
                            String dvid = (clienttmpid[dclid] != null && !clienttmpid[dclid].isEmpty()) ? clienttmpid[dclid] : clientsrvstrid[dclid];
                            if (dvid != null && !dvid.isEmpty() && !bandvidlist.contains(dvid)) bandvidlist.add(dvid);
                        }
                        if (netserver == 1) {
                            senddisconnectban(dclid, dsrvid, drid);
                            delclient(dclid, true);
                        }
                    }
                }
            }
        }
    }

