    void speedCheck() {
        long currTime = System.currentTimeMillis();
        if (currTime - mpTime < 10) {
            mpCount++;
        } else {
            if (mpCount > 0) mpCount--;
        }
        if (mpCount > 10) {
            senddisconnect();
            finish();
        }
        mpTime = currTime;
    }

