    private long lastMoveStepNano = 0L;
    private float smoothMoveDtMs = 16.0f;
    private volatile float moveStepScale = 1.05f;

     void move_prov() {// 60 fps
        // компенсация шага скорости под старый тайминг 16 мс
        long nowMoveNano = System.nanoTime();
        if (lastMoveStepNano != 0L) {
            float dtMs = (nowMoveNano - lastMoveStepNano) / 1000000f;
            if (dtMs >= 10f && dtMs <= 35f) {
                smoothMoveDtMs = smoothMoveDtMs * 0.85f + dtMs * 0.15f;
            }
        }
        lastMoveStepNano = nowMoveNano;
        float sc = smoothMoveDtMs / 15.4f;
        if (sc < 1.0f) sc = 1.0f;
        if (sc > 1.25f) sc = 1.25f;
        moveStepScale = sc;
        speedCheck();
        soundManager.playrepsound();
        if (netgame) {
            if (onlinegame) {
                obronlinepptimer();
            } else {
                obrpptimer();
            }
        }
        switch (glscreen) {
            case 1:
                move_prov_menu_obr60Fps();
                break;
            case 3:
                break;
            case 4:
                break;
            case 5:
                break;
            case 6:
                move_prov_menu_obr60Fps();
                break;
            case 7:
                move_prov_menu_obr60Fps();
                break;
            case 8:
                break;
            case 9:
                move_prov_menu_obr60Fps();
                break;
            case 14:
                move_prov_menu_obr60Fps();
                break;
            case 2:
                if (netgame) {
                    updateClientPing();
                }
                if (netgame && pause && netserver == 1 && provmod1) {
                    obrrpaktimer();
                    return;
                }
                if (pause || mapfw <= 0) {
                    if (netgame && mapfw > 0) {
                        obrrpaktimer();
                    }
                    return;
                }
                if (netgame) {
                    if (!onlinegame || (netPosTick++ % 2 == 0)) {
                        sendunitpos();
                        sendCarpos();
                    }
                }
                if (netgame) {
                    if (onlinegame) {
                        sendplscore();
                        obrping();
                        obrbantimer();
                    }
                    if (netserver == 1) clientmanager();
                    sendgamedata();
                    obrrpaktimer();
                }
                // синхронизация шага движения с отрисовкой камеры и мира
                synchronized (moveRenderLock) {
                    if (netgame) antilagmov();
                    provunit();
                    if(onlinegame) {
                        if (rpaktimer < 50) {
                            atunit();
                            utmove();
                        }
                    }
                    else {
                        atunit();
                        utmove();
                    }
                    uugmove();
                    bugtmove();
                    provteam();
                    obtmove();
                    obautouse();
                    provob();
                    provbug();
                    if (gtype == 12) planeMove();
                    snmove();
                    bugugmove();
                    glmove();
                }
                break;
        }
    }

