        void addloadedob(int tip, int x, int y, int n) {//dobavlenie zagruzennogo objekta na kartu
            if (tip < 0 || tip >= maxtob) return;
            int id = -1;
            if (tip == 36) {
                flbluex = x - mapminx;
                flbluey = y - mapminy;
            }
            if (tip == 37) {
                flredx = x - mapminx;
                flredy = y - mapminy;
            }
            if ((!weapononmap || gtype == 10) && tip != 4 && tip != 5 && tip != 52 && tip != 74 && tip != 85) {
                boolean add = true;
                for (int i = 0; i < maxshopmenuob; i++) {
                    if (tip == shopmenuobtip[i]) {
                        add = false;
                        break;
                    }
                }
                if (!add) return;
            }
            switch (gtype) {
                case 3:
                    if (tip != 36 && tip != 37 && tip != 55 && tip != 56) {
                        id = addob(loadedobid, tip, x - mapminx, y - mapminy, tobusnkobmax[tip], tobusnkzapmax[tip], toblife[tip], false, n, false, -1);
                        loadedobid++;
                    }
                    if (tip == 34) bbaseid = id;
                    if (tip == 35) rbaseid = id;
                    break;
                case 4:
                    if (tip != 34 && tip != 35 && tip != 55 && tip != 56) {
                        id = addob(loadedobid, tip, x - mapminx, y - mapminy, tobusnkobmax[tip], tobusnkzapmax[tip], toblife[tip], false, n, false, -1);
                        loadedobid++;
                    }
                    break;
                case 5:
                    if (tip != 35 && tip != 36 && tip != 37 && tip != 55 && tip != 56) {
                        id = addob(loadedobid, tip, x - mapminx, y - mapminy, tobusnkobmax[tip], tobusnkzapmax[tip], toblife[tip], false, n, false, -1);
                        loadedobid++;
                    }
                    if (tip == 34) bbaseid = id;
                    break;
                case 9:
                    if (tip != 34 && tip != 35 && tip != 36 && tip != 37) {
                        id = addob(loadedobid, tip, x - mapminx, y - mapminy, tobusnkobmax[tip], tobusnkzapmax[tip], toblife[tip], false, n, false, -1);
                        loadedobid++;
                    }
                    if (tip == 55) bpid[0] = id;
                    if (tip == 56) bpid[1] = id;
                    break;
                default:
                    if (tip != 34 && tip != 35 && tip != 36 && tip != 37 && tip != 55 && tip != 56) {
                        id = addob(loadedobid, tip, x - mapminx, y - mapminy, tobusnkobmax[tip], tobusnkzapmax[tip], toblife[tip], false, n, false, -1);
                        loadedobid++;
                    }
            }
            if (id >= 0 && id < maxob) oblist.add(new ObIds(id, n));
        }

        int LoadTex(int idname, int provcode) {//загрузка текстур
            final BitmapFactory.Options options = new BitmapFactory.Options();
            options.inScaled = false;
            GLES30.glActiveTexture(GLES30.GL_TEXTURE0);
            int[] t = new int[1];
            GLES30.glGenTextures(1, t, 0);
            GLES30.glBindTexture(GLES30.GL_TEXTURE_2D, t[0]);
            GLES30.glTexParameterf(GLES30.GL_TEXTURE_2D, GLES30.GL_TEXTURE_MIN_FILTER, GLES30.GL_LINEAR);
            GLES30.glTexParameterf(GLES30.GL_TEXTURE_2D, GLES30.GL_TEXTURE_MAG_FILTER, GLES30.GL_LINEAR);
            GLES30.glTexParameterf(GLES30.GL_TEXTURE_2D, GLES30.GL_TEXTURE_WRAP_S, GLES30.GL_CLAMP_TO_EDGE);
            GLES30.glTexParameterf(GLES30.GL_TEXTURE_2D, GLES30.GL_TEXTURE_WRAP_T, GLES30.GL_CLAMP_TO_EDGE);
            Bitmap bitmap = BitmapFactory.decodeResource(getResources(), idname, options);
            if (provcode != 0) {
                int w = bitmap.getWidth();
                int h = bitmap.getHeight();
                if (bitmap.getPixel(w / 2, h / 2) != provcode) finish();
            }
            GLUtils.texImage2D(GLES30.GL_TEXTURE_2D, 0, bitmap, 0);
            bitmap.recycle();
            texid[texcount] = t[0];
            texcount++;
            return t[0];
        }

        void updateCrosshairTex(int texId, int argbColor) {
            int w = 40;
            int h = 40;
            int a = (argbColor >> 24) & 0xFF;
            int r = (argbColor >> 16) & 0xFF;
            int g = (argbColor >> 8) & 0xFF;
            int b = argbColor & 0xFF;

            java.nio.ByteBuffer buffer = java.nio.ByteBuffer.allocateDirect(w * h * 4);
            buffer.order(java.nio.ByteOrder.nativeOrder());
            for (int y = 0; y < h; y++) {
                for (int x = 0; x < w; x++) {
                    if (x >= 18 && x <= 21) {
                        buffer.put((byte) r);
                        buffer.put((byte) g);
                        buffer.put((byte) b);
                        buffer.put((byte) a);
                    } else {
                        buffer.put((byte) 0);
                        buffer.put((byte) 0);
                        buffer.put((byte) 0);
                        buffer.put((byte) 0);
                    }
                }
            }
            buffer.position(0);

            GLES30.glActiveTexture(GLES30.GL_TEXTURE0);
            GLES30.glBindTexture(GLES30.GL_TEXTURE_2D, texId);
            GLES30.glTexParameterf(GLES30.GL_TEXTURE_2D, GLES30.GL_TEXTURE_MIN_FILTER, GLES30.GL_LINEAR);
            GLES30.glTexParameterf(GLES30.GL_TEXTURE_2D, GLES30.GL_TEXTURE_MAG_FILTER, GLES30.GL_LINEAR);
            GLES30.glTexParameterf(GLES30.GL_TEXTURE_2D, GLES30.GL_TEXTURE_WRAP_S, GLES30.GL_CLAMP_TO_EDGE);
            GLES30.glTexParameterf(GLES30.GL_TEXTURE_2D, GLES30.GL_TEXTURE_WRAP_T, GLES30.GL_CLAMP_TO_EDGE);
            GLES30.glTexImage2D(GLES30.GL_TEXTURE_2D, 0, GLES30.GL_RGBA, w, h, 0, GLES30.GL_RGBA, GLES30.GL_UNSIGNED_BYTE, buffer);
        }

        int createCrosshairTex(int argbColor) {
            GLES30.glActiveTexture(GLES30.GL_TEXTURE0);
            int[] t = new int[1];
            GLES30.glGenTextures(1, t, 0);
            updateCrosshairTex(t[0], argbColor);
            texid[texcount] = t[0];
            texcount++;
            return t[0];
        }

        int loadtexmap(int ttexid, int mapid, int provcode) {//загрузка атласа текстур
            int texw, texh;
            int x1 = 0, y1 = 0;
            final BitmapFactory.Options options = new BitmapFactory.Options();
            options.inScaled = false;
            options.inPreferredConfig = Bitmap.Config.ARGB_8888;
            int[] t = new int[1];
            GLES30.glGenTextures(1, t, 0);
            GLES30.glBindTexture(GLES30.GL_TEXTURE_2D, t[0]);
            GLES30.glTexParameterf(GLES30.GL_TEXTURE_2D, GLES30.GL_TEXTURE_MIN_FILTER, GLES30.GL_LINEAR);
            GLES30.glTexParameterf(GLES30.GL_TEXTURE_2D, GLES30.GL_TEXTURE_MAG_FILTER, GLES30.GL_LINEAR);
            GLES30.glTexParameterf(GLES30.GL_TEXTURE_2D, GLES30.GL_TEXTURE_WRAP_S, GLES30.GL_CLAMP_TO_EDGE);
            GLES30.glTexParameterf(GLES30.GL_TEXTURE_2D, GLES30.GL_TEXTURE_WRAP_T, GLES30.GL_CLAMP_TO_EDGE);
            Bitmap bitmap;
            try {
                bitmap = BitmapFactory.decodeResource(getResources(), ttexid, options);
            } catch (NullPointerException e) {
                return 0;
            }
            if (bitmap == null) return 0;
            texw = bitmap.getWidth();
            texh = bitmap.getHeight();
            if (provcode != 0) {
                if (bitmap.getPixel(texw / 2, texh / 2) != provcode) finish();
            }
            GLUtils.texImage2D(GLES30.GL_TEXTURE_2D, 0, bitmap, 0);
            bitmap.recycle();
            try {
                Resources r = ct.getResources();
                InputStream is = r.openRawResource(mapid);
                InputStreamReader isr = new InputStreamReader(is);
                BufferedReader br = new BufferedReader(isr);
                String str;
                StringBuilder tmp = new StringBuilder();
                int tmpi;
                while ((str = br.readLine()) != null) {
                    byte u = 0;
                    if (ttexmapid >= maxtex) {
                        log("maxtex!");
                        break;
                    }
                    texname[ttexmapid] = "";
                    for (int i = 0; i < str.length(); i++) {
                        switch (u) {
                            case 0:
                                if (str.charAt(i) != ' ') {
                                    texname[ttexmapid] = texname[ttexmapid] + str.charAt(i);
                                } else {
                                    u++;
                                }
                                break;
                            case 1:
                                if (str.charAt(i) == ' ') {
                                    tmp = new StringBuilder();
                                    u++;
                                }
                                break;
                            case 2:
                                if (str.charAt(i) != ' ') {
                                    tmp.append(str.charAt(i));
                                } else {
                                    tmpi = Integer.parseInt(tmp.toString());
                                    x1 = tmpi;
                                    texx1[ttexmapid] = (float) tmpi / (float) texw;
                                    tmp = new StringBuilder();
                                    u++;
                                }
                                break;
                            case 3:
                                if (str.charAt(i) != ' ') {
                                    tmp.append(str.charAt(i));
                                } else {
                                    tmpi = Integer.parseInt(tmp.toString());
                                    y1 = tmpi;
                                    texy1[ttexmapid] = (float) tmpi / (float) texh;
                                    tmp = new StringBuilder();
                                    u++;
                                }
                                break;
                            case 4:
                                if (str.charAt(i) != ' ') {
                                    tmp.append(str.charAt(i));
                                } else {
                                    tmpi = Integer.parseInt(tmp.toString());
                                    texx2[ttexmapid] = (float) (tmpi + x1) / (float) texw;
                                    tmp = new StringBuilder();
                                    u++;
                                }
                                break;
                            case 5:
                                if (i != str.length() - 1) {
                                    tmp.append(str.charAt(i));
                                } else {
                                    tmp.append(str.charAt(i));
                                    tmpi = Integer.parseInt(tmp.toString());
                                    texy2[ttexmapid] = (float) (tmpi + y1) / (float) texh;
                                    tmp = new StringBuilder();
                                    u++;
                                }
                                break;
                        }
                    }
                    ttexmapid++;
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
            texid[texcount] = t[0];
            texcount++;
            return t[0];
        }

        int loadtxt() {//загрузка разметки для текста
            int texw, texh;
            int x1 = 0, y1 = 0;
            final BitmapFactory.Options options = new BitmapFactory.Options();
            options.inScaled = false;
            int[] tt = new int[1];
            GLES30.glGenTextures(1, tt, 0);
            GLES30.glBindTexture(GLES30.GL_TEXTURE_2D, tt[0]);
            GLES30.glTexParameterf(GLES30.GL_TEXTURE_2D, GLES30.GL_TEXTURE_MIN_FILTER, GLES30.GL_LINEAR_MIPMAP_LINEAR);
            GLES30.glTexParameterf(GLES30.GL_TEXTURE_2D, GLES30.GL_TEXTURE_MAG_FILTER, GLES30.GL_LINEAR);
            GLES30.glTexParameterf(GLES30.GL_TEXTURE_2D, GLES30.GL_TEXTURE_WRAP_S, GLES30.GL_CLAMP_TO_EDGE);
            GLES30.glTexParameterf(GLES30.GL_TEXTURE_2D, GLES30.GL_TEXTURE_WRAP_T, GLES30.GL_CLAMP_TO_EDGE);
            Bitmap bitmap = BitmapFactory.decodeResource(getResources(), R.raw.txt_256, options);
            texw = bitmap.getWidth();
            texh = bitmap.getHeight();
            GLUtils.texImage2D(GLES30.GL_TEXTURE_2D, 0, bitmap, 0);
            GLES30.glGenerateMipmap(GLES30.GL_TEXTURE_2D);
            bitmap.recycle();
            try {
                Resources r = ct.getResources();
                InputStream is = r.openRawResource(R.raw.txt_256f);
                InputStreamReader isr = new InputStreamReader(is);
                BufferedReader br = new BufferedReader(isr);
                String str;
                int ind = -1;
                while ((str = br.readLine()) != null) {
                    ind++;
                    byte u = 0;
                    for (int i = 0; i < str.length(); i++) {
                        if (str.charAt(i) == '=') {
                            StringBuilder tmp = new StringBuilder();
                            for (int t = i + 1; t < str.length(); t++) {
                                if (str.charAt(t) == ' ') break;
                                tmp.append(str.charAt(t));
                            }
                            int n = Integer.parseInt(tmp.toString());
                            switch (u) {
                                case 0:
                                    chid[ind] = n;
                                    break;
                                case 1:
                                    x1 = n;
                                    chtx1[ind] = (float) n / (float) texw;
                                    break;
                                case 2:
                                    y1 = n;
                                    chty1[ind] = (float) n / (float) texh;
                                    break;
                                case 3:
                                    chw[ind] = n;
                                    chtx2[ind] = (float) (n + x1) / (float) texw;
                                    break;
                                case 4:
                                    chh[ind] = n;
                                    chty2[ind] = (float) (n + y1) / (float) texh;
                                    break;
                                case 5:
                                    chxo[ind] = n;
                                    break;
                                case 6:
                                    chyo[ind] = n;
                                    break;
                                case 7:
                                    chxa[ind] = n;
                                    break;
                            }
                            u++;
                        }
                    }
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
            texid[texcount] = tt[0];
            texcount++;
            return tt[0];
        }

