        void clearbrmap() {
            for (int i = 0; i < mapmaxwk; i++) {
                for (int j = 0; j < mapmaxhk; j++) {
                    String mapname = "br_" + i + j;
                    try {
                        File mapfile = getFileStreamPath(mapname);
                        if (mapfile.exists()) mapfile.delete();
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                }
            }
        }

        void loadmap(int resname, String mapname) {//загрузка карты
            String ver1 = "", ver2;
            cleargame();
            Resources r = ct.getResources();
            InputStream is = r.openRawResource(resname);
            InputStreamReader isr = new InputStreamReader(is);
            BufferedReader br = new BufferedReader(isr);
            long code = 0;
            String str;
            StringBuilder tmp;
            int x0 = 0;
            int y0 = 0;
            int x1 = 0;
            int y1, t;
            int texid = 0;
            short svp = 0;
            byte u = 0;
            boolean genmap = false;
            try {
                ver1 = br.readLine();
                try {
                    code = Long.parseLong(ver1);
                } catch (Exception ex) {
                }
                DataInputStream dais = new DataInputStream(openFileInput(mapname));
                ver2 = dais.readUTF();
                if (ver2 == null || !ver2.equals(ver1)) throw new IOException();
                maxmapk = dais.readInt();
                code = code + maxmapk;
                if (maxmapk <= 0 || maxmapk > maxmapw * maxmaph) throw new IOException();
                setmapbuf(maxmapk);
                mapminx = dais.readShort();
                code = code + mapminx;
                mapminy = dais.readShort();
                code = code + mapminy;
                mapmaxx = dais.readShort();
                code = code + mapmaxx;
                mapmaxy = dais.readShort();
                code = code + mapmaxy;
                setmapvar();
                while (dais.available() > 0) {
                    str = dais.readUTF();
                    texid = ztexind(str);
                    svp = dais.readByte();
                    code = code + svp;
                    if (svp < -1) throw new IOException();
                    x0 = dais.readShort();
                    code = code + x0;
                    y0 = dais.readShort();
                    code = code + y0;
                    x1 = dais.readShort();
                    code = code + x1;
                    y1 = dais.readShort();
                    code = code + y1;
                    addmapkv(svp, texid, x0, y0, x1, y1);
                }
                dais.close();
                if (!provmapcode(code)) {
                    /*genmap = true;
                    try {
                        code = Long.parseLong(ver1);
                    } catch (Exception ex) {
                    } */
                }
            } catch (IOException e) {
                genmap = true;
            }
            if (!genmap) return;
            maxmapk = getmaxmapk(resname);
            code = code + maxmapk;
            if (maxmapk == 0) maxmapk = maxmapw * maxmaph;
            setmapbuf(maxmapk);
            try {
                DataOutputStream daos = new DataOutputStream(openFileOutput(mapname, MODE_PRIVATE));
                if ((str = br.readLine()) != null) mapminx = Math.round(Integer.parseInt(str));
                code = code + mapminx;
                if ((str = br.readLine()) != null) mapminy = Math.round(Integer.parseInt(str));
                code = code + mapminy;
                if ((str = br.readLine()) != null) mapmaxx = Math.round(Integer.parseInt(str));
                code = code + mapmaxx;
                if ((str = br.readLine()) != null) mapmaxy = Math.round(Integer.parseInt(str));
                code = code + mapmaxy;
                daos.writeUTF(ver1);
                daos.writeInt(maxmapk);
                daos.writeShort(mapminx);
                daos.writeShort(mapminy);
                daos.writeShort(mapmaxx);
                daos.writeShort(mapmaxy);
                setmapvar();
                while ((str = br.readLine()) != null) {
                    switch (u) {
                        case 0:
                            daos.writeUTF(str);
                            texid = ztexind(str);
                            u++;
                            break;
                        case 1:
                            tmp = new StringBuilder();
                            for (t = 0; t < str.length(); t++) {
                                tmp.append(str.charAt(t));
                            }
                            svp = Short.parseShort(tmp.toString());
                            code = code + svp;
                            daos.writeByte(svp);
                            u++;
                            break;
                        case 2:
                            tmp = new StringBuilder();
                            for (t = 0; t < str.length(); t++) {
                                tmp.append(str.charAt(t));
                            }
                            x0 = Math.round(Integer.parseInt(tmp.toString())) - mapminx;
                            code = code + x0;
                            daos.writeShort(x0);
                            u++;
                            break;
                        case 3:
                            tmp = new StringBuilder();
                            for (t = 0; t < str.length(); t++) {
                                tmp.append(str.charAt(t));
                            }
                            y0 = Math.round(Integer.parseInt(tmp.toString())) - mapminy;
                            code = code + y0;
                            daos.writeShort(y0);
                            u++;
                            break;
                        case 4:
                            tmp = new StringBuilder();
                            for (t = 0; t < str.length(); t++) {
                                tmp.append(str.charAt(t));
                            }
                            x1 = Math.round(Integer.parseInt(tmp.toString())) - mapminx;
                            code = code + x1;
                            daos.writeShort(x1);
                            u++;
                            break;
                        case 5:
                            tmp = new StringBuilder();
                            for (t = 0; t < str.length(); t++) {
                                tmp.append(str.charAt(t));
                            }
                            y1 = Math.round(Integer.parseInt(tmp.toString())) - mapminy;
                            code = code + y1;
                            daos.writeShort(y1);
                            u = 0;
                            addmapkv(svp, texid, x0, y0, x1, y1);
                            break;
                    }
                }
                daos.close();
                //if (!provmapcode(code)) finish();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

