        void setmapbuf(int maxmapk) {//ustanovka map-buffera
            ByteBuffer bb = ByteBuffer.allocateDirect(maxmapk * 6 * 2 * 4);
            bb.order(ByteOrder.nativeOrder());
            mapverbuf = bb.asFloatBuffer();
            mapverbuf.position(0);
            float[] buf = new float[maxmapk * 6 * 2];
            mapverbuf.put(buf);
            mapverbuf.position(0);
            bb = ByteBuffer.allocateDirect(maxmapk * 6 * 2 * 4);
            bb.order(ByteOrder.nativeOrder());
            maptexbuf = bb.asFloatBuffer();
            maptexbuf.position(0);
            maptexbuf.put(buf);
            maptexbuf.position(0);
        }

        void setmapvar() {//set map variable
            tmappos = 0;
            mapw = mapmaxx - mapminx;
            if (mapw < 0) mapw = -mapw;
            maph = mapmaxy - mapminy;
            if (maph < 0) maph = -maph;
            int tmapfw = mapw / maprk;
            int tmapfh = maph / maprk;
            obmapfw = mapw / obmaprk;
            obmapfh = maph / obmaprk;
            fmap = new short[tmapfw][tmapfh];//
            mmap = new int[tmapfw][tmapfh];  //840 Kb
            allobmap = new short[obmapfw][obmapfh][2];    //2240 Kb
            int tmaxhz = tmapfw * tmapfh;
            hzx = new short[tmaxhz];//
            hzy = new short[tmaxhz];//560 Kb
            //BR map: 33374*6*2*4=1564 Kb (3129 Kb inkl. VBO)
            maxhz = tmaxhz;
            mapfw = tmapfw;
            mapfh = tmapfh;
            mapkvw = mapw / mapmaxwk;
            mapkvh = maph / mapmaxhk;
        }

        int addmapkv(short svp, int texid, int x0, int y0, int x1, int y1) {//dobavit kvadrat karti v buffer
            if (mapverbuf == null || maptexbuf == null) return 0;
            if (tmappos / 6 >= maxmapk) return 0;
            float[] buf12 = new float[12];
            int inx = x0 / maprk;
            int iny = y0 / maprk;
            int ikx = (x1 - maprk) / maprk;
            int iky = (y1 - maprk) / maprk;
            if (fmap != null) {
                for (int i = inx; i <= ikx; i++) {
                    for (int t = iny; t <= iky; t++) {
                        if (i >= 0 && i < fmap.length && t >= 0 && t < fmap[i].length) {
                            fmap[i][t] = svp;
                        }
                    }
                }
            }
            buf12[0] = x0;
            buf12[1] = y0;
            buf12[2] = x1;
            buf12[3] = y0;
            buf12[4] = x0;
            buf12[5] = y1;
            buf12[6] = x1;
            buf12[7] = y0;
            buf12[8] = x0;
            buf12[9] = y1;
            buf12[10] = x1;
            buf12[11] = y1;
            int vb = tmappos * 2;
            if (vb >= 0 && vb + 12 <= mapverbuf.capacity()) {
                mapverbuf.position(vb);
                mapverbuf.put(buf12);
            }
            if (texid >= 0 && texid < texx1.length && texid < texy1.length && texid < texx2.length && texid < texy2.length) {
                buf12[0] = texx1[texid];
                buf12[1] = texy2[texid];
                buf12[2] = texx2[texid];
                buf12[3] = texy2[texid];
                buf12[4] = texx1[texid];
                buf12[5] = texy1[texid];
                buf12[6] = texx2[texid];
                buf12[7] = texy2[texid];
                buf12[8] = texx1[texid];
                buf12[9] = texy1[texid];
                buf12[10] = texx2[texid];
                buf12[11] = texy1[texid];
            } else {
                Arrays.fill(buf12, 0f);
            }
            if (vb >= 0 && vb + 12 <= maptexbuf.capacity()) {
                maptexbuf.position(vb);
                maptexbuf.put(buf12);
            }
            tmappos = tmappos + 6;
            maptcount = tmappos;
            return vb;
        }

