        int uiWhiteTex;

        @Override
        public void onSurfaceCreated(GL10 gl, EGLConfig config) {
            Thread th = Thread.currentThread();
            th.setPriority(Thread.NORM_PRIORITY);
            if (!netgame) pause = true;
            GLES30.glClearColor(0f, 0f, 0f, 1f);
            GLES30.glEnable(GLES30.GL_BLEND);
            GLES30.glBlendFunc(GLES30.GL_SRC_ALPHA, GLES30.GL_ONE_MINUS_SRC_ALPHA);
            GLES30.glPixelStorei(GLES30.GL_UNPACK_ALIGNMENT, 1);
            Matrix.setLookAtM(mViewMatrix, 0, 0, 0, 1, 0, 0, -1, 0, 1, 0);

            final String vertexShader =
                    "#version 300 es\n"
                            + "uniform mat4 u_MVPMatrix;\n"
                            + "uniform vec4 u_Color;\n"
                            + "in vec4 a_Position;\n"
                            + "in vec2 a_TexCoordinate;\n"
                            + "in float a_alfa;\n"
                            + "out vec4 v_Color;\n"
                            + "out vec2 v_TexCoordinate;\n"
                            + "void main() {\n"
                            + "    v_Color = u_Color;\n"
                            + "    v_Color.a += a_alfa;\n"
                            + "    v_TexCoordinate = a_TexCoordinate;\n"
                            + "    gl_Position = u_MVPMatrix * a_Position;\n"
                            + "}\n";

            final String fragmentShader =
                    "#version 300 es\n"
                            + "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
                            + "precision highp float;\n"
                            + "#else\n"
                            + "precision mediump float;\n"
                            + "#endif\n"
                            + "uniform sampler2D u_Texture;\n"
                            + "in vec4 v_Color;\n"
                            + "in vec2 v_TexCoordinate;\n"
                            + "out vec4 fragColor;\n"
                            + "void main() {\n"
                            + "    fragColor = v_Color + texture(u_Texture, v_TexCoordinate);\n"
                            + "}\n";

            final String mapvertexShader =
                    "#version 300 es\n"
                            + "uniform mat4 u_MVPMatrix;\n"
                            + "in vec4 a_Position;\n"
                            + "in vec2 a_TexCoordinate;\n"
                            + "out vec2 v_TexCoordinate;\n"
                            + "void main() {\n"
                            + "    v_TexCoordinate = a_TexCoordinate;\n"
                            + "    gl_Position = u_MVPMatrix * a_Position;\n"
                            + "}\n";

            final String mapfragmentShader =
                    "#version 300 es\n"
                            + "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
                            + "precision highp float;\n"
                            + "#else\n"
                            + "precision mediump float;\n"
                            + "#endif\n"
                            + "uniform sampler2D u_Texture;\n"
                            + "in vec2 v_TexCoordinate;\n"
                            + "out vec4 fragColor;\n"
                            + "void main() {\n"
                            + "    fragColor = texture(u_Texture, v_TexCoordinate);\n"
                            + "}\n";

            final String bzvertexShader =
                    "#version 300 es\n"
                            + "uniform mat4 u_MVPMatrix;\n"
                            + "in vec4 a_Position;\n"
                            + "void main() {\n"
                            + "    gl_Position = u_MVPMatrix * a_Position;\n"
                            + "}\n";

            final String bzfragmentShader =
                    "#version 300 es\n"
                            + "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
                            + "precision highp float;\n"
                            + "#else\n"
                            + "precision mediump float;\n"
                            + "#endif\n"
                            + "uniform vec3 u_bzdata;\n"
                            + "uniform vec3 u_bznewdata;\n"
                            + "uniform vec4 u_ScreenData;\n"
                            + "out vec4 fragColor;\n"
                            + "void main() {\n"
                            + "    vec2 fcoord;\n"
                            + "    fcoord.x = gl_FragCoord.x/u_ScreenData.w * u_ScreenData.z - u_ScreenData.x;\n"
                            + "    fcoord.y = gl_FragCoord.y/u_ScreenData.w * u_ScreenData.z + u_ScreenData.y;\n"
                            + "    float dnew = distance(fcoord.xy, u_bznewdata.xy);\n"
                            + "    if (distance(fcoord.xy, u_bzdata.xy) < u_bzdata.z && (dnew < u_bznewdata.z || dnew > u_bznewdata.z+50.0/u_ScreenData.w)) {\n"
                            + "        fragColor = vec4(0.0, 0.0, 0.0, 0.0);\n"
                            + "    } else {\n"
                            + "        fragColor = vec4(0.0, 0.0, 0.0, 0.5);\n"
                            + "    }\n"
                            + "}\n";

            final String uivertexShader =
                    "#version 300 es\n"
                            + "uniform mat4 u_MVPMatrix;\n"
                            + "in vec2 a_Position;\n"
                            + "void main() {\n"
                            + "    gl_Position = u_MVPMatrix * vec4(a_Position, 0.0, 1.0);\n"
                            + "}\n";

            final String uifragmentShader =
                    "#version 300 es\n"
                            + "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
                            + "precision highp float;\n"
                            + "#else\n"
                            + "precision mediump float;\n"
                            + "#endif\n"
                            + "uniform vec4 d_Color;\n"
                            + "out vec4 fragColor;\n"
                            + "void main() {\n"
                            + "    fragColor = d_Color;\n"
                            + "}\n";

            int uivShader = GLES30.glCreateShader(GLES30.GL_VERTEX_SHADER);
            GLES30.glShaderSource(uivShader, uivertexShader);
            GLES30.glCompileShader(uivShader);

            int uifShader = GLES30.glCreateShader(GLES30.GL_FRAGMENT_SHADER);
            GLES30.glShaderSource(uifShader, uifragmentShader);
            GLES30.glCompileShader(uifShader);

            int vertexShaderHandle = GLES30.glCreateShader(GLES30.GL_VERTEX_SHADER);
            GLES30.glShaderSource(vertexShaderHandle, vertexShader);
            GLES30.glCompileShader(vertexShaderHandle);

            int fragmentShaderHandle = GLES30.glCreateShader(GLES30.GL_FRAGMENT_SHADER);
            GLES30.glShaderSource(fragmentShaderHandle, fragmentShader);
            GLES30.glCompileShader(fragmentShaderHandle);

            int mapvertexShaderHandle = GLES30.glCreateShader(GLES30.GL_VERTEX_SHADER);
            GLES30.glShaderSource(mapvertexShaderHandle, mapvertexShader);
            GLES30.glCompileShader(mapvertexShaderHandle);

            int mapfragmentShaderHandle = GLES30.glCreateShader(GLES30.GL_FRAGMENT_SHADER);
            GLES30.glShaderSource(mapfragmentShaderHandle, mapfragmentShader);
            GLES30.glCompileShader(mapfragmentShaderHandle);

            int bzvertexShaderHandle = GLES30.glCreateShader(GLES30.GL_VERTEX_SHADER);
            GLES30.glShaderSource(bzvertexShaderHandle, bzvertexShader);
            GLES30.glCompileShader(bzvertexShaderHandle);
            final int[] compileStatus = new int[1];
            GLES30.glGetShaderiv(bzvertexShaderHandle, GLES30.GL_COMPILE_STATUS, compileStatus, 0);
            if (compileStatus[0] == 0) {
                log("vertex shader error: " + GLES30.glGetShaderInfoLog(bzvertexShaderHandle));
                GLES30.glDeleteShader(bzvertexShaderHandle);
            }

            int bzfragmentShaderHandle = GLES30.glCreateShader(GLES30.GL_FRAGMENT_SHADER);
            GLES30.glShaderSource(bzfragmentShaderHandle, bzfragmentShader);
            GLES30.glCompileShader(bzfragmentShaderHandle);
            GLES30.glGetShaderiv(bzfragmentShaderHandle, GLES30.GL_COMPILE_STATUS, compileStatus, 0);
            if (compileStatus[0] == 0) {
                log("fragment shader error: " + GLES30.glGetShaderInfoLog(bzfragmentShaderHandle));
                GLES30.glDeleteShader(bzfragmentShaderHandle);
            }

            programHandle = GLES30.glCreateProgram();
            GLES30.glAttachShader(programHandle, vertexShaderHandle);
            GLES30.glAttachShader(programHandle, fragmentShaderHandle);
            GLES30.glBindAttribLocation(programHandle, 0, "a_Position");
            GLES30.glBindAttribLocation(programHandle, 1, "a_TexCoordinate");
            GLES30.glBindAttribLocation(programHandle, 2, "a_alfa");
            GLES30.glLinkProgram(programHandle);

            mapprogramHandle = GLES30.glCreateProgram();
            GLES30.glAttachShader(mapprogramHandle, mapvertexShaderHandle);
            GLES30.glAttachShader(mapprogramHandle, mapfragmentShaderHandle);
            GLES30.glBindAttribLocation(mapprogramHandle, 3, "a_Position");
            GLES30.glBindAttribLocation(mapprogramHandle, 4, "a_TexCoordinate");
            GLES30.glLinkProgram(mapprogramHandle);
            GLES30.glReleaseShaderCompiler();

            bzprogramHandle = GLES30.glCreateProgram();
            GLES30.glAttachShader(bzprogramHandle, bzvertexShaderHandle);
            GLES30.glAttachShader(bzprogramHandle, bzfragmentShaderHandle);
            GLES30.glBindAttribLocation(bzprogramHandle, 5, "a_Position");
            GLES30.glLinkProgram(bzprogramHandle);
            GLES30.glReleaseShaderCompiler();

            uiprogramHandle = GLES30.glCreateProgram();
            GLES30.glAttachShader(uiprogramHandle, uivShader);
            GLES30.glAttachShader(uiprogramHandle, uifShader);
            GLES30.glBindAttribLocation(uiprogramHandle, 6, "a_Position");
            GLES30.glLinkProgram(uiprogramHandle);


            uiMVPHandle = GLES30.glGetUniformLocation(uiprogramHandle, "u_MVPMatrix");
            uiColor = GLES30.glGetUniformLocation(uiprogramHandle, "d_Color");
            uiPosHandle = GLES30.glGetAttribLocation(uiprogramHandle, "a_Position");

            mMVPMatrixHandle = GLES30.glGetUniformLocation(programHandle, "u_MVPMatrix");
            mTextureUniformHandle = GLES30.glGetUniformLocation(programHandle, "u_Texture");
            mPositionHandle = GLES30.glGetAttribLocation(programHandle, "a_Position");
            mTextureCoordinateHandle = GLES30.glGetAttribLocation(programHandle, "a_TexCoordinate");
            malfa = GLES30.glGetAttribLocation(programHandle, "a_alfa");
            mcolor = GLES30.glGetUniformLocation(programHandle, "u_Color");

            mapmMVPMatrixHandle = GLES30.glGetUniformLocation(mapprogramHandle, "u_MVPMatrix");
            mapmTextureUniformHandle = GLES30.glGetUniformLocation(mapprogramHandle, "u_Texture");
            mapmPositionHandle = GLES30.glGetAttribLocation(mapprogramHandle, "a_Position");
            mapmTextureCoordinateHandle = GLES30.glGetAttribLocation(mapprogramHandle, "a_TexCoordinate");

            bzmMVPMatrixHandle = GLES30.glGetUniformLocation(bzprogramHandle, "u_MVPMatrix");
            bzu_bzdata = GLES30.glGetUniformLocation(bzprogramHandle, "u_bzdata");
            bzu_bznewdata = GLES30.glGetUniformLocation(bzprogramHandle, "u_bznewdata");
            bzu_screendata = GLES30.glGetUniformLocation(bzprogramHandle, "u_ScreenData");
            bzmPositionHandle = GLES30.glGetAttribLocation(bzprogramHandle, "a_Position");

            int[] tex = new int[1];
            GLES30.glGenTextures(1, tex, 0);
            uiWhiteTex = tex[0];

            GLES30.glBindTexture(GLES30.GL_TEXTURE_2D, uiWhiteTex);
            ByteBuffer bb = ByteBuffer.allocateDirect(4);
            bb.put((byte)0).put((byte)0).put((byte)0).put((byte)0).position(0);
            GLES30.glTexImage2D(GLES30.GL_TEXTURE_2D, 0, GLES30.GL_RGBA, 1, 1, 0,
                    GLES30.GL_RGBA, GLES30.GL_UNSIGNED_BYTE, bb);

            GLES30.glTexParameteri(GLES30.GL_TEXTURE_2D, GLES30.GL_TEXTURE_MIN_FILTER, GLES30.GL_NEAREST);
            GLES30.glTexParameteri(GLES30.GL_TEXTURE_2D, GLES30.GL_TEXTURE_MAG_FILTER, GLES30.GL_NEAREST);


            GLES30.glGenBuffers(vbocount, vbo, 0);
            int[] temp = new int[1];
            GLES30.glGenFramebuffers(1, temp, 0);
            mmapfboid = temp[0];
        }

