        void settvbo0() {//set start vertex buffer objekt/shader
            GLES30.glUseProgram(programHandle);
            GLES30.glUniform4f(mcolor, 0, 0, 0, 0);
            GLES30.glDisableVertexAttribArray(mPositionHandle);
            GLES30.glBindBuffer(GLES30.GL_ARRAY_BUFFER, vbo[0]);
            GLES30.glVertexAttribPointer(mPositionHandle, 2, GLES30.GL_FLOAT, false, 8, 0);
            GLES30.glEnableVertexAttribArray(mPositionHandle);
            GLES30.glDisableVertexAttribArray(mTextureCoordinateHandle);
            GLES30.glBindBuffer(GLES30.GL_ARRAY_BUFFER, vbo[1]);
            GLES30.glVertexAttribPointer(mTextureCoordinateHandle, 2, GLES30.GL_FLOAT, false, 8, 0);
            GLES30.glEnableVertexAttribArray(mTextureCoordinateHandle);
            GLES30.glDisableVertexAttribArray(malfa);
            GLES30.glBindBuffer(GLES30.GL_ARRAY_BUFFER, vbo[2]);
            GLES30.glVertexAttribPointer(malfa, 1, GLES30.GL_FLOAT, false, 4, 0);
            GLES30.glEnableVertexAttribArray(malfa);
        }
