            drawtext(x, y, tg, s, 1f, 1f, 1f, 0, false);
            y = y - st;
            s = ct.getString(R.string.juggernauts_killed) + userjugk;
            drawtext(x, y, tg, s, 1f, 1f, 1f, 0, false);
            y = y - st;
            s = ct.getString(R.string.ghosts_killed) + userghostk;
            drawtext(x, y, tg, s, 1f, 1f, 1f, 0, false);
            y = y - st;
            s = ct.getString(R.string.deaths) + userdeath;
            drawtext(x, y, tg, s, 1f, 1f, 1f, 0, false);
            float kdstat;
            if (userdeath != 0) {
                kdstat = (float) userenemk / userdeath;
            } else {
                kdstat = 0.0f;
            }
            String kdlevel = "";
            if (userenemk > 500 && userdeath > 200 && userscore > 15000) {
                if (userenemk * 90 > userscore * 3 && kdstat > 2.0) kdlevel = "[BotKiller]";
                if (kdstat < 1.00) kdlevel = "[Low]";
                if (kdstat >= 1.00 && kdstat < 1.50) kdlevel = "[Medium]";
                if (kdstat >= 1.50 && kdstat < 1.75) kdlevel = "[High]";
                if (kdstat >= 1.75) kdlevel = "[Pro]";
                if (kdstat >= 2.50) kdlevel = "[God]";
            }
            DecimalFormat df = new DecimalFormat("#.##");
            String formattedkdstat = df.format(kdstat);
            y = y - st;
            s = ct.getString(R.string.kdstatic) + formattedkdstat + " " + kdlevel;
            drawtext(x, y, tg, s, 1f, 1f, 1f, 0, false);
            y = (int) (y - st * 1.7f);
