        void drawUIRect(float x, float y, float wd, float hd, float r, float g, float b, float a) {

            float[] quad = {
                    x,      y,
                    x+wd,   y,
                    x,      y+hd,

                    x+wd,   y,
                    x+wd,   y+hd,
                    x,      y+hd
            };

            FloatBuffer fb = ByteBuffer.allocateDirect(quad.length * 4)
                    .order(ByteOrder.nativeOrder())
                    .asFloatBuffer();
            fb.put(quad).position(0);

            GLES30.glUseProgram(uiprogramHandle);

            GLES30.glUniform4f(uiColor, r, g, b, a);

            GLES30.glBindBuffer(GLES30.GL_ARRAY_BUFFER, 0);

            GLES30.glVertexAttribPointer(uiPosHandle, 2, GLES30.GL_FLOAT, false, 8, fb);
            GLES30.glEnableVertexAttribArray(uiPosHandle);

            Matrix.orthoM(mProjectionMatrix, 0, 0, w, 0, h, 0, 1);
            Matrix.multiplyMM(mPVmatrix, 0, mProjectionMatrix, 0, mViewMatrix, 0);

            Matrix.setIdentityM(mModelMatrix, 0);
            Matrix.multiplyMM(mMVPMatrix, 0, mPVmatrix, 0, mModelMatrix, 0);
            GLES30.glUniformMatrix4fv(uiMVPHandle, 1, false, mMVPMatrix, 0);
            GLES30.glDrawArrays(GLES30.GL_TRIANGLES, 0, 6);
            settvbo0();
        }

