        void drawsleep() {//прорисовка ослепления
            float[] buf4 = new float[4];
            for (int i = 0; i < maxunittr; i++) {
                if (usos[i] > 0) usos[i] = usos[i] - sosspd;
                if (usos[i] < 0) usos[i] = 0;
            }
            for (int i = 0; i < bug_count; i++) {
                if (bugsos[i] > 0) bugsos[i] = bugsos[i] - sosspd;
                if (bugsos[i] < 0) bugsos[i] = 0;
            }
            int pid = plid;
            if (pid == -1) return;
            if (utip[pid] == -1 || utip[pid] == 5) return;
            if (usos[pid] != oldplsos) {
                float a = usos[pid];
                if (a > 1) a = 1;
                a = a - 1;
                Arrays.fill(buf4, a);
                abuffer.position(slppos);
                abuffer.put(buf4);
                abuffer.position(mapslppos);
                abuffer.put(buf4);
                bufacopy = true;
                GLES30.glBindTexture(GLES30.GL_TEXTURE_2D, slptex);
                GLES30.glDrawArrays(GLES30.GL_TRIANGLE_STRIP, slppos, 4);
                oldplsos = usos[pid];
            }
        }

