        void drawbug(float xs, float ys) {//прорисовка жуков
            GLES30.glDisableVertexAttribArray(mapmPositionHandle);
            GLES30.glBindBuffer(GLES30.GL_ARRAY_BUFFER, vbo[23]);
            GLES30.glVertexAttribPointer(mapmPositionHandle, 2, GLES30.GL_FLOAT, false, 8, 0);
            GLES30.glEnableVertexAttribArray(mapmPositionHandle);
            GLES30.glDisableVertexAttribArray(mapmTextureCoordinateHandle);
            GLES30.glBindBuffer(GLES30.GL_ARRAY_BUFFER, vbo[24]);
            GLES30.glVertexAttribPointer(mapmTextureCoordinateHandle, 2, GLES30.GL_FLOAT, false, 8, 0);
            GLES30.glEnableVertexAttribArray(mapmTextureCoordinateHandle);
            if (xs < -mapw + w) {
                xs = -mapw + w;
            }
            if (xs > 0) {
                xs = 0;
            }
            if (ys < 0) {
                ys = 0;
            }
            if (ys > maph - h) {
                ys = maph - h;
            }
            int xsw = (int) (-xs + w);
            int ysw = (int) (ys + h);
            int rd2, vb, a, td, tip;
            double d;
            boolean prov;
            float[] buf12 = new float[12];
            float[] buf4x = new float[4];
            float[] buf4y = new float[4];
            for (int i = 0; i < bug_count; i++) {
                tip = bugtip[i];
                if (bugclear[i]) {
                    clearbug(i);
                    bugclear[i] = false;
                }
                if (tip < 0 || tip >= maxtbug) continue;
                td = bugtd[i];
                if (td < 0 || td >= maxbugd) td = 0;
                if (netgame && netserver == 1) {
                    if (bugat[i] != bugoldat[i] || td != bugoldtd[i]) {
                        bugoldtd[i] = td;
                        bugoldat[i] = bugat[i];
                        sendbugtd(i, td, bugat[i]);
                    }
                }
                if (td == 2) {
                    if (bugat[i]) bugantimer[i]++;
                } else {
                    bugantimer[i]++;
                }
                if (bugantimer[i] > buganper[i]) {
                    bugantimer[i] = 0;
                    bugtk[i][td]++;
                    if (bugtk[i][td] >= bugmaxk[i][td]) {
                        bugtk[i][td] = 0;
                        if (bugat[i]) bugat[i] = false;
                    }
                }
                rd2 = bugraz[i] / 2;
                vb = bugvb[i] * 2;
                prov = (bugx[i] + rd2 >= -xs && bugx[i] - rd2 < xsw && bugy[i] + rd2 >= ys && bugy[i] - rd2 < ysw);
                if (prov) {
                    bugdraw[i] = true;
                    int texid = bugtex[tip][td][bugtk[i][td]];
                    buf12[0] = texx1[texid];
                    buf12[1] = texy2[texid];
                    buf12[2] = texx1[texid];
                    buf12[3] = texy1[texid];
                    buf12[4] = texx2[texid];
                    buf12[5] = texy2[texid];
                    buf12[6] = texx1[texid];
                    buf12[7] = texy1[texid];
                    buf12[8] = texx2[texid];
                    buf12[9] = texy2[texid];
                    buf12[10] = texx2[texid];
                    buf12[11] = texy1[texid];
                    bugtexbuf.position(vb);
                    bugtexbuf.put(buf12);
                    bugtexcopy = true;
                    setbugtexminmax(i);

                    if (bugugol[i] != bugoldugol[i]) {
                        d = sqrt2 * rd2;
                        a = bugugol[i] - 90;
                        for (int t = 0; t < 4; t++) {
                            buf4x[t] = (float) (d * Math.sin(Math.toRadians(a + 45)));
                            buf4y[t] = (float) (-d * Math.cos(Math.toRadians(a + 45)));
                            a = a - 90;
                            bugoldvbx[i][t] = buf4x[t];
                            bugoldvby[i][t] = buf4y[t];
                        }
                    } else {
                        for (int t = 0; t < 4; t++) {
                            buf4x[t] = bugoldvbx[i][t];
                            buf4y[t] = bugoldvby[i][t];
                        }
                    }

                    if (bugugol[i] != bugoldugol[i] || bugx[i] != bugoldx[i] || bugy[i] != bugoldy[i]) {
                        bugoldugol[i] = bugugol[i];
                        bugoldx[i] = bugx[i];
                        bugoldy[i] = bugy[i];
                        buf12[0] = buf4x[0] + bugx[i];
                        buf12[1] = buf4y[0] + bugy[i];
                        buf12[2] = buf4x[1] + bugx[i];
                        buf12[3] = buf4y[1] + bugy[i];
                        buf12[4] = buf4x[3] + bugx[i];
                        buf12[5] = buf4y[3] + bugy[i];
                        buf12[6] = buf4x[1] + bugx[i];
                        buf12[7] = buf4y[1] + bugy[i];
                        buf12[8] = buf4x[3] + bugx[i];
                        buf12[9] = buf4y[3] + bugy[i];
                        buf12[10] = buf4x[2] + bugx[i];
                        buf12[11] = buf4y[2] + bugy[i];
                        bugverbuf.position(bugvb[i] * 2);
                        bugverbuf.put(buf12);
                        bugvbcopy = true;
                        setbugvbminmax(i);
                    }
                } else {
                    if (bugdraw[i]) {
                        clearbug(i);
                        bugoldugol[i] = -1000;
                    }
                }
            }
            if (bug_count > oldbug_count) {
                clearbug(bug_count - 1);
                bugtexcopy = true;
                setbugtexminmax(bug_count - 1);
                oldbug_count = bug_count;
            }
            copybugbuf();
            GLES30.glBindTexture(GLES30.GL_TEXTURE_2D, bug_tex);
            GLES30.glDrawArrays(GLES30.GL_TRIANGLES, 0, bug_count * 6);
        }

