        void drawlife(float xs, float ys) {//прорисовка полосы жизни
            if (gtype != 3 && gtype != 5) return;
            GLES30.glUseProgram(mapprogramHandle);
            GLES30.glDisableVertexAttribArray(mapmPositionHandle);
            GLES30.glBindBuffer(GLES30.GL_ARRAY_BUFFER, vbo[0]);
            GLES30.glVertexAttribPointer(mapmPositionHandle, 2, GLES30.GL_FLOAT, false, 8, 0);
            GLES30.glEnableVertexAttribArray(mapmPositionHandle);
            GLES30.glDisableVertexAttribArray(mapmTextureCoordinateHandle);
            GLES30.glBindBuffer(GLES30.GL_ARRAY_BUFFER, vbo[1]);
            GLES30.glVertexAttribPointer(mapmTextureCoordinateHandle, 2, GLES30.GL_FLOAT, false, 8, 0);
            GLES30.glEnableVertexAttribArray(mapmTextureCoordinateHandle);
            float lw = 3;
            if (xs < -mapw + w) {
                xs = -mapw + w;
            }
            if (xs > 0) {
                xs = 0;
            }
            if (ys < 0) {
                ys = 0;
            }
            if (ys > maph - h) {
                ys = maph - h;
            }
            int xsw = (int) (-xs + w);
            int ysw = (int) (ys + h);
            float raz = tobraz[34] - 22;
            float rd2 = raz / 2;
            float yo = 20;
            int i = -1;
            float[] buf8 = new float[8];
            for (int t = 0; t < 2; t++) {
                if (t == 0) i = bbaseid;
                if (t == 1 && gtype == 3) i = rbaseid;
                if (i < 0 || i >= maxob) continue;
                if (obtip[i] != 34 && obtip[i] != 35) continue;
                if (obx[i] + rd2 >= -xs && obx[i] - rd2 < xsw && oby[i] + rd2 >= ys && oby[i] - rd2 < ysw) {
                    int vb = lifepos * 2;
                    if (obx[i] != loldx || oby[i] != loldy) {
                        buf8[0] = obx[i] - rd2;
                        buf8[1] = oby[i] + rd2 + yo;
                        buf8[2] = buf8[0];
                        buf8[3] = oby[i] + rd2 + lw + yo;
                        buf8[4] = obx[i] + rd2;
                        buf8[5] = buf8[1];
                        buf8[6] = buf8[4];
                        buf8[7] = buf8[3];
                        vertexBuffer.position(vb);
                        vertexBuffer.put(buf8);
                    }

                    GLES30.glBindTexture(GLES30.GL_TEXTURE_2D, ser);
                    GLES30.glDrawArrays(GLES30.GL_TRIANGLE_STRIP, lifepos, 4);

                    if (obx[i] != loldx || oby[i] != loldy || oblife[i] != loldlife) {
                        float lpos = raz * ((float) oblife[i] / toblife[34]);
                        buf8[0] = obx[i] - rd2;
                        buf8[1] = oby[i] + rd2 + yo;
                        buf8[2] = buf8[0];
                        buf8[3] = oby[i] + rd2 + lw + yo;
                        buf8[4] = obx[i] + lpos - rd2;
                        buf8[5] = buf8[1];
                        buf8[6] = buf8[4];
                        buf8[7] = buf8[3];
                        vertexBuffer.position(vb + 8);
                        vertexBuffer.put(buf8);
                    }
                    loldx = obx[i];
                    loldy = oby[i];
                    loldlife = oblife[i];
                    GLES30.glBindTexture(GLES30.GL_TEXTURE_2D, zel);
                    GLES30.glDrawArrays(GLES30.GL_TRIANGLE_STRIP, lifepos + 4, 4);
                }
            }
        }

