        void drawplane() {
            float[] buf12 = new float[12];
            float[] buf4x = new float[4];
            float[] buf4y = new float[4];
            double a, d;
            final float razd2 = 100 * planedrawms;
            int pid = plid;
            settvbo0();
            d = sqrt2 * razd2;
            a = planeUgol - pid2;
            for (int t = 0; t < 4; t++) {
                buf4x[t] = (float) (d * Math.sin(a + pid4));
                buf4y[t] = (float) (-d * Math.cos(a + pid4));
                a = a - pid2;
            }
            buf12[0] = buf4x[0] + planeX;
            buf12[1] = buf4y[0] + planeY;
            buf12[2] = buf4x[1] + planeX;
            buf12[3] = buf4y[1] + planeY;
            buf12[4] = buf4x[3] + planeX;
            buf12[5] = buf4y[3] + planeY;
            buf12[6] = buf4x[1] + planeX;
            buf12[7] = buf4y[1] + planeY;
            buf12[8] = buf4x[3] + planeX;
            buf12[9] = buf4y[3] + planeY;
            buf12[10] = buf4x[2] + planeX;
            buf12[11] = buf4y[2] + planeY;
            vertexBuffer.position(planevb * 2);
            vertexBuffer.put(buf12);
            if (pid == -1 || uplane[pid]) {
                xs = -planeX + wd2 * drawms;
                ys = planeY - hd2 * drawms;
                if (xs < -mapw + w * drawms) {
                    xs = -mapw + w * drawms;
                }
                if (xs > 0) {
                    xs = 0;
                }
                if (ys < 0) {
                    ys = 0;
                }
                if (ys > maph - h * drawms) {
                    ys = maph - (int) (h * drawms);
                }
            }
            GLES30.glBindTexture(GLES30.GL_TEXTURE_2D, planetex);
            GLES30.glDrawArrays(GLES30.GL_TRIANGLES, planevb, 6);
        }

        void drawblackzone(boolean minimap, float xs, float ys, float drawms, float vpx, float vpy) {//прорисовка black zone v battle royale
            if (blrad == 0 || rs == 0) return;
            float rad = bloldrad * rs;
            GLES30.glUseProgram(bzprogramHandle);
            GLES30.glDisableVertexAttribArray(bzmPositionHandle);
            GLES30.glBindBuffer(GLES30.GL_ARRAY_BUFFER, vbo[0]);
            GLES30.glVertexAttribPointer(bzmPositionHandle, 2, GLES30.GL_FLOAT, false, 8, 0);
            GLES30.glEnableVertexAttribArray(bzmPositionHandle);
            GLES30.glUniform3f(bzu_bzdata, getnormalizedcoord(bloldcx * rs, rad), getnormalizedcoord(bloldcy * rs, rad), 2);
            GLES30.glUniform3f(bzu_bznewdata, getnormalizedcoord(blcx * rs, rad), getnormalizedcoord(blcy * rs, rad), getnormalizedcoord(blrad * rs, rad));
            GLES30.glUniformMatrix4fv(bzmMVPMatrixHandle, 1, false, mMVPMatrix, 0);
            GLES30.glUniform4f(bzu_screendata, getnormalizedcoord((xs + vpx * drawms) * rs, rad), getnormalizedcoord((ys - vpy * drawms) * rs, rad), drawms, rad / 2);
            if (minimap) {
                Matrix.orthoM(mProjectionMatrix, 0, 0, mmaptexw * mmapms, 0, mmaptexh * mmapms, 0, 1);
                Matrix.multiplyMM(mPVmatrix, 0, mProjectionMatrix, 0, mViewMatrix, 0);
                Matrix.setIdentityM(mModelMatrix, 0);
                Matrix.multiplyMM(mMVPMatrix, 0, mPVmatrix, 0, mModelMatrix, 0);
                GLES30.glUniformMatrix4fv(bzmMVPMatrixHandle, 1, false, mMVPMatrix, 0);
            }
            GLES30.glDrawArrays(GLES30.GL_TRIANGLES, blvb, 6);
            settvbo0();
        }

        float getnormalizedcoord(float coord, float max) {
            return coord * 2 / max;
        }
