        void drawsmk(float xs, float ys) {//прорисовка дыма
            GLES30.glUseProgram(programHandle);
            GLES30.glUniformMatrix4fv(mMVPMatrixHandle, 1, false, mMVPMatrix, 0);
            GLES30.glDisableVertexAttribArray(mPositionHandle);
            GLES30.glBindBuffer(GLES30.GL_ARRAY_BUFFER, vbo[14]);
            GLES30.glVertexAttribPointer(mPositionHandle, 2, GLES30.GL_FLOAT, false, 8, 0);
            GLES30.glEnableVertexAttribArray(mPositionHandle);
            GLES30.glDisableVertexAttribArray(mTextureCoordinateHandle);
            GLES30.glBindBuffer(GLES30.GL_ARRAY_BUFFER, vbo[15]);
            GLES30.glVertexAttribPointer(mTextureCoordinateHandle, 2, GLES30.GL_FLOAT, false, 8, 0);
            GLES30.glEnableVertexAttribArray(mTextureCoordinateHandle);
            GLES30.glDisableVertexAttribArray(malfa);
            GLES30.glBindBuffer(GLES30.GL_ARRAY_BUFFER, vbo[16]);
            GLES30.glVertexAttribPointer(malfa, 1, GLES30.GL_FLOAT, false, 4, 0);
            GLES30.glEnableVertexAttribArray(malfa);
            if (xs < -mapw + w * drawms) {
                xs = (int) (-mapw + w * drawms);
            }
            if (xs > 0) {
                xs = 0;
            }
            if (ys < 0) {
                ys = 0;
            }
            if (ys > maph - h * drawms) {
                ys = (int) (maph - h * drawms);
            }
            float a;
            float rud2;
            double d;
            boolean prov;
            float xsw = -xs + w * drawms;
            float ysw = ys + h * drawms;
            int tip;
            float[] buf12 = new float[12];
            float[] buf6 = new float[6];
            float[] buf4x = new float[4];
            float[] buf4y = new float[4];
            for (int i = 12; i < maxsmk; i++) {
                tip = smtip[i];
                if (smbufclear[i]) {
                    clearsmk(i);
                    smbufclear[i] = false;
                }
                if (smbufadd[i]) {
                    clearsmk(i);
                    smktexcopy = true;
                    smkacopy = true;
                    setsmkalminmax(i);
                    setsmktexminmax(i);
                    smbufadd[i] = false;
                }
                if (tip == -1) continue;
                if (smraz[i] < 600) smraz[i] = smraz[i] + smspd[i]; //1556 Размер дыма мб
                smfraz[i] = smraz[i] / 1.75f;
                if (smtimer[i] > 0) smtimer[i]--;
                if (smtimer[i] == 0 || smraz[i] == 0 || smal[i] < -1) {
                    smtimer[i] = -1;
                    if (smdraw[i]) clearsmk(i);
                    smtip[i] = -1;
                    if (i - 11 == smkcount) {
                        int nextCount = 0;
                        for (int t = i - 1; t >= 12; t--) {
                            if (smtip[t] != -1) {
                                nextCount = t - 11;
                                break;
                            }
                        }
                        smkcount = nextCount;
                    }
                    continue;
                }
                if (smtimer[i] <= smperzat[i]) {
                    smal[i] = smtimer[i] / (float) (smperzat[i]) - 1 + smnal[i];
                }
                rud2 = smraz[i] / 2;
                prov = (smx[i] + rud2 >= -xs && smx[i] - rud2 < xsw && smy[i] + rud2 >= ys && smy[i] - rud2 < ysw);
                if (prov) {
                    smdraw[i] = true;
                    if (smtex[tip] != smoldtex[i]) {
                        int texid = smtex[tip];
                        smoldtex[i] = texid;
                        buf12[0] = texx1[texid];
                        buf12[1] = texy2[texid];
                        buf12[2] = texx2[texid];
                        buf12[3] = texy2[texid];
                        buf12[4] = texx1[texid];
                        buf12[5] = texy1[texid];
                        buf12[6] = texx2[texid];
                        buf12[7] = texy2[texid];
                        buf12[8] = texx1[texid];
                        buf12[9] = texy1[texid];
                        buf12[10] = texx2[texid];
                        buf12[11] = texy1[texid];
                        smktexbuf.position(smvb[i] * 2);
                        smktexbuf.put(buf12);
                        smktexcopy = true;
                        setsmktexminmax(i);
                    }
                    d = sqrt2 * rud2;
                    a = smugol[i] - 90;
                    for (int t = 0; t < 4; t++) {
                        buf4x[t] = (float) (d * Math.sin(Math.toRadians(a + 45)));
                        buf4y[t] = (float) (-d * Math.cos(Math.toRadians(a + 45)));
                        a = a - 90;
                    }
                    buf12[0] = buf4x[0] + smx[i];
                    buf12[1] = buf4y[0] + smy[i];
                    buf12[2] = buf4x[1] + smx[i];
                    buf12[3] = buf4y[1] + smy[i];
                    buf12[4] = buf4x[3] + smx[i];
                    buf12[5] = buf4y[3] + smy[i];
                    buf12[6] = buf4x[1] + smx[i];
                    buf12[7] = buf4y[1] + smy[i];
                    buf12[8] = buf4x[3] + smx[i];
                    buf12[9] = buf4y[3] + smy[i];
                    buf12[10] = buf4x[2] + smx[i];
                    buf12[11] = buf4y[2] + smy[i];
                    smkverbuf.position(smvb[i] * 2);
                    smkverbuf.put(buf12);
                    smkvbcopy = true;
                    setsmkvbminmax(i);
                    if (smal[i] != smoldal[i]) {
                        smoldal[i] = smal[i];
                        Arrays.fill(buf6, smal[i]);
                        smkabuf.position(smvb[i]);
                        smkabuf.put(buf6);
                        smkacopy = true;
                        setsmkalminmax(i);
                    }
                } else {
                    if (smdraw[i]) clearsmk(i);
                }
            }
            copysmkbuf();
            GLES30.glBindTexture(GLES30.GL_TEXTURE_2D, smktex);
            GLES30.glDrawArrays(GLES30.GL_TRIANGLES, smkpos, smkcount * 6);
        }

