        void obpluse(int ind) {//использование объекта igrokom
            if (ind == -1) return;
            if (utip[ind] == -1 || utip[ind] == 2 || utip[ind] == 4 || utip[ind] == 5) return;
            if (ucarpos[ind] != -1 || ucarobid[ind] != -1 || ucartip[ind] != -1) {
                if (ind == plid) shopmenu = false;
                return;
            }
            if (ind == plid && carCoolDown > 0) return;
            if (ind == plid && shopmenu) {
                shopmenu = false;
                bn[3] = false;
                return;
            }
            double r, minr = 0;
            int iob = -1;
            int rad = obautouserad;
            int otip;
            int[] obs = getobs(unitXY.ux[ind] - obautouserad, unitXY.uy[ind] - obautouserad, unitXY.ux[ind] + obautouserad, unitXY.uy[ind] + obautouserad);
            for (int id : obs) {
                if (id == -1) break;
                otip = obtip[id];
                if (otip == -1 || (!obuse[id] && otip != 40 && otip != 74 && otip != 85) || otip == 4 || otip == 5 || otip == 36 || otip == 37 || (otip == 54 && obsnk1[id] == -1) || (otip == 54 && uteam[ind] == 0))
                    continue;
                if (otip == 74 || otip == 85) {
                    if (carCoolDown > 0) continue;
                    boolean hasSeat = (otip == 74) ? (obcaruid[id][0] == -1) : (obcaruid[id][0] == -1 || obcaruid[id][1] == -1);
                    if (!hasSeat) continue;
                }
                if (otip == 40) rad = (int) (obraz[id] / 2 + obautouserad);
                if (obx[id] < unitXY.ux[ind] + rad && obx[id] > unitXY.ux[ind] - rad && oby[id] < unitXY.uy[ind] + rad && oby[id] > unitXY.uy[ind] - rad) {
                    r = Math.sqrt((unitXY.ux[ind] - obx[id]) * (unitXY.ux[ind] - obx[id]) + (unitXY.uy[ind] - oby[id]) * (unitXY.uy[ind] - oby[id])) - obraz[id] / 2;
                    if (iob == -1) {
                        minr = r;
                        iob = id;
                    }
                    if (r < minr) {
                        minr = r;
                        iob = id;
                    }
                }
            }
            if (iob != -1) {
                otip = obtip[iob];
                if (otip == 4) {//apt
                    return;
                }
                if (otip == 5) {//patr
                    return;
                }
                if (otip == 40) {//gunshop
                    shopmenudownid = -1;
                    shopmenuupid = -1;
                    shopmenustr = 0;
                    shopmenuoldstr = -1;
                    if (!shopmenu) {
                        closeOtherGameWindows(8);
                    }
                    shopmenu = !shopmenu;
                    if (ind == plid) {
                        // сброс ходьбы при открытии магазина
                        lrt = false;
                        lrpid = -1;
                        lrpx = 0;
                        lrpy = 0;
                        unitXY.utx[ind] = unitXY.ux[ind];
                        unitXY.uty[ind] = unitXY.uy[ind];
                        if (usost[ind] == 1) usost[ind] = 0;
                        bn[3] = false;
                    }
                    if (shopmenu) {
                        resetShopTouches();
                    } else {
                        shopmenudownid = -1;
                        shopmenuupid = -1;
                        shopmenundownid = -1;
                        shopmenutouchpid = -1;
                    }
                    return;
                }
                if (otip == 74 || otip == 85) {
                    carCoolDown = 20;
                    if (ind == plid) {
                        shopmenu = false;
                        bn[3] = false;
                    }
                }
                if (!netgame || netserver == 1) {
                    obuse(ind, iob, obrid[iob], true);
                } else {
                    sendobuse(ind, iob, obrid[iob], true);
                }
            }
        }

