        void selectlocalmap(final datagame_localmap lm) {//vibor local custom map
            if (lm == null) return;
            if (gtype == 12 && glscreen != 11 && (lm.width < minbrmapw || lm.height < minbrmaph)) {
                showtoast(ct.getString(R.string.minimum_map_size) + minbrmapw + "x" + minbrmaph);
                return;
            }
            boolean add = true;
            for (int i = 0; i < gamemapslist.size(); i++) {
                datagame_selectedmap sm = gamemapslist.get(i);
                if (sm == null || !sm.custommap) continue;
                if (sm.mapuid.equals(lm.mapuid)) {
                    add = false;
                    selectedmap = new datagame_selectedmap(lm.mapname, lm.mapuid, lm.timestamp, lm.width, lm.height);
                    spmap.setSelection(i);
                    break;
                }
            }
            if (add) {
                runOnUiThread(() -> {

                    selectedmap = new datagame_selectedmap(lm.mapname, lm.mapuid, lm.timestamp, lm.width, lm.height);
                    gamemapslist.add(selectedmap);
                    spmapadapter.notifyDataSetChanged();
                    spmap.setSelection(gamemapslist.size() - 1);

                });
            }
            dialogid = -1;
            setacdialogid(dialogid);
            chscreen(3);
        }

        void saveonlinemap() {//zagruzit kartu na server
            int sel = lv1pos;
            if (sel < 0 || sel >= lmlist.size()) return;
            datagame_localmap lm = lmlist.get(sel);
            if (lm == null) return;
            if (!provonlinemap(lm.mapuid)) {
                showtoast(ct.getString(R.string.you_cannot_upload));
                return;
            }
            if (usersrvid == 0) {
                showtoast(ct.getString(R.string.login_error));
                return;
            }
            if (userscore < skayrux.shootout2d.sys_menu_socket_repository.INSTANCE.getMinScoreUploadMap()) {
                showtoast(ct.getString(R.string.you_need_more_scores_to_upload_map, skayrux.shootout2d.sys_menu_socket_repository.INSTANCE.getFormattedMinScoreUploadMap()));
                return;
            }
            if (memaph < 8 || memapw < 10) return;
            if (sendprofmaptimer > 0) return;
            sendprofmap();
        }

