        void clearmapeditor() {
            float[] buf12 = new float[12];
            stopthreads();
            cleardolist();
            memap.clear();
            drawms = 1;
            wd2 = w / 2;
            hd2 = h / 2;
            xs = 0;
            ys = 0;
            mecamx = 0;
            mecamy = 0;
            ob_count = 0;
            lrtx = lrcx;
            lrty = lrcy;
            lroldtx = -1;
            lroldty = -1;
            Arrays.fill(obtip, -1);
            int bufob = 0;
            for (int i = 0; i < maxob; i++) {
                obvb[i] = bufob;
                obverbuf.position(obvb[i] * 2);
                obverbuf.put(buf12);
                obtexbuf.position(obvb[i] * 2);
                obtexbuf.put(buf12);
                bufob = bufob + 6;
            }
            copyobbuf();
            maxmapk = maxmapw * maxmaph;
            setmapbuf(maxmapk);
        }

        void medeletemap(String mapuid) {//udalit kartu
            if (mapuid == null || mapuid.isEmpty()) return;
            if (savedmaps.contains(mapuid)) {
                savedmaps.remove(mapuid);
                savemapslist();
            }
            try {
                File mapfile = getFileStreamPath(mapuid + ".map");
                File obfile = getFileStreamPath(mapuid + ".ob");
                boolean res = false;
                if (mapfile.exists()) res = mapfile.delete();
                if (!res) {
                    showtoast(ct.getString(R.string.error_deleting_map));
                    return;
                }
                if (obfile.exists()) res = obfile.delete();
                if (!res) {
                    showtoast(ct.getString(R.string.error_deleting_map));
                    return;
                }
                delfrommapslist(mapuid);
            } catch (Exception e) {
                e.printStackTrace();
                showtoast(ct.getString(R.string.error_deleting_map));
                return;
            }
            showtoast(ct.getString(R.string.map_is_successfully_deleted));
        }

        void delfrommapslist(final String mapuid) {
            runOnUiThread(() -> {

                boolean res = false;
                for (int i = gamemapslist.size() - 1; i >= 0; i--) {
                    datagame_selectedmap sm = gamemapslist.get(i);
                    if (sm == null || !sm.custommap) continue;
                    if (mapuid.equals(sm.mapuid)) {
                        gamemapslist.remove(i);
                        res = true;

                    }
                    if (res) {
                        spmapadapter.notifyDataSetChanged();
                        if (gtype == 12) {
                            nmap = -1;
                            selectedmap = new datagame_selectedmap(getmapname(nmap), nmap);
                        } else {
                            spmap.setSelection(nmap - 1);
                            selectedmap = new datagame_selectedmap(getmapname(nmap), nmap);
                        }
                    }
                }
            });
        }

        void merenamemap(String mapuid, String mapname) {//pereimenovanie karti
            if (mapuid == null || mapname == null || mapuid.isEmpty() || mapname.isEmpty()) return;
            File mapfile = getFileStreamPath(mapuid + ".map");
            if (!mapfile.exists()) return;
            clearmapeditor();
            if (!meloadmapdata(mapfile, false, true)) return;
            if (!mapname.equals(memapname)) {
                memapname = mapname;
                mesavemapdata(mapuid + ".map");
            }
            clearmapeditor();
        }

        boolean meloadmapdata(File mapfile, boolean addkv, boolean mapeditor) {//zagruzit dannie karti
            try {
                DataInputStream dais = new DataInputStream(new FileInputStream(mapfile));
                byte ver = dais.readByte();//gameversion
                if (ver > gameversion) {
                    dais.close();
                    return false;
                }
                int mainkvcount = 0;
                if (mapeditor) {
                    memapname = dais.readUTF();
                    memapuid = dais.readUTF();
                    memapusrvid = dais.readInt();
                    if (memapusrvid == 0) memapusrvid = usersrvid;
                    dais.readInt();//gamerid
                    memapw = dais.readShort();
                    memaph = dais.readShort();
                    mainkvcount = memapw * memaph;
                } else {
                    dais.readUTF();
                    dais.readUTF();
                    dais.readInt();
                    dais.readInt();//gamerid
                    dais.readShort();
                    dais.readShort();
                }
                if (mapeditor) {
                    metimestamp = dais.readUTF();
                    int mmk = dais.readInt() + 5000;
                    if (mmk > maxmapk) maxmapk = mmk;
                } else {
                    dais.readUTF();//timestamp
                    maxmapk = dais.readInt();
                }
                setmapbuf(maxmapk);
                mapminx = dais.readShort();
                mapminy = dais.readShort();
                mapmaxx = dais.readShort();
                mapmaxy = dais.readShort();
                setmapvar();
                int kv = 0;
                while (dais.available() > 0) {
                    String texname = dais.readUTF();
                    byte svp = dais.readByte();
                    short x0 = dais.readShort();
                    short y0 = dais.readShort();
                    short x1 = dais.readShort();
                    short y1 = dais.readShort();
                    kv++;
                    int texind = -1;
                    MapEditorTexture metex = null;
                    for (int i = 0; i < metexlist.size(); i++) {
                        metex = metexlist.get(i);
                        if (metex.texname.equals(texname)) {
                            texind = i;
                            break;
                        }
                    }
                    if (texind == -1 || metex == null) continue;
                    int vb = 0;
                    if (addkv) vb = addmapkv(svp, metex.texid, x0, y0, x1, y1);
                    if (mapeditor) {
                        metexind = texind;
                        mesvp = svp;
                        memap.add(new GameMapKv(texname, metex.texid, texind, svp, x0, y0, x1, y1, vb, false, (kv <= mainkvcount)));
                    }
                }
                dais.close();
            } catch (IOException e) {
                e.printStackTrace();
                return false;
            }
            return true;
        }

        boolean meloadobdata(File obfile, boolean mapeditor) {//sagruzka dannich objektov
            if (mapeditor) {
                glscreen = 11;
            }
            loadmapob = true;
            oblist.clear();
            loadedobid = 0;
            int n = 0;
            boolean bpa = false, bpb = false;
            boolean bbase = false, rbase = false;
            boolean bflag = false, rflag = false;
            try {
                DataInputStream dais = new DataInputStream(new FileInputStream(obfile));
                byte ver = dais.readByte();//gameversion
                if (ver > gameversion) {
                    dais.close();
                    return false;
                }
                dais.readUTF();//timestamp
                while (dais.available() > 0) {
                    byte obtip = dais.readByte();
                    short x = dais.readShort();
                    short y = dais.readShort();
                    n++;
                    if (mapeditor) {
                        addob(-1, obtip, x, y, tobusnkobmax[obtip], tobusnkzapmax[obtip], toblife[obtip], false, rand.nextInt(), false, -1);
                    } else {
                        if (obtip == 34) bbase = true;
                        if (obtip == 35) rbase = true;
                        if (obtip == 36) bflag = true;
                        if (obtip == 37) rflag = true;
                        if (obtip == 55) bpa = true;
                        if (obtip == 56) bpb = true;
                        addloadedob(obtip, x, y, n);
                    }
                }
                dais.close();
            } catch (IOException e) {
                e.printStackTrace();
                return false;
            }
            if (!mapeditor) addbaob();
            loadmapob = false;
            if (mapeditor) {
                return true;
            } else {
                switch (gtype) {
                    case 3:
                        return (bbase && rbase);
                    case 4:
                        return (bflag && rflag);
                    case 5:
                        return bbase;
                    case 9:
                        return (bpa && bpb);
                    default:
                        return true;
                }
            }
        }

