    void setbotcommand(int comid, int uid, float x, float y) {//otdat prikas botam
        if (uid < 0 || uid >= maxunittr) return;
        if (utip[uid] == -1 || utip[uid] == 2 || utip[uid] == 3) return;
        final int maxb;
        if (ubot[uid]) {
            maxb = 2;
        } else {
            maxb = 5;
        }
        int bcount = 0;
        for (int i = 0; i < maxunittr; i++) {
            if (utip[i] == -1 || i == uid || !ubot[i] || uteam[i] != uteam[uid]) continue;
            if (unitXY.ux[uid] >= unitXY.ux[i] - botcomrad && unitXY.ux[uid] <= unitXY.ux[i] + botcomrad && unitXY.uy[uid] >= unitXY.uy[i] - botcomrad && unitXY.uy[uid] <= unitXY.uy[i] + botcomrad) {
                if (bcount >= maxb) break;
                bcount++;
                ucomid[i] = comid;
                ucomuid[i] = uid;
                ucomx[i] = (int) x;
                ucomy[i] = (int) y;
                switch (comid) {
                    case 2:
                        ucomtimer[i] = 450;
                        break;
                    case 4:
                        ucomtimer[i] = 600;
                        break;
                    case 5:
                        ucomtimer[i] = 600;
                        break;
                    default:
                        ucomtimer[i] = 0;
                }
                ucomtenable[i] = false;
                if (comid == -1) {
                    ucommsgid[i] = 1;
                    ucommsgtimer[i] = 60;
                    if (netgame) sendcommsg(1, i);
                }
                ustop(i);
            }
        }
    }

    void obrcomtimer() {//obrabotka timer prikasa
        for (int i = 0; i < maxunittr; i++) {
            if (ucomtenable[i]) {
                if (ucomtimer[i] > 0) {
                    ucomtimer[i]--;
                } else {
                    ucomtenable[i] = false;
                    ucomid[i] = -1;
                    ucommsgid[i] = -1;
                    ucommsgtimer[i] = 0;
                }
            }
        }
    }

    void initPlane() {//inizialisazija koordinat poleta
        try {
            brStart = true;
            drawms = planedrawms;
            planeX = 0;
            planeY = rand.nextInt(maph);
            planeEndX = mapw + 400;
            if (planeY < maph / 2) {
                planeEndY = maph / 2 + rand.nextInt(maph / 2);
            } else {
                planeEndY = rand.nextInt(maph / 2);
            }
            planeUgol = -2000;
            planeStart = true;
            if (netgame) sendplanedata(maxunit);
            float sd = 1100 * drawms;
            addsmk(0, planeX + wd2 * drawms, planeY, -0.6f, 10.0f, 700, 300, sd, rand.nextInt(360));
            if (netgame)
                sendaddsmk(0, planeX + wd2 * drawms, planeY, -0.6f, 10.0f, 700, 300, sd, rand.nextInt(360), maxunit);
            final int planed = (int) Math.sqrt(mapw * mapw + (planeEndY - planeY) * (planeEndY - planeY));
            oblsmktimer = 90;
            for (int i = 0; i < maxunittr; i++) {
                if (utip[i] == -1) continue;
                uplane[i] = true;
                if (netgame) senduplane(i, true, maxunit);
                if (i == plid) {
                    synchronized (cheatlock) {
                        udrawms[i] = planedrawms;
                        setacdrawms(planedrawms);
                    }
                } else {
                    udrawms[i] = planedrawms;
                }
                if (ubot[i]) {
                    int botplaned = rand.nextInt(planed);
                    if (planeUgol == -2000) {
                        int nx = (int) (mapw - planeX);
                        int ny = (int) (maph - planeY);
                        int kx = (int) (mapw - planeEndX);
                        int ky = (int) (maph - planeEndY);
                        double d = Math.sqrt((kx - nx) * (kx - nx) + (ky - ny) * (ky - ny));
                        if (d < 0.00001) d = 0.00001;
                        planeUgol = -(ky - ny) / d;
                        if (planeUgol > 1) planeUgol = 1;
                        if (planeUgol < -1) planeUgol = -1;
                        planeUgol = Math.acos(planeUgol);
                        if (kx < nx) planeUgol = pim2 - planeUgol;
                        int ugol = (int) Math.toDegrees(planeUgol);
                        if (ugol >= 360) ugol = ugol - 360;
                        if (ugol < 0) ugol = ugol + 360;
                        planeUgol = Math.toRadians(ugol);
                    }
                    ubotparx[i] = (float) (planeX - botplaned * Math.sin(planeUgol));
                    ubotpary[i] = (float) (planeY + botplaned * Math.cos(planeUgol));
                }
            }
        } catch (IllegalArgumentException e) {
            e.printStackTrace();
        }
    }

    void setblackzone(float rad) {//ustanovit radius black zone (server)
        if (netgame && netserver == 0) return;
        addsysmsg(16, -1, -1, true);
        blmovezad = 1500;
        if (blrad == 0) {
            float w = mapw - rad;
            float h = maph - rad;
            if (w < 1) w = 1;
            if (h < 1) h = 1;
            blcx = rand.nextInt((int) w) + rad / 2;
            blcy = rand.nextInt((int) h) + rad / 2;
            bloldcx = blcx;
            bloldcy = blcy;
            float[] d = new float[4];
            d[0] = (float) Math.sqrt((blcx - mapw) * (blcx - mapw) + (blcy - maph) * (blcy - maph));
            d[1] = (float) Math.sqrt(blcx * blcx + (blcy - maph) * (blcy - maph));
            d[2] = (float) Math.sqrt((blcx - mapw) * (blcx - mapw) + blcy * blcy);
            d[3] = (float) Math.sqrt(blcx * blcx + blcy * blcy);
            float maxd = 0;
            for (int i = 0; i < 4; i++) {
                if (d[i] > maxd) maxd = d[i];
            }
            bloldrad = maxd + 3000;
        } else {
            float rxmin = blcx - blrad + rad;
            float rymin = blcy - blrad + rad;
            float rxmax = blcx + blrad - rad - rxmin;
            float rymax = blcy + blrad - rad - rymin;
            if (rxmax < 1) rxmax = 1;
            if (rymax < 1) rymax = 1;
            blcx = rand.nextInt((int) rxmax) + rxmin;
            blcy = rand.nextInt((int) rymax) + rymin;
        }
        blrad = rad;
        if (netgame) sendnewblpos(maxunit);
    }

