    void killunit(int id, boolean local) {//kill unita
        if (id < 0 || id >= maxunittr) return;
        int zomk = 0, jugk = 0, ghostk = 0, enemk = 0, score;
        int flag = uflag[id];
        int slot = utslot[id];
        if (utip[id] == -1) {
            ukilled[id] = true;
            udeathtimer[id] = 65;
            uvisibletimer[id] = 0;
            uvisx[id] = (short) unitXY.ux[id];
            uvisy[id] = (short) unitXY.uy[id];
            uclear[id] = true;
            return;
        }
        if (!pause && newgametimer == 0 && !comnewgame) {
            if (utip[id] == 2) {
                soundManager.addsound(54, -1, unitXY.ux[id], unitXY.uy[id]); // Замена звука 6.1
            } else {
                if (utip[id] != 5) {
                    int uuid = upatuid[id];
                    if (uuid != -1) {
                        int rnd = rand.nextInt(3);
                        soundManager.addsound(rnd + 32, -1, unitXY.ux[id], unitXY.uy[id]);
                    }
                }
            }
        }
        int uid = upatuid[id];
        if (!unet[id]) local = true;
        if (local) {
            if (gtype == 8 && utip[id] == 3) {
                juggernextid = uid;
                if (netgame) sendnextjugid(uid);
            }
            if (gtype == 11 && utip[id] == 4) {
                // кандидат в призраки на след. раунд
                if (uid >= 0 && uid < maxunittr && untip[uid] != -1 && untip[uid] != 5) {
                    for (int i = 0; i < ghostcount; i++) {
                        if (ghostnextid[i] == uid) break;
                        if (ghostnextid[i] == -1) {
                            ghostnextid[i] = uid;
                            break;
                        }
                    }
                }
                if (netgame) sendnextghostid(maxunit);
            }
            if (utip[id] != 5) {
                addinfostr(uid, id, upatobtip[id], upatbugtip[id]);
                if (netgame) sendaddinfostr(uid, id, upatobtip[id], upatbugtip[id]);
            }
            int minplcount = 1;
            int plc = getplcount();
            if (gtype != 12 || brStart) {
                if (uid >= 0 && uid < maxunittr) {
                    if (uteam[id] != uteam[uid]) {
                        ukills[uid]++;
                        switch (utip[id]) {
                            case 2:
                                zomk++;
                                minplcount = 2;
                                break;
                            case 3:
                                jugk++;
                                minplcount = 2;
                                break;
                            case 4:
                                ghostk++;
                                minplcount = 2;
                                break;
                            default:
                                enemk++;
                                break;
                        }
                        score = uscore[id];
                        if (uid == plid) {
                            synchronized (cheatlock) {
                                int trueKills = acStatResolve(ukills[uid] - 1, acukills, ac2ukills) + 1;
                                ukills[uid] = trueKills;
                                setacukills(trueKills);
                                verifyAndRestoreStatsLocked();
                                setunitscore(id, utip[id], ubot[id]);
                                score = uscore[id];
                                if (upatobtip[id] != 44 && !uafk[id]) {
                                    if (onlinegame) {
                                        int victimTip = utip[id];
                                        boolean victimIsBot = ubot[id];
                                        int botDiff = uatraz[id];

                                        if (victimTip == 2) {
                                            if (victimIsBot) stat_kZombBot++; else stat_kZombPl++;
                                        } else if (victimTip == 3) {
                                            if (victimIsBot) {
                                                if (botDiff == 0) stat_kJugBotTerm++;
                                                else if (botDiff == 30) stat_kJugBotNorm++;
                                                else stat_kJugBotEasy++;
                                            } else {
                                                stat_kJugPl++;
                                            }
                                        } else if (victimTip == 4) {
                                            if (victimIsBot) stat_kGhostBot++; else stat_kGhostPl++;
                                        } else {
                                            if (victimIsBot) {
                                                if (botDiff == 0) stat_kBotTerm++;
                                                else if (botDiff == 30) stat_kBotNorm++;
                                                else stat_kBotEasy++;
                                            } else {
                                                stat_kPl++;
                                            }
                                        }

                                        usertmpzomk = usertmpzomk + zomk;
                                        usertmpjugk = usertmpjugk + jugk;
                                        usertmpghostk = usertmpghostk + ghostk;
                                        usertmpenemk = usertmpenemk + enemk;
                                        usertmpscore = usertmpscore + score;
                                        setactmpscore(usertmpscore);
                                        setacenemk(usertmpenemk);
                                        setaczomk(usertmpzomk);
                                        setacjugk(usertmpjugk);
                                        setacghostk(usertmpghostk);
                                    }
                                }
                                udengi[uid] = udengi[uid] + uzen;
                                if (gtype == 8 && utip[id] == 3)
                                    udengi[uid] = udengi[uid] + uzen * 4;
                                if (gtype == 11 && utip[id] == 4)
                                    udengi[uid] = udengi[uid] + uzen * 3;
                                udengi[uid] = Math.min(49999, udengi[uid]);
                                setacdengi(udengi[uid]);
                            }
                        } else {
                            if (upatobtip[id] != 44 && !uafk[id])
                                sendstat(uid, score, enemk, 0, zomk, jugk, ghostk, 0, uclientid[uid]);
                            udengi[uid] = udengi[uid] + uzen;
                            if (gtype == 8 && utip[id] == 3) udengi[uid] = udengi[uid] + uzen * 4;
                            if (gtype == 11 && utip[id] == 4) udengi[uid] = udengi[uid] + uzen * 3;
                            udengi[uid] = Math.min(49999, udengi[uid]);
                        }
                        if (gtype == 6 || gtype == 10) {
                            if (uteam[uid] == 0) {
                                tsbluescore++;
                                if (netgame) sendtsscore(false, -2000, 1);
                            }
                            if (uteam[uid] == 1) {
                                tsredscore++;
                                if (netgame) sendtsscore(false, 1, -2000);
                            }
                        }
                    } else {
                        if (id != uid) {
                            if (uid == plid) {
                                synchronized (cheatlock) {
                                    verifyAndRestoreStatsLocked();
                                    ukills[uid]--;
                                    setacukills(ukills[uid]);
                                    udengi[uid] = Math.max(-49999, udengi[uid] - uzen);
                                    if (onlinegame) {
                                        boolean victimIsBot = ubot[id];
                                        if (victimIsBot) stat_tkBot++; else stat_tkPl++;
                                        usertmpscore = usertmpscore - 40;
                                        setactmpscore(usertmpscore);
                                    }
                                    setacdengi(udengi[uid]);
                                }
                            } else {
                                ukills[uid]--;
                                udengi[uid] = Math.max(-49999, udengi[uid] - uzen);
                                score = -40;
                                sendstat(uid, score, 0, 0, 0, 0, 0, 0, uclientid[uid]);
                            }
                        }
                    }
                    sendunitscore(uid, ukills[uid], -2000, udengi[uid]);
                    if (gtype == 10 && !unet[uid] && ukills[uid] >= uoldkills[uid] + 2) {
                        uoldkills[uid] = uoldkills[uid] + 2;
                        incugt10wi(uid);
                    }
                    if (id == plid) {
                        if ((utip[uid] != 4 || untip[id] == 4) && utip[uid] != -1) {
                            chnablidtimer = 30;
                            chnablid = uid;
                        }
                        plnablid = -1;
                    }
                }
                if (utip[id] != 5) udeath[id]++;
                if (id == plid && utip[id] != 5) {
                    synchronized (cheatlock) {
                        int trueDeaths = Math.max(0, acStatResolve(udeath[id] - 1, acudeath, ac2udeath)) + 1;
                        udeath[id] = trueDeaths;
                        setacudeath(trueDeaths);
                        verifyAndRestoreStatsLocked();
                        if (onlinegame) {
                            usertmpdeath++;
                            if (upatbugtip[id] != -1) {
                                stat_dBug++;
                                usertmpscore = usertmpscore - 40;
                                setactmpscore(usertmpscore);
                            } else if (uid >= 0 && uid < maxunittr && uid != id) {
                                int killerTip = utip[uid];
                                boolean killerIsBot = ubot[uid];
                                int botDiff = uatraz[uid];
                                usertmpscore = usertmpscore - 20;

                                if (killerTip == 2) {
                                    if (killerIsBot) stat_dZombBot++; else stat_dZombPl++;
                                } else if (killerTip == 3) {
                                    if (killerIsBot) stat_dJugBot++; else stat_dJugPl++;
                                } else if (killerTip == 4) {
                                    if (killerIsBot) stat_dGhostBot++; else stat_dGhostPl++;
                                } else {
                                    if (killerIsBot) {
                                        if (botDiff == 0) stat_dBotTerm++;
                                        else if (botDiff == 30) stat_dBotNorm++;
                                        else stat_dBotEasy++;
                                    } else {
                                        stat_dPl++;
                                    }
                                }
                                setactmpscore(usertmpscore);
                            } else {
                                stat_dOther++;
                            }
                            setacdeath(usertmpdeath);
                        }
                    }
                }
                if (gtype == 10) {
                    if (!(uid >= 0 && uid < maxunittr && uteam[uid] != uteam[id])) uolddeath[id]++;
                    if (udeath[id] >= uolddeath[id] + 4) {
                        uolddeath[id] = uolddeath[id] + 4;
                        incugt10wi(id);
                    }
                }
                if (utip[id] != 5) sendunitscore(id, -2000, udeath[id], -2000);
            }
        }
        ustop(id);
        uatuid[id] = -1;
        uatbugid[id] = -1;
        uatobid[id] = -1;
        ubuycooltimer[id] = 0;
        ucoverob[id] = -1; // bot
        ucovertimer[id] = 0;
        uloiterob[id]    = -1;
        uloitertimer[id] =  0;
        //addanim(uunan[id], ux[id], uy[id]);
        if (local && utip[id] != 2 && utip[id] != 5) {
            if (slot >= 0 && slot < maxuslot) {
                int snar = usnar[id][slot];
                if (snar != -1 && usv[id] != 0 && tsntipp[snar] == 1 && usnkob[id][slot] > 0) {//бросок гранаты игроком
                    if (id == plid) {
                        synchronized (cheatlock) {
                            usnkob[id][slot]--;
                            setacsnkob(usnkob[id][slot], slot);
                        }
                    } else {
                        usnkob[id][slot]--;
                    }
                    if (netgame) sendpatr(id, slot, usnkob[id][slot], usnkzap[id][slot]);
                    addnet_localsnr(true, usnar[id][slot], unitXY.ux[id], unitXY.uy[id], uuron[id][slot], id, -1, -1, Math.toRadians(uugol[id]), 0, uksnv[id][slot], usnrazb[id][slot], 0, 0, uobtip[id][slot]);
                }
            }
            int xs = -50;
            for (int c = 0; c < maxuslot; c++) {
                if (c != 2 || usnkob[id][c] != 0 || usnkzap[id][c] != 0) {
                    if ((gtype != 12 || uobtip[id][c] != 84 || brStart) && (gtype == 1 || gtype == 7 || gtype == 8 || gtype == 9 || gtype == 11 || gtype == 12 || uobtip[id][c] != scr8slotob[c][scr8slotid[c]])) {
                        addob(-1, uobtip[id][c], unitXY.ux[id] + xs, unitXY.uy[id] - unitXY.ufrazw[id], usnkob[id][c], usnkzap[id][c], -2000, true, rand.nextInt(), true, id);
                        xs = xs + 50;
                    }
                }
            }
        }
        // заражение юнита при убийстве зомби
        boolean infectZombie = (local && gtype == 7 && uid >= 0 && uid < maxunittr && utip[id] != 2 && untip[id] != 2 && (untip[uid] == 2 || utip[uid] == 2 || upatobtip[id] == 47));
        if (id == plid) {
            synchronized (cheatlock) {
                utip[id] = -1;
                setacutip(-1);
            }
        } else {
            utip[id] = -1;
        }
        ucartip[id] = -1;
        int carobid = ucarobid[id];
        if (carobid >= 0 && carobid < maxob) {
            for (int c = 0; c < maxcarplcount; c++) {
                if (obcaruid[carobid][c] == id) {
                    if (c == 0) obspd[carobid] = 0;
                    obcaruid[carobid][c] = -1;
                }
            }
        }
        ucarobid[id] = -1;
        ucarpos[id] = -1;
        ukilled[id] = true;
        udeathtimer[id] = 65;
        uvisibletimer[id] = 0;
        uvisx[id] = (short) unitXY.ux[id];
        uvisy[id] = (short) unitXY.uy[id];
        unetvx[id] = 0f;
        unetvy[id] = 0f;
        unetmovetimer[id] = 0;
        unettx[id] = unitXY.ux[id];
        unetty[id] = unitXY.uy[id];
        uclear[id] = true;
        if (local) {
            if (uteam[id] != 2 || gtype == 2 || gtype == 12)
                addob(-1, 9, unitXY.ux[id], unitXY.uy[id], 0, 0, toblife[9], false, rand.nextInt(), true, id); //bugg
            if (flag != -1) {
                float fx, fy;
                float st = 36;
                fx = (float) (unitXY.ux[id] + st * Math.sin(Math.toRadians(uugol[id])));
                fy = (float) (unitXY.uy[id] - st * Math.cos(Math.toRadians(uugol[id])));
                addob(-1, 36 + flag, fx, fy, 0, 0, toblife[36 + flag], true, rand.nextInt(), true, id);
            }
        }
        if (local && netgame) {
            sendkillunit(id, maxunit);
            if (gtype == 7) sendgamedata();
        }
        if (local) {
            if (infectZombie) {
                dozombie(id);
            }
            if (gtype == 2) {
                urestimer[id] = 150; //
            }
            if (gtype == 3 || gtype == 4 || gtype == 5 || gtype == 6 || gtype == 10 || (gtype == 12 && !brStart)) {
                if (uteam[id] != 2) urestimer[id] = 300;
            }
        }
    }

