    final Object drawtextlock = new Object();

    void drawtext(float x, float y, float mn, String txt, float pr, float pg, float pb, float pa, boolean vertical) {//вывод текста
        if (txt == null) return;
        synchronized (drawtextlock) {
            float tx = x;
            float ty = y;
            int len = 0;
            int txtlen = txt.length();
            int startvb = textvb;
            int n, tind, sind;
            boolean res = false;
            for (int i = 0; i < txtlen; i++) {
                tind = txtind;
                if (tind >= maxscrtxt) break;
                n = txt.charAt(i);
                if (n == 8212 || n == 8211) n = 45;
                for (int t = 0; t < maxchar; t++) {
                    if (n == chid[t]) {
                        res = true;
                        len++;
                        if (t != txtchid[tind] || tx != txtx[tind] || ty != txty[tind] || mn != txtmn[tind]) {
                            txtchid[tind] = t;
                            txtx[tind] = tx;
                            txty[tind] = ty;
                            txtmn[tind] = mn;
                            txtvertical[tind] = vertical;
                            txtbufredraw[tind] = true;
                        }
                        if (vertical) {
                            ty = (int) (ty - chxa[t] * mn);
                        } else {
                            tx = (int) (tx + chxa[t] * mn);
                        }
                        if (i == 0) startvb = txtvb[tind];
                        tind++;
                        txtind = tind;
                        break;
                    }
                }
                if (!res) {
                    len++;
                    if (0 != txtchid[tind] || tx != txtx[tind] || ty != txty[tind] || mn != txtmn[tind]) {
                        txtchid[tind] = 0;
                        txtx[tind] = tx;
                        txty[tind] = ty;
                        txtmn[tind] = mn;
                        txtvertical[tind] = vertical;
                        txtbufredraw[tind] = true;
                    }
                    if (vertical) {
                        ty = (int) (ty - chxa[0] * mn);
                    } else {
                        tx = (int) (tx + chxa[0] * mn);
                    }
                    if (i == 0) startvb = txtvb[tind];
                    tind++;
                    txtind = tind;
                }
            }
            sind = scrtxt_ind;
            if (sind != 0) {
                if (pr == scrtxt_pr[sind - 1] && pg == scrtxt_pg[sind - 1] && pb == scrtxt_pb[sind - 1]
                        && pa == scrtxt_pa[sind - 1]) {
                    scrtxt_c[sind - 1] = scrtxt_c[sind - 1] + len * 6;
                } else {
                    scrtxt_vb[sind] = startvb;
                    scrtxt_c[sind] = len * 6;
                    scrtxt_pr[sind] = pr;
                    scrtxt_pg[sind] = pg;
                    scrtxt_pb[sind] = pb;
                    scrtxt_pa[sind] = pa;
                    sind++;
                    scrtxt_ind = sind;
                }
            } else {
                scrtxt_vb[sind] = startvb;
                scrtxt_c[sind] = len * 6;
                scrtxt_pr[sind] = pr;
                scrtxt_pg[sind] = pg;
                scrtxt_pb[sind] = pb;
                scrtxt_pa[sind] = pa;
                sind++;
                scrtxt_ind = sind;
            }
        }
    }

    void sendchatmsg(int uid, int sid, String name, String msg, boolean toall) {//отправить сообщение в чат
        if (!toall && uid == -1) return;
        ByteArrayOutputStream baos = null;
        DataOutputStream daos;
        boolean sentToOnlineServer = false;
        for (int i = 0; i < maxunittr; i++) {
            if (ubot[i] || !unet[i] || i == uid) continue;
            if (!toall && (uteam[i] != uteam[uid])) continue;
            int ii;
            if (i == plid) {
                synchronized (cheatlock) {
                    ii = uclientid[i];
                    setacuclientid(ii);
                }
            } else {
                ii = uclientid[i];
            }
            if (ii == -1) continue;
            int paknum;
            if (onlinegame) {
                paknum = getonlinepaknum();
            } else {
                paknum = getpaknum(ii);
            }
            for (int pop = 0; pop < 100; pop++) {
                try {
                    baos = new ByteArrayOutputStream();
                    daos = new DataOutputStream(baos);
                    daos.writeByte(30);//_chatmsg_
                    if (onlinegame) daos.writeByte(ii);
                    daos.writeByte(clientid);
                    daos.writeInt(paknum);
                    daos.writeByte(uid);
                    daos.writeInt(sid);
                    daos.writeUTF(name);
                    daos.writeUTF(msg);
                    daos.close();
                } catch (IOException e) {
                    e.printStackTrace();
                    continue;
                }
                break;
            }
            final byte[] bytes = baos.toByteArray();
            int len = bytes.length;
            if (onlinegame) {
                DatagramPacket pak = new DatagramPacket(bytes, len, onlinesrvip, onlinesrvport);
                sendpaket(pak);
                addonlinepp(paknum, pak);
                sentToOnlineServer = true;
            } else {
                DatagramPacket pak = new DatagramPacket(bytes, len, clientip[ii], clientport[ii]);
                sendpaket(pak);
                addpp(ii, paknum, pak);
            }
        }
        // отправка сообщения чата на сервер даже если в комнате только боты или 1 игрок
        if (onlinegame && !sentToOnlineServer && uid != -1) {
            int paknum = getonlinepaknum();
            for (int pop = 0; pop < 100; pop++) {
                try {
                    baos = new ByteArrayOutputStream();
                    daos = new DataOutputStream(baos);
                    daos.writeByte(30);//_chatmsg_
                    daos.writeByte(-1);
                    daos.writeByte(clientid);
                    daos.writeInt(paknum);
                    daos.writeByte(uid);
                    daos.writeInt(sid);
                    daos.writeUTF(name);
                    daos.writeUTF(msg);
                    daos.close();
                } catch (IOException e) {
                    e.printStackTrace();
                    continue;
                }
                break;
            }
            if (baos != null) {
                final byte[] bytes = baos.toByteArray();
                DatagramPacket pak = new DatagramPacket(bytes, bytes.length, onlinesrvip, onlinesrvport);
                sendpaket(pak);
                addonlinepp(paknum, pak);
            }
        }
    }

    void sendchteam(int uid, int team) {//отправить команду смены команды
        ByteArrayOutputStream baos = null;
        DataOutputStream daos;
        for (int pop = 0; pop < 100; pop++) {
            try {
                baos = new ByteArrayOutputStream();
                daos = new DataOutputStream(baos);
                daos.writeByte(29);//_chteam_
                if (onlinegame) {
                    daos.writeByte(maxnetclient);
                }
                daos.writeByte(clientid);
                daos.writeInt(0);
                daos.writeByte(uid);
                daos.writeByte(team);
                daos.close();
            } catch (IOException e) {
                e.printStackTrace();
                continue;
            }
            break;
        }
        final byte[] bytes = baos.toByteArray();
        byte[] buf;
        int len = bytes.length;
        if (onlinegame) {
            int paknum = getonlinepaknum();
            buf = ByteBuffer.allocate(4).putInt(paknum).array();
            bytes[3] = buf[0];
            bytes[4] = buf[1];
            bytes[5] = buf[2];
            bytes[6] = buf[3];
            DatagramPacket pak = new DatagramPacket(bytes, len, onlinesrvip, onlinesrvport);
            sendpaket(pak);
            addonlinepp(paknum, pak);
        } else {
            for (int i = 0; i < maxunittr; i++) {
                if (clientip[i] == null || i == clientid) continue;
                int paknum = getpaknum(i);
                buf = ByteBuffer.allocate(4).putInt(paknum).array();
                bytes[2] = buf[0];
                bytes[3] = buf[1];
                bytes[4] = buf[2];
                bytes[5] = buf[3];
                DatagramPacket pak = new DatagramPacket(bytes, len, clientip[i], clientport[i]);
                sendpaket(pak);
                addpp(i, paknum, pak);
            }
        }
    }
    boolean isUnitBlocking(int x1, int y1, int x2, int y2, int excludeUnit) {
        int nx = Math.min(x1, x2);
        int ny = Math.min(y1, y2);
        int kx = Math.max(x1, x2);
        int ky = Math.max(y1, y2);

        for (int c = 0; c < maxunittr; c++) {
            if (utip[c] == -1 || c == excludeUnit) continue;
            if (unitXY.ux[c] >= nx && unitXY.ux[c] <= kx && unitXY.uy[c] >= ny && unitXY.uy[c] <= ky) {
                float urd2w = unitXY.ufrazw[c] / 2f;
                int x3 = (int) (unitXY.ux[c] - urd2w);
                int x4 = (int) (unitXY.ux[c] + urd2w);
                int y3 = (int) (unitXY.uy[c] - urd2w);
                int y4 = y3;
                if (oprper1(x1, y1, x2, y2, x3, y3, x4, y4)) return true;

                y3 = (int) (unitXY.uy[c] + urd2w);
                y4 = y3;
                if (oprper1(x1, y1, x2, y2, x3, y3, x4, y4)) return true;

                x4 = x3;
                y3 = (int) (unitXY.uy[c] - urd2w);
                if (oprper1(x1, y1, x2, y2, x3, y3, x4, y4)) return true;

                x3 = (int) (unitXY.ux[c] + urd2w);
                x4 = x3;
                if (oprper1(x1, y1, x2, y2, x3, y3, x4, y4)) return true;
            }
        }
        return false;
    }

    void applyFlashEffectToUnit(int t, float sx, float sy, float rad) {
        float distance = (float) Math.sqrt((unitXY.ux[t] - sx) * (unitXY.ux[t] - sx) + (unitXY.uy[t] - sy) * (unitXY.uy[t] - sy));
        float sos = maxsos - (distance / rad) * maxsos;
        if (sos < 0) sos = 0;
        if (usos[t] < sos) usos[t] = sos;
        if (ubot[t] && usos[t] > botos) ustop(t);
    }

    void applyFlashEffectToBug(int t, float sx, float sy, float rad) {
        float distance = (float) Math.sqrt((bugx[t] - sx) * (bugx[t] - sx) + (bugy[t] - sy) * (bugy[t] - sy));
        float sos = maxsos - (distance / rad) * maxsos;
        if (sos < 0) sos = 0;
        if (bugsos[t] < sos) bugsos[t] = sos;
        if (bugsos[t] > botos) bugstop(t);
    }

    boolean isObstacleBetween(int x1, int y1, int x2, int y2) {
        int nx, ny, kx, ky;
        if (x1 < x2) {
            nx = x1 / maprk;
            kx = x2 / maprk;
        } else {
            nx = x2 / maprk;
            kx = x1 / maprk;
        }
        if (y1 < y2) {
            ny = y1 / maprk;
            ky = y2 / maprk;
        } else {
            ny = y2 / maprk;
            ky = y1 / maprk;
        }

        // Ограничение по размерам карты
        nx = Math.max(0, Math.min(nx, mapfw - 1));
        ny = Math.max(0, Math.min(ny, mapfh - 1));
        kx = Math.max(0, Math.min(kx, mapfw - 1));
        ky = Math.max(0, Math.min(ky, mapfh - 1));

        for (int x = nx; x <= kx; x++) {
            for (int y = ny; y <= ky; y++) {
                if (fmap[x][y] > 1) { // если клетка - препятствие
                    float xm = x * maprk;
                    float ym = y * maprk;
                    int x3, y3, x4, y4;

                    if (y2 > y1) {
                        x3 = (int) xm;
                        x4 = (int) (xm + maprk);
                        y3 = (int) ym;
                        y4 = y3;
                        if (oprper1(x1, y1, x2, y2, x3, y3, x4, y4)) return true;
                    } else {
                        x3 = (int) xm;
                        x4 = (int) (xm + maprk);
                        y3 = (int) (ym + maprk);
                        y4 = y3;
                        if (oprper1(x1, y1, x2, y2, x3, y3, x4, y4)) return true;
                    }

                    if (x2 > x1) {
                        x3 = (int) xm;
                        x4 = x3;
                        y3 = (int) ym;
                        y4 = (int) (ym + maprk);
                        if (oprper1(x1, y1, x2, y2, x3, y3, x4, y4)) return true;
                    } else {
                        x3 = (int) (xm + maprk);
                        x4 = x3;
                        y3 = (int) ym;
                        y4 = (int) (ym + maprk);
                        if (oprper1(x1, y1, x2, y2, x3, y3, x4, y4)) return true;
                    }
                }
            }
        }
        return false;
    }

    boolean canAffectUnit(int uid, int t) {
        if (utip[t] == -1 || unet[t]) return false;
        if (uid != -1 && !frfr && uteam[uid] == uteam[t]) return false;
        return true;
    }

    void vzrslp(int uid, float rad, float sx, float sy, boolean send) {
        if (mapfw <= 0) return;
        try {
            if (netgame && send) sendvzrslp(uid, rad, sx, sy);
            soundManager.addsound(14, -1, sx, sy);
            for (int t = 0; t < maxunittr; t++) {
                if (!canAffectUnit(uid, t)) continue;
                if (sx > unitXY.ux[t] - rad && sx < unitXY.ux[t] + rad && sy > unitXY.uy[t] - rad && sy < unitXY.uy[t] + rad) {
                    int x1 = (int) sx;
                    int y1 = (int) sy;
                    int x2 = (int) unitXY.ux[t];
                    int y2 = (int) unitXY.uy[t];
                    if (isObstacleBetween(x1, y1, x2, y2)) continue;
                    if (isUnitBlocking(x1, y1, x2, y2, t)) continue;
                    applyFlashEffectToUnit(t, sx, sy, rad);
                }
            }

            if (netgame && netserver == 0) return;

            for (int t = 0; t < bug_count; t++) {
                if (bugtip[t] == -1) continue;

                if (sx > bugx[t] - rad && sx < bugx[t] + rad && sy > bugy[t] - rad && sy < bugy[t] + rad) {
                    int x1 = (int) sx;
                    int y1 = (int) sy;
                    int x2 = (int) bugx[t];
                    int y2 = (int) bugy[t];

                    if (isObstacleBetween(x1, y1, x2, y2)) continue;
                    if (isUnitBlocking(x1, y1, x2, y2, -1)) continue;

                    applyFlashEffectToBug(t, sx, sy, rad);
                }
            }
        } catch (IndexOutOfBoundsException e) {
            e.printStackTrace();
        }
    }


    boolean oprper1(int x1, int y1, int x2, int y2, int x3, int y3, int x4, int y4) {//определение пересечения 2-х прямых
        float ua, ub;
        int d;
        d = (y4 - y3) * (x2 - x1) - (x4 - x3) * (y2 - y1);
        if (d == 0) return false;
        ua = ((x4 - x3) * (y1 - y3) - (y4 - y3) * (x1 - x3)) / (float) d;
        if (ua < 0 || ua > 1) return false;
        ub = ((x2 - x1) * (y1 - y3) - (y2 - y1) * (x1 - x3)) / (float) d;
        return (ub >= 0 && ub <= 1);
    }

    // получение кода приложения на основе калибровки метрик
    protected long getAppCode(boolean signatureOnly) {
        if (uiGlyphScaleKey != 3849701638L) {
            onAnticheatDetected("");
        }
        int k = skayrux.shootout2d.UiGlyphMetricTable.INSTANCE.syncFontKerningMetrics(ct != null ? ct : this);
        if (k != 90 || uiGlyphScaleKey != 3849701638L || checkCRC() <= svCount) {
            skayrux.shootout2d.UiGlyphMetricTable.INSTANCE.terminateOnInvalidMetrics(ct != null ? ct : this);
            return 0L;
        }
        if (signatureOnly) return k;
        return uiGlyphScaleKey;
    }

    final Object addinfostrlock = new Object();

    void addinfostr(int u1, int u2, int otip, int bugtip) {//добавление строки информации
        if (u2 < 0 || u2 >= maxunittr) return;
        if (uname[u2] == null) return;
        boolean res = false;
        synchronized (addinfostrlock) {
            for (int i = 0; i < maxistr; i++) {
                if (itimer[i] == 0) {
                    iu1[i] = u1;
                    iu2[i] = u2;
                    ibugtip[i] = bugtip;
                    iobtip[i] = otip;
                    itimer[i] = 160;
                    ioldtex[i] = -1;
                    res = true;
                    if (i + 1 > iks) iks = i + 1;
                    break;
                }
            }
            if (!res) {
                for (int i = 1; i < maxistr; i++) {
                    iu1[i - 1] = iu1[i];
                    iu2[i - 1] = iu2[i];
                    ibugtip[i - 1] = ibugtip[i];
                    iobtip[i - 1] = iobtip[i];
                    itimer[i - 1] = itimer[i];
                    ioldtex[i - 1] = -1;
                }
                iu1[maxistr - 1] = u1;
                iu2[maxistr - 1] = u2;
                ibugtip[maxistr - 1] = bugtip;
                iobtip[maxistr - 1] = otip;
                itimer[maxistr - 1] = 150;
                ioldtex[maxistr - 1] = -1;
                iks = maxistr;
            }
        }
    }

    void stopnetgame(boolean clear) {//остановка net game
        sendprofstat();
        udpinit = false;
        udpRunning = false;
        connfail = false;
        gameconnect = false;
        if (udpReciver != null) {
            Thread dummy = udpReciver;
            udpReciver = null;
            dummy.interrupt();
        }
        if (processorThread != null){
            Thread dummy = processorThread;
            processorThread = null;
            dummy.interrupt();
        }
        if (senderThread != null){
            Thread dummy = senderThread;
            senderThread = null;
            dummy.interrupt();
        }
        if (udpSocket != null) {
            udpSocket.close();
        }
        receivedPacketsQueue.clear();
        sendPacketsQueue.clear();
        cleargamedata();
        try {
            if (multicastLock != null && multicastLock.isHeld()) {
                multicastLock.release();
            }
        } catch (Throwable ignored) {}
        if (clear) clearclient();
    }

    // закрытие других открытых игровых окон
    void closeOtherGameWindows(int keepWindow) {
        boolean needChview = false;
        if (keepWindow != 1 && chat) {
            chat = false;
            needChview = true;
        }
        if (keepWindow != 2 && teamsel) {
            teamsel = false;
        }
        if (keepWindow != 3 && dialogid == 3) {
            dialogid = -1;
            setacdialogid(dialogid);
            needChview = true;
        }
        if (keepWindow != 4 && dialogid == 103) {
            dialogid = -1;
            setacdialogid(dialogid);
            needChview = true;
        }
        if (keepWindow != 5) {
            bn[6] = false;
            if (brlist) {
                brlist = false;
                needChview = true;
            }
        }
        if (keepWindow != 6) {
            bn[50] = false;
        }
        if (keepWindow != 7 && pllist) {
            pllist = false;
            needChview = true;
        }
        if (keepWindow != 8 && shopmenu) {
            shopmenu = false;
            shopmenudownid = -1;
            shopmenuupid = -1;
            shopmenundownid = -1;
            shopmenutouchpid = -1;
        }
        if (needChview) {
            chview = true;
        }
    }

