    void sendsrvconnect(InetAddress ip, int port){//запрос на подключение к серверу
        try {
            initUserSrvId();
            final int num=-1;
            ByteArrayOutputStream baos=new ByteArrayOutputStream();
            DataOutputStream daos=new DataOutputStream(baos);
            daos.writeByte(36);//_connect_
            if (onlinegame) daos.writeByte(0);
            daos.writeByte(-1);
            daos.writeInt(num);
            // генерация уникального id сессии при каждом новом подключении
            gamerid = rand.nextInt(899999999) + 100000;
            daos.writeInt(gamerid);
           // daos.writeUTF(dvid);
            daos.writeByte(gameversion);
            daos.writeInt(usersrvid);
            daos.writeInt(userscore);
            daos.writeByte(userstatus);
            daos.writeUTF(plname);
            if (serverpassword == null || serverpassword.trim().isEmpty() || serverpassword.equals("_null_")) {
                daos.writeUTF("_null_");
            } else {
                daos.writeUTF(serverpassword.trim());
            }
            daos.writeInt(svCount);
            String connToken = onlinegame ? getActiveSessionToken() : "";
            if (!connToken.isEmpty()) usertmpid = connToken;
            String sendTmp = onlinegame ? (usertmpid != null ? usertmpid : "") : sanitizePlayerStrId(usersrvstrid, usersrvid);
            daos.writeUTF(sendTmp);
            daos.writeBoolean(profonline);
            // передача пакета, названия и версии кода приложения
            daos.writeUTF(ct != null ? ct.getPackageName() : "skayrux.shootout2d.com");
            daos.writeUTF(ct != null ? ct.getString(R.string.app_name) : "2D Shootout");
            daos.writeInt(BuildConfig.VERSION_CODE);
            daos.close();
            final byte[] bytes=baos.toByteArray();
            if (onlinegame) {
                DatagramPacket pak=new DatagramPacket(bytes, bytes.length, ip, port);
                sendpaket(pak);
                addonlinepp(num, pak);
            }else{
                DatagramPacket pak=new DatagramPacket(bytes, bytes.length, ip, port);
                sendpaket(pak);
                addpp(0, num, pak);
            }
        }catch (IOException io){
            io.printStackTrace();
        }
    }

    void sendfindsrv(){//отправить запрос на поиск сервера
        autorefrtimer=90;
        try{
            synchronized (srvlistblock) {
                clearserverlist();
            }
            ByteArrayOutputStream baos=new ByteArrayOutputStream();
            DataOutputStream daos=new DataOutputStream(baos);
            if (onlinegame){
                daos.writeByte(-7);//_serverlist_
                daos.writeByte(onlinesrvversion);
                daos.close();
                final byte[] bytes=baos.toByteArray();
                for (int i=0; i<onlinesrvips.size(); i++) {
                    DatagramPacket pak=new DatagramPacket(bytes, bytes.length, onlinesrvips.get(i), ipport);
                    sendpaket(pak);
                }
            }else{
                daos.writeByte(7);//_server?_
                daos.close();
                final byte[] bytes=baos.toByteArray();
                DatagramPacket pak=new DatagramPacket(bytes, bytes.length, bcip, ipport);
                sendpaket(pak);
            }
            srvliststime=System.currentTimeMillis();
        }catch(Exception e){
            e.printStackTrace();
            try{
                bcip=getBroadcastAddress();
            }catch (IOException ex){
            }
        }
    }

    void sendcreateonlinegame(int onlinever, InetAddress srvip){//отправить запрос на sozdanie online igri
        try{
            initUserSrvId();
            if (gamerid <= 123456 || gamerid == 0 || gamerid == 1 || gamerid == -1 || gamerid == usersrvid) {
                gamerid = rand.nextInt(899999999) + 100000;
            }
            if (clientip[0] != null) {
                clientrandomid[0] = gamerid;
            }
            onlinesendpaknum=0;
            onlinesrvport=ipport;
            ByteArrayOutputStream baos=new ByteArrayOutputStream();
            DataOutputStream daos=new DataOutputStream(baos);
            daos.writeByte(-35);//_createonline_
            daos.writeByte(gameversion);
            daos.writeByte(onlinever);
            daos.writeByte(appcodeversion);
            daos.writeInt(gamerid);
            //daos.writeUTF(dvid); // 2dac 3
            daos.writeByte(nmap);
            datagame_selectedmap sm=selectedmap;
            boolean custommap=(sm!=null && sm.custommap);
            daos.writeBoolean(custommap);
            if (custommap){
                daos.writeUTF(sm.mapname);
                daos.writeUTF(sm.mapuid);
            }
            daos.writeByte(gtype);
            if (gtype==5 || gtype==2 || gtype==7 || gtype==8 || gtype==11 || gtype==12){
                plcount=rbc;
            }else{
                plcount=bbc+rbc;
            }
            daos.writeByte(Math.min(127, plcount));
            daos.writeUTF(verstr);
            daos.writeUTF(plname);
			if (serverpassword == null || serverpassword.trim().isEmpty() || serverpassword.equals("_null_")) {
				daos.writeUTF("_null_");
			} else {
				daos.writeUTF(serverpassword.trim());
			}
			daos.writeByte(userstatus);
            daos.writeInt(usersrvid);
            String createToken = getActiveSessionToken();
            if (!createToken.isEmpty()) usertmpid = createToken;
            daos.writeUTF(usertmpid != null ? usertmpid : "");
            daos.writeBoolean(profonline);
            daos.writeUTF(encryptStr(String.valueOf(getAppCode(false)),false));
            daos.writeByte(bbr);
            daos.writeByte(rbr);
            // передача пакета, названия и версии кода приложения
            daos.writeUTF(ct != null ? ct.getPackageName() : "skayrux.shootout2d.com");
            daos.writeUTF(ct != null ? ct.getString(R.string.app_name) : "2D Shootout");
            daos.writeInt(BuildConfig.VERSION_CODE);
            daos.writeShort(plcount);
            daos.close();
            final byte[] bytes=baos.toByteArray();
            if (srvip==null) {
                for (int i=0; i<onlinesrvips.size(); i++) {
                    if (onlinesrvips.get(i)==null) continue;
                    DatagramPacket pak=new DatagramPacket(bytes, bytes.length, onlinesrvips.get(i), ipport);
                    sendpaket(pak);
                }
            }else{
                DatagramPacket pak=new DatagramPacket(bytes, bytes.length, srvip, ipport);
                sendpaket(pak);
            }
        }catch(IOException io){
            io.printStackTrace();
            try{
                bcip=getBroadcastAddress();
            }catch (IOException e){
            }
        }
    }

    int getclientindex(InetAddress ip){//возвращает индекс клиента
        if (ip==null) return -1;
        for (int i = 0; i < maxunittr; i++) {
            if (clientip[i]==null) continue;
            if (ip.equals(clientip[i])) return i;
        }
        return -1;
    }

    void sendaddcl(InetAddress destip, int destport, int destcid, InetAddress addip, int addport, int addcid, int addrid , int addsrvid, int addscore, int addstatus, String addname, boolean addrdy){//команда на добавление клиента (one to one)
        if (destcid==-1 || addcid==-1 || destip==null || destport==0 || addport==0) return;
        int paknum;
        if (onlinegame){
            paknum=getonlinepaknum();
        }else{
            paknum=getpaknum(destcid);
        }
        ByteArrayOutputStream baos=null;
        DataOutputStream daos;
        for (int pop=0; pop<100; pop++){
            try{
                baos=new ByteArrayOutputStream();
                daos=new DataOutputStream(baos);
                daos.writeByte(20);//_addclnt_
                if (onlinegame) daos.writeByte(destcid);
                daos.writeByte(clientid);
                daos.writeInt(paknum);
                daos.writeByte((byte)addcid);
                daos.writeInt(addrid);
               // daos.writeUTF(adddvid);
                daos.writeInt(addport);
                daos.writeInt(addsrvid);
                daos.writeInt(addscore);
                daos.writeByte((byte)addstatus);
                daos.writeBoolean(addrdy);
                if (addip==null){
                    daos.writeUTF("NULL");
                }else{
                    daos.writeUTF(addip.toString());
                }
                daos.writeUTF(addname);
                String addStrId = (addcid >= 0 && addcid < maxunit)
                        ? sanitizePlayerStrId(clientsrvstrid[addcid], addsrvid)
                        : sanitizePlayerStrId(null, addsrvid);
                daos.writeUTF(addStrId);
                daos.close();
            } catch (IOException e) {
                e.printStackTrace();
                continue;
            }
            break;
        }
        final byte[] bytes=baos.toByteArray();
        if (onlinegame){
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, onlinesrvip, onlinesrvport);
            sendpaket(pak);
            addonlinepp(paknum, pak);
        }else{
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, destip, destport);
            sendpaket(pak);
            addpp(destcid, paknum, pak);
        }
    }

    void sendaddcl(InetAddress destip, int destport, int destcid){//команда на добавление клиента (all to one)
        if (destcid==-1 || destip==null || destport==0) return;
        int paknum;
        if (onlinegame){
            paknum=getonlinepaknum();
        }else{
            paknum=getpaknum(destcid);
        }
        ByteArrayOutputStream baos=null;
        DataOutputStream daos;
        for (int pop=0; pop<100; pop++){
            try{
                baos=new ByteArrayOutputStream();
                daos=new DataOutputStream(baos);
                daos.writeByte(20);//_addclnt_
                if (onlinegame) daos.writeByte(destcid);
                daos.writeByte(clientid);
                daos.writeInt(paknum);
                for (int i=0; i<maxunittr; i++){
                    if (clientip[i]==null || destcid==i) continue;
                    daos.writeByte((byte) i);
                    daos.writeInt(clientrandomid[i]);
                   // daos.writeUTF(clientdvid[i]);
                    daos.writeInt(clientport[i]);
                    daos.writeInt(clientsrvid[i]);
                    daos.writeInt(clientscore[i]);
                    daos.writeByte((byte) clientstatus[i]);
                    daos.writeBoolean(clientrdy[i]);
                    daos.writeUTF(clientip[i].toString());
                    daos.writeUTF(clientname[i]);
                    String iStrId = (i >= 0 && i < maxunit)
                            ? sanitizePlayerStrId(clientsrvstrid[i], clientsrvid[i])
                            : sanitizePlayerStrId(null, clientsrvid[i]);
                    daos.writeUTF(iStrId);
                    if (daos.size()>plength-100 && i<maxunittr-1){ // plength - 200 , test lag
                        boolean send=false;
                        for (int t=i+1; t<maxunittr; t++){
                            if (clientip[t]!=null && destcid!=t){
                                send=true;
                                break;
                            }
                        }
                        if (send){
                            daos.close();
                            sendaddclSend(destip, destport, destcid, paknum, baos);
                            baos=new ByteArrayOutputStream();
                            daos=new DataOutputStream(baos);
                            daos.writeByte(20);
                            if (onlinegame) daos.writeByte(destcid);
                            daos.writeByte(clientid);
                            if (onlinegame){
                                paknum=getonlinepaknum();
                            }else{
                                paknum=getpaknum(destcid);
                            }
                            daos.writeInt(paknum);
                        }
                    }
                }
                daos.close();
            } catch (IOException e) {
                e.printStackTrace();
                continue;
            }
            break;
        }
        sendaddclSend(destip, destport, destcid, paknum, baos);
    }

    void sendaddclSend(InetAddress destip, int destport, int destcid, int paknum, ByteArrayOutputStream baos){
        final byte[] bytes=baos.toByteArray();
        if (onlinegame){
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, onlinesrvip, onlinesrvport);
            sendpaket(pak);
            addonlinepp(paknum, pak);
        }else{
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, destip, destport);
            sendpaket(pak);
            addpp(destcid, paknum, pak);
        }
    }

