    void sendmapheadudp(int cli, datagame_custommaphead head){//send custom map head
        if (cli<=0 || cli>=maxunit || head==null) return;
        int paknum=(onlinegame) ? getonlinepaknum() : getpaknum(cli);
        ByteArrayOutputStream baos=null;
        DataOutputStream daos;
        for (int pop=0; pop<100; pop++) {
            try {
                baos=new ByteArrayOutputStream();
                daos=new DataOutputStream(baos);
                daos.writeByte(27);//_mapheadudp_
                if (onlinegame) daos.writeByte(cli);
                daos.writeByte(clientid);
                daos.writeInt(paknum);
                daos.writeByte(head.gver);
                daos.writeUTF(head.mapname);
                daos.writeUTF(head.mapuid);
                daos.writeInt(head.usersrvid);
                daos.writeInt(head.userrid);
                daos.writeShort(head.mapw);
                daos.writeShort(head.maph);
                daos.writeUTF(head.timestamp);
                daos.writeInt(head.maxmapk);
                daos.writeShort(head.mapminx);
                daos.writeShort(head.mapminy);
                daos.writeShort(head.mapmaxx);
                daos.writeShort(head.mapmaxy);
                daos.close();
            } catch (IOException e) {
                e.printStackTrace();
                continue;
            }
            break;
        }
        final byte[] bytes=baos.toByteArray();
        if (onlinegame){
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, onlinesrvip, onlinesrvport);
            sendpaket(pak);
            addonlinepp(paknum, pak);
        }else{
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, clientip[cli], clientport[cli]);
            sendpaket(pak);
            addpp(cli, paknum, pak);
        }
    }

