    void sendunitpos() {//отсылает позицию юнита
        if (pause || provmod1 || unitXY == null) return;
        ByteArrayOutputStream baos=new ByteArrayOutputStream();
        DataOutputStream daos=new DataOutputStream(baos);
        int ugol;
        try {
            daos.writeByte(15);//_unitpos_
            if (onlinegame) {
                daos.writeByte(maxnetclient);
            }
            daos.writeByte(clientid);
            if (netserver==1) {
                for (int t=0; t<maxunittr; t++) {
                    int carobid = ucarobid[t];
                    if (utip[t]==-1 || unet[t] || utip[t]==5) continue;
                    if (unitXY.ux[t] <= 1f && unitXY.uy[t] <= 1f) continue;
                    if (daos.size() > plength - 20) break;
                    daos.writeByte(t);
                    daos.writeShort((short) unitXY.ux[t]);
                    daos.writeShort((short) unitXY.uy[t]);
                    daos.writeShort((short) uugol[t]);
                }
                if (bug_count>0) {
                    boolean add=true;
                    for (int t=0; t<bug_count; t++) {
                        if (bugtip[t]==-1) continue;
                        if (daos.size() > plength - 20) break;
                        if (add){
                            daos.writeByte(-100);
                            add=false;
                        }
                        daos.writeByte(t-maxbug/2);
                        daos.writeShort((short)bugx[t]);
                        daos.writeShort((short)bugy[t]);
                        ugol=(bugugol[t]-180)/2;
                        daos.writeByte(ugol);
                    }
                }
            }else{
                int pid=plid;
                if (pid!=-1) {
                    int carobid = ucarobid[pid];
                    if (utip[pid]!=-1 && (unitXY.ux[pid] > 1f || unitXY.uy[pid] > 1f)) {
                        daos.writeByte(pid);
                        daos.writeShort((short) unitXY.ux[pid]);
                        daos.writeShort((short) unitXY.uy[pid]);
                        daos.writeShort((short) uugol[pid]);
                    }
                }
            }
            daos.close();
        }catch (IOException e) {
            e.printStackTrace();
        }
        if (baos.toByteArray().length<=0) return;
        final byte[] bytes=baos.toByteArray();
        if (onlinegame){
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, onlinesrvip, onlinesrvport);
            sendpaket(pak);
        }else{
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, clientip[0], clientport[0]);
            for (int i=0; i<maxunittr; i++) {
                InetAddress ip=clientip[i];
                int port=clientport[i];
                if (ip==null || port==0 || i==clientid || !clientrdy[i]) continue;
                pak.setAddress(ip);
                pak.setPort(port);
                sendpaket(pak);
            }
        }
        obrukugol();
        sendudrawms();
    }

