    void obrukugol() {//отсылает ukugol
        if (netserver==1) {
            for (int t=0; t<maxunittr; t++) {
                if (utip[t]==-1 || unet[t] || ukugol[t]==uoldkugol[t] || utip[t]==5) continue;
                uoldkugol[t]=ukugol[t];
                sendukugol(t);
            }
        }else{
            int pid=plid;
            if (pid!=-1) {
                if (utip[pid]!=-1 && uoldkugol[pid]!=ukugol[pid]) {
                    uoldkugol[pid]=ukugol[pid];
                    sendukugol(pid);
                }
            }
        }
    }
    void obrsendSkin() {//отсылает uskin
        if (netserver==1) {
            for (int t=0; t<maxunittr; t++) {
                if (utip[t]==-1 || unet[t] || utip[t]==5) continue;
                if (uskin[t] == uoldskin[t]) continue;
                uoldskin[t] = uskin[t];
                senduskin(t);
            }
        }else{
            int pid=plid;
            if (pid!=-1) {
                if (utip[pid]!=-1 && uskin[pid] != uoldskin[pid]) {
                    uoldskin[pid] = uskin[pid];
                    senduskin(pid);
                }
            }
        }
    }

