    void sendconcom(InetAddress ip, int port, int cli, int rid){//отправка команды подключения к игре
        plcount=getunitcount();
        int paknum;
        if (onlinegame){
            paknum=getonlinepaknum();
        }else{
            paknum=getpaknum(cli);
        }
        ByteArrayOutputStream baos=null;
        DataOutputStream daos;
        for (int pop=0; pop<100; pop++){
            try{
                baos=new ByteArrayOutputStream();
                daos=new DataOutputStream(baos);
                daos.writeByte(9);//_conncomm_
                if (onlinegame) daos.writeByte(cli);
                daos.writeByte(clientid);
                daos.writeInt(paknum);
                daos.writeByte(cli);
                daos.writeInt(rid);//for strikeserver
                //daos.writeUTF(devid);
                daos.writeByte(nmap);
                datagame_selectedmap sm=selectedmap;
                boolean custommap=(sm!=null && sm.custommap);
                daos.writeBoolean(custommap);
                if (custommap){
                    daos.writeUTF(sm.mapname);
                    daos.writeUTF(sm.mapuid);
                    daos.writeUTF(sm.timestamp);
                }
                daos.writeByte(gtype);
                daos.writeByte(plcount);
                daos.writeByte(bbr);
                daos.writeByte(rbr);
                daos.writeShort(bbc);
                daos.writeShort(rbc);
                daos.writeByte(brminpl);
                daos.writeBoolean(frfr);
                daos.writeBoolean(weapononmap);
                daos.writeBoolean(autobalance);
                daos.writeShort(startmoney);
                daos.writeShort(egperiod/30);
                for (int i=0; i<maxuslot; i++) {
                    daos.writeByte(scr8slotid[i]);
                }
                for (int i=0; i<maxshopmenuob; i++) {
                    daos.writeBoolean(tobdost[shopmenuobtip[i]]);
                }
                daos.writeBoolean(spectateEnemy);
                daos.close();
            } catch (IOException e) {
                e.printStackTrace();
                continue;
            }
            break;
        }
        final byte[] bytes=baos.toByteArray();
        if (onlinegame){
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, onlinesrvip, onlinesrvport);
            sendpaket(pak);
            addonlinepp(paknum, pak);
        }else{
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, ip, port);
            sendpaket(pak);
            addpp(cli, paknum, pak);
        }
    }

