    void sendpause(boolean p, int destclid){//отправка паузы
        if (onlinegame){
            int paknum=getonlinepaknum();
            ByteArrayOutputStream baos=null;
            DataOutputStream daos;
            for (int pop=0; pop<100; pop++) {
                try {
                    baos=new ByteArrayOutputStream();
                    daos=new DataOutputStream(baos);
                    daos.writeByte(10);//_pause_
                    daos.writeByte(destclid == maxunit ? maxnetclient : destclid);
                    daos.writeByte(clientid);
                    daos.writeInt(paknum);
                    daos.writeBoolean(p);
                    daos.close();
                } catch (IOException e) {
                    e.printStackTrace();
                    continue;
                }
                break;
            }
            final byte[] bytes=baos.toByteArray();
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, onlinesrvip, onlinesrvport);
            sendpaket(pak);
            addonlinepp(paknum, pak);
        }else{
            for (int i=0; i<maxunittr; i++) {
                if (clientip[i]==null || i==clientid || (i!=destclid && destclid!=maxunit)) continue;
                int paknum=getpaknum(i);
                ByteArrayOutputStream baos=null;
                DataOutputStream daos;
                for (int pop=0; pop<100; pop++) {
                    try {
                        baos=new ByteArrayOutputStream();
                        daos=new DataOutputStream(baos);
                        daos.writeByte(10);//_pause_
                        daos.writeByte(clientid);
                        daos.writeInt(paknum);
                        daos.writeBoolean(p);
                        daos.close();
                    } catch (IOException e) {
                        e.printStackTrace();
                        continue;
                    }
                    break;
                }
                final byte[] bytes=baos.toByteArray();
                DatagramPacket pak=new DatagramPacket(bytes, bytes.length, clientip[i], clientport[i]);
                sendpaket(pak);
                addpp(i, paknum, pak);
            }
        }
    }

    void sendready(){//клиент готов к получению игровых данных
        if (onlinegame){
            int paknum=getonlinepaknum();
            ByteArrayOutputStream baos=null;
            DataOutputStream daos;
            for (int pop=0; pop<100; pop++) {
                try {
                    baos=new ByteArrayOutputStream();
                    daos=new DataOutputStream(baos);
                    daos.writeByte(5);//_ready_
                    daos.writeByte(maxnetclient);
                    daos.writeByte(clientid);
                    daos.writeInt(paknum);
                    daos.close();
                } catch (IOException e) {
                    e.printStackTrace();
                    continue;
                }
                break;
            }
            final byte[] bytes=baos.toByteArray();
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, onlinesrvip, onlinesrvport);
            sendpaket(pak);
            addonlinepp(paknum, pak);
        }else{
            for (int i=0; i<maxunittr; i++) {
                if (clientip[i]==null || i==clientid) continue;
                int paknum=getpaknum(i);
                ByteArrayOutputStream baos=null;
                DataOutputStream daos;
                for (int pop=0; pop<100; pop++) {
                    try {
                        baos=new ByteArrayOutputStream();
                        daos=new DataOutputStream(baos);
                        daos.writeByte(5);//_ready_
                        daos.writeByte(clientid);
                        daos.writeInt(paknum);
                        daos.close();
                    } catch (IOException e) {
                        e.printStackTrace();
                        continue;
                    }
                    break;
                }
                final byte[] bytes=baos.toByteArray();
                DatagramPacket pak=new DatagramPacket(bytes, bytes.length, clientip[i], clientport[i]);
                sendpaket(pak);
                addpp(i, paknum, pak);
            }
        }
    }

    void sendclientunitid(int uid, int x, int y, int destcid, boolean startunit){//отправка свободного индекса юнита клиенту
        if (destcid<0 || destcid>=maxunittr) return;
        int paknum;
        ByteArrayOutputStream baos=null;
        DataOutputStream daos;
        if (onlinegame){
            paknum=getonlinepaknum();
            for (int pop=0; pop<100; pop++){
                try{
                    baos=new ByteArrayOutputStream();
                    daos=new DataOutputStream(baos);
                    daos.writeByte(14);//_clientui_
                    daos.writeByte(maxnetclient);
                    daos.writeByte(clientid);
                    daos.writeInt(paknum);
                    daos.writeByte((byte)uid);
                    daos.writeByte((byte) destcid);
                    daos.writeShort(x);
                    daos.writeShort(y);
                    daos.writeBoolean(startunit);
                    daos.close();
                }catch(IOException e){
                    e.printStackTrace();
                    continue;
                }
                break;
            }
            final byte[] bytes=baos.toByteArray();
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, onlinesrvip, onlinesrvport);
            sendpaket(pak);
            addonlinepp(paknum, pak);
        }else{
            for (int i=0; i<maxunittr; i++){
                if (clientip[i]==null || i==clientid) continue;
                paknum=getpaknum(i);
                for (int pop=0; pop<100; pop++){
                    try{
                        baos=new ByteArrayOutputStream();
                        daos=new DataOutputStream(baos);
                        daos.writeByte(14);//_clientui_
                        daos.writeByte(clientid);
                        daos.writeInt(paknum);
                        daos.writeByte((byte) uid);
                        daos.writeByte((byte) destcid);
                        daos.writeShort(x);
                        daos.writeShort(y);
                        daos.writeBoolean(startunit);
                        daos.close();
                    }catch (IOException e){
                        e.printStackTrace();
                        continue;
                    }
                    break;
                }
                final byte[] bytes=baos.toByteArray();
                DatagramPacket pak=new DatagramPacket(bytes, bytes.length, clientip[i], clientport[i]);
                sendpaket(pak);
                addpp(i, paknum, pak);
            }
        }
    }

    void sendaddobsrv(int tip, float x, float y, int sn1, int sn2, int life, boolean prov, int uid){//команда добавить объект на сервер
        int paknum;
        if (onlinegame){
            paknum=getonlinepaknum();
        }else{
            paknum=getpaknum(0);
        }
        ByteArrayOutputStream baos=null;
        DataOutputStream daos;
        for (int pop=0; pop<100; pop++){
            try{
                baos=new ByteArrayOutputStream();
                daos=new DataOutputStream(baos);
                daos.writeByte(4);//_addob_
                if (onlinegame) daos.writeByte(0);
                daos.writeByte(clientid);
                daos.writeInt(paknum);
                daos.writeByte(tip);
                daos.writeShort((short)x);
                daos.writeShort((short)y);
                daos.writeShort(sn1);
                daos.writeShort(sn2);
                daos.writeShort(life);
                daos.writeBoolean(prov);
                daos.writeByte(uid);
                daos.close();
            }catch(IOException e){
                e.printStackTrace();
                continue;
            }
            break;
        }
        final byte[] bytes=baos.toByteArray();
        if (onlinegame){
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, onlinesrvip, onlinesrvport);
            sendpaket(pak);
            addonlinepp(paknum, pak);
        }else{
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, clientip[0], clientport[0]);
            sendpaket(pak);
            addpp(0, paknum, pak);
        }
    }

    int getgamedataind(int pakid, int destcl){//get gamedata global & paket index
        int ind, gind;
        gind=sdglobali;
        ind=sdpakind[pakid];
        sdpakind[pakid]++;
        sdglobali++;
        if (ind>=sdpakmaxind[pakid] || gind>=sdglobalmax) {
            sdpakind[pakid]--;
            sdglobali--;
            sendgamedata();
            gind=sdglobali;
            ind=sdpakind[pakid];
            sdpakind[pakid]++;
            sdglobali++;
        }
        sdglobalid[gind]=ind;
        sdglobalupr[gind]=(byte)pakid;
        sdglobalclid[gind]=destcl;
        return ind;
    }

