    void sendteamscore(){//послать инфо об очках komand
        ByteArrayOutputStream baos=null;
        DataOutputStream daos;
        int paknum=0;
        if (onlinegame) paknum=getonlinepaknum();
        for (int pop=0; pop<100; pop++){
            try{
                baos=new ByteArrayOutputStream();
                daos=new DataOutputStream(baos);
                daos.writeByte(13);//_teamscr_
                if (onlinegame) daos.writeByte(maxnetclient);
                daos.writeByte(clientid);
                daos.writeInt(paknum);
                daos.writeShort(t0score);
                daos.writeShort(t1score);
                daos.close();
            }catch(IOException e){
                e.printStackTrace();
                continue;
            }
            break;
        }
        final byte[] bytes=baos.toByteArray();
        int len=bytes.length;
        if (onlinegame){
            DatagramPacket pak=new DatagramPacket(bytes, len, onlinesrvip, onlinesrvport);
            sendpaket(pak);
            addonlinepp(paknum, pak);
        }else{
            byte[] buf;
            for (int i=0; i<maxunittr; i++) {
                if (i==clientid || clientip[i]==null) continue;
                paknum=getpaknum(i);
                buf=ByteBuffer.allocate(4).putInt(paknum).array();
                bytes[2]=buf[0];
                bytes[3]=buf[1];
                bytes[4]=buf[2];
                bytes[5]=buf[3];
                DatagramPacket pak=new DatagramPacket(bytes, len, clientip[i], clientport[i]);
                sendpaket(pak);
                addpp(i, paknum, pak);
            }
        }
    }

