    void sendaddbugip(InetAddress ip, int port, int cid){//команда добавить bug
        int nz=0;
        int pr;
        int paknum;
        if (onlinegame){
            paknum=getonlinepaknum();
        }else{
            paknum=getpaknum(cid);
        }
        ByteArrayOutputStream baos=null;
        DataOutputStream daos;
        for (int pop=0; pop<100; pop++){
            try{
                baos=new ByteArrayOutputStream();
                daos=new DataOutputStream(baos);
                daos.writeByte(32);//_addbug_
                if (onlinegame) {
                    daos.writeByte(cid);
                    pr=7;
                }else{
                    pr=6;
                }
                daos.writeByte(clientid);
                daos.writeInt(paknum);
                for (int ii=nz; ii<maxbug; ii++) {
                    if (bugtip[ii]==-1 || buglife[ii]<=0) continue;
                    daos.writeShort(ii);
                    daos.writeByte(bugtip[ii]);
                    daos.writeShort(Math.round(bugx[ii]));
                    daos.writeShort(Math.round(bugy[ii]));
                    daos.writeShort(buglife[ii]);
                    daos.writeByte(buguid[ii]);
                    pr=pr+10;
                    if (pr>plength-17 && ii+1<maxbug){
                        daos.close();
                        final byte[] bytes=baos.toByteArray();
                        if (onlinegame){
                            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, onlinesrvip, onlinesrvport);
                            sendpaket(pak);
                            addonlinepp(paknum, pak);
                            paknum=getonlinepaknum();
                        }else{
                            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, ip, port);
                            sendpaket(pak);
                            addpp(cid, paknum, pak);
                            paknum=getpaknum(cid);
                        }
                        nz=ii+1;
                        baos=new ByteArrayOutputStream();
                        daos=new DataOutputStream(baos);
                        daos.writeByte(32);
                        if (onlinegame) {
                            daos.writeByte(cid);
                            pr=7;
                        }else{
                            pr=6;
                        }
                        daos.writeByte(clientid);
                        daos.writeInt(paknum);
                    }
                }
                daos.close();
            }catch(IOException e){
                e.printStackTrace();
                continue;
            }
            break;
        }
        final byte[] bytes=baos.toByteArray();
        if (onlinegame){
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, onlinesrvip, onlinesrvport);
            sendpaket(pak);
            addonlinepp(paknum, pak);
        }else{
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, ip, port);
            sendpaket(pak);
            addpp(cid, paknum, pak);
        }
    }

    void sendaddunit(int uid, int tip, float x, float y, int team, boolean bot, int ob1tip, int ob2tip, int ob3tip, String name, int cid, int kills, int death, int life, int armor, int slot, int dengi, boolean startunit){//команда добавить юнит для всех клиентов
        ByteArrayOutputStream baos=null;
        DataOutputStream daos;
        for (int pop=0; pop<100; pop++){
            try{
                baos=new ByteArrayOutputStream();
                daos=new DataOutputStream(baos);
                daos.writeByte(21);//_addunit_
                if (onlinegame) daos.writeByte(maxnetclient);
                daos.writeByte(clientid);
                daos.writeInt(0);
                daos.writeByte(uid);
                daos.writeByte(cid);
                daos.writeByte(tip);
                daos.writeShort(Math.round(x));
                daos.writeShort(Math.round(y));
                daos.writeByte(team);
                daos.writeBoolean(bot);
                daos.writeBoolean(startunit);
                daos.writeByte(ob1tip);
                daos.writeByte(ob2tip);
                daos.writeByte(ob3tip);
                daos.writeShort(kills);
                daos.writeShort(death);
                daos.writeShort(life);
                daos.writeShort(armor);
                daos.writeByte(slot);
                daos.writeShort(Math.max(-32768, Math.min(32767, dengi)));
                daos.writeUTF(name);
                daos.close();
            }catch(IOException e){
                e.printStackTrace();
                continue;
            }
            break;
        }
        final byte[] bytes=baos.toByteArray();
        byte[] buf;
        int len=bytes.length;
        if (onlinegame){
            int paknum=getonlinepaknum();
            buf=ByteBuffer.allocate(4).putInt(paknum).array();
            bytes[3]=buf[0];
            bytes[4]=buf[1];
            bytes[5]=buf[2];
            bytes[6]=buf[3];
            DatagramPacket pak=new DatagramPacket(bytes, len, onlinesrvip, onlinesrvport);
            sendpaket(pak);
            addonlinepp(paknum, pak);
        }else{
            for (int t=0; t<maxunittr; t++) {
                if (t==clientid || clientip[t]==null) continue;
                int paknum=getpaknum(t);
                buf=ByteBuffer.allocate(4).putInt(paknum).array();
                bytes[2]=buf[0];
                bytes[3]=buf[1];
                bytes[4]=buf[2];
                bytes[5]=buf[3];
                DatagramPacket pak=new DatagramPacket(bytes, len, clientip[t], clientport[t]);
                sendpaket(pak);
                addpp(t, paknum, pak);
            }
        }
    }

    void sendaddallunit(InetAddress ip, int port, int cid){//команда добавить юнитov novomu clientu
        int paknum;
        if (onlinegame){
            paknum=getonlinepaknum();
        }else{
            paknum=getpaknum(cid);
        }
        ByteArrayOutputStream baos=null;
        DataOutputStream daos;
        for (int pop=0; pop<100; pop++){
            try{
                baos=new ByteArrayOutputStream();
                daos=new DataOutputStream(baos);
                daos.writeByte(21);//_addunit_
                if (onlinegame) daos.writeByte(cid);
                daos.writeByte(clientid);
                daos.writeInt(paknum);
                for (int ii=0; ii<maxunittr; ii++) {
                    if (unet[ii] || untip[ii]==-1) continue;
                    daos.writeByte(ii);
                    daos.writeByte(uclientid[ii]);
                    daos.writeByte(untip[ii]);
                    daos.writeShort(Math.round(unitXY.ux[ii]));
                    daos.writeShort(Math.round(unitXY.uy[ii]));
                    daos.writeByte(uteam[ii]);
                    boolean unitAlive = (utip[ii] != -1 && utip[ii] != 5);
                    int sendLife = (unitAlive && ulife[ii] > 0) ? ulife[ii] : ((untip[ii] >= 0 && untip[ii] < maxtunit) ? tumaxlife[untip[ii]] : 100);
                    daos.writeBoolean(ubot[ii]);
                    daos.writeBoolean(unitAlive);
                    daos.writeByte(uobtip[ii][0]);
                    daos.writeByte(uobtip[ii][1]);
                    daos.writeByte(uobtip[ii][2]);
                    daos.writeShort(ukills[ii]);
                    daos.writeShort(udeath[ii]);
                    daos.writeShort(sendLife);
                    daos.writeShort(uarmor[ii]);
                    daos.writeByte(utslot[ii]);
                    daos.writeShort(Math.max(-32768, Math.min(32767, udengi[ii])));
                    daos.writeUTF(uname[ii]);
                    if (daos.size()>plength-150 && ii<maxunittr-1){
                        boolean send=false;
                        for (int i=ii+1; i<maxunittr; i++){
                            if (!unet[i] && untip[i]!=-1){
                                send=true;
                                break;
                            }
                        }
                        if (send){
                            daos.close();
                            sendaddallunitSend(ip, port, cid, paknum, baos);
                            baos=new ByteArrayOutputStream();
                            daos=new DataOutputStream(baos);
                            daos.writeByte(21);
                            if (onlinegame) daos.writeByte(cid);
                            daos.writeByte(clientid);
                            if (onlinegame){
                                paknum=getonlinepaknum();
                            }else{
                                paknum=getpaknum(cid);
                            }
                            daos.writeInt(paknum);
                        }
                    }
                }
                daos.close();
            }catch(IOException e){
                e.printStackTrace();
                continue;
            }
            break;
        }
        sendaddallunitSend(ip, port, cid, paknum, baos);
    }

    void sendaddallunitSend(InetAddress ip, int port, int cid, int paknum, ByteArrayOutputStream baos){
        final byte[] bytes=baos.toByteArray();
        if (onlinegame){
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, onlinesrvip, onlinesrvport);
            sendpaket(pak);
            addonlinepp(paknum, pak);
        }else{
            DatagramPacket pak=new DatagramPacket(bytes, bytes.length, ip, port);
            sendpaket(pak);
            addpp(cid, paknum, pak);
        }
    }

    // отправка пакета отключения от сервера перед закрытием сокета
    void senddisconnect(){//disconnect samogo sebja
        sendprofstat();
        clconnecttimer=0;
        try{
            if (onlinegame){
                ByteArrayOutputStream baos=new ByteArrayOutputStream();
                DataOutputStream daos=new DataOutputStream(baos);
                daos.writeByte(17);//_disconn_
                daos.writeByte(maxnetclient);
                daos.writeByte(clientid);
                daos.writeInt(gamerid);
                daos.close();
                final byte[] bytes=baos.toByteArray();
                final DatagramPacket pak=new DatagramPacket(bytes, bytes.length, onlinesrvip, onlinesrvport);
                sendpaket(pak);
                final DatagramSocket sock = udpSocket;
                if (sock != null && !sock.isClosed() && onlinesrvip != null && onlinesrvport != 0) {
                    if (android.os.Looper.myLooper() == android.os.Looper.getMainLooper()) {
                        Thread disconnThread = new Thread(() -> {
                            try {
                                for (int k = 0; k < 3; k++) {
                                    if (!sock.isClosed()) sock.send(pak);
                                }
                            } catch (Exception ignored) {}
                        });
                        disconnThread.setPriority(Thread.MAX_PRIORITY);
                        disconnThread.start();
                        try {
                            disconnThread.join(60);
                        } catch (Exception ignored) {}
                    } else {
                        try {
                            for (int k = 0; k < 3; k++) {
                                if (!sock.isClosed()) sock.send(pak);
                            }
                        } catch (Exception ignored) {}
                    }
                }
            }else{
                final ArrayList<DatagramPacket> lanPackets = new ArrayList<>();
                for (int i=0; i<maxunittr; i++) {
                    if (i==clientid || clientip[i]==null) continue;
                    ByteArrayOutputStream baos=new ByteArrayOutputStream();
                    DataOutputStream daos=new DataOutputStream(baos);
                    daos.writeByte(17);//_disconn_
                    daos.writeByte(clientid);
                    daos.writeInt(gamerid);
                    daos.close();
                    final byte[] bytes=baos.toByteArray();
                    DatagramPacket pak=new DatagramPacket(bytes, bytes.length, clientip[i], clientport[i]);
                    sendpaket(pak);
                    lanPackets.add(pak);
                }
                final DatagramSocket sock = udpSocket;
                if (sock != null && !sock.isClosed() && !lanPackets.isEmpty()) {
                    if (android.os.Looper.myLooper() == android.os.Looper.getMainLooper()) {
                        Thread disconnThread = new Thread(() -> {
                            try {
                                for (int k = 0; k < 2; k++) {
                                    for (DatagramPacket p : lanPackets) {
                                        if (!sock.isClosed()) sock.send(p);
                                    }
                                }
                            } catch (Exception ignored) {}
                        });
                        disconnThread.setPriority(Thread.MAX_PRIORITY);
                        disconnThread.start();
                        try {
                            disconnThread.join(60);
                        } catch (Exception ignored) {}
                    } else {
                        try {
                            for (int k = 0; k < 2; k++) {
                                for (DatagramPacket p : lanPackets) {
                                    if (!sock.isClosed()) sock.send(p);
                                }
                            }
                        } catch (Exception ignored) {}
                    }
                }
            }
        }catch(IOException e){
            e.printStackTrace();
        }
    }

