    private final Object moveRenderLock = new Object();
    private volatile boolean moveStepRequested = true;
    private volatile long lastRenderFrameNano = 0L;

    // синхронизированный с рендером поток шага движения
    private final Runnable runmove_prov = new Runnable() {
        public void run() {
            int id = threadsid;
            if (thmove_prov == null) return;
            thmove_prov.setPriority(Thread.NORM_PRIORITY);
            while (!renderpause && !threadspause && id == threadsid) {
                long start = System.currentTimeMillis();
                long nowNano = System.nanoTime();
                boolean activeRenderSync = (glscreen == 2 && loadingtimer >= 5 && !getcustommap && (nowNano - lastRenderFrameNano) < 25000000L);
                if (!activeRenderSync) {
                    synchronized (moveRenderLock) {
                        if ((System.nanoTime() - lastRenderFrameNano) >= 25000000L || glscreen != 2 || loadingtimer < 5 || getcustommap) {
                            move_prov();
                        }
                    }
                }
                long time = 16 - (System.currentTimeMillis() - start);
                try {
                    if (time > 0) Thread.sleep(time);
                } catch (InterruptedException e) {
                    break;
                }
            }
        }
    };

