    class MapSender implements Runnable{
        int cli;
        String mapuid;

        MapSender(int cli, String mapuid){
            this.cli=cli;
            this.mapuid=mapuid;
        }

        public void run() {
            if (mapuid == null || mapuid.isEmpty()) return;
            File mapfile = findMapFile(mapuid + ".map");
            File obfile = findObFile(mapuid + ".ob");
            if (mapfile == null || !mapfile.exists() || obfile == null || !obfile.exists()) return;
            try{
                DataInputStream dais=new DataInputStream(new FileInputStream(mapfile));
                byte gver=dais.readByte();
                String mapname=dais.readUTF();
                String uid=dais.readUTF();
                int srvid=dais.readInt();
                int rid=dais.readInt();
                short mapw=dais.readShort();
                short maph=dais.readShort();
                String timestamp=dais.readUTF();
                int maxmapk=dais.readInt();
                short mapminx=dais.readShort();
                short mapminy=dais.readShort();
                short mapmaxx=dais.readShort();
                short mapmaxy=dais.readShort();
                custommaphead=new datagame_custommaphead(gver, mapname, uid, srvid, rid, mapw, maph, timestamp, maxmapk, mapminx, mapminy, mapmaxx, mapmaxy);
                sendmapheadudp(cli, custommaphead);
                Thread.sleep(10);
                memap.clear();
                meob.clear();
                while (dais.available()>0){
                    String texname=dais.readUTF();
                    byte svp=dais.readByte();
                    short x0=dais.readShort();
                    short y0=dais.readShort();
                    short x1=dais.readShort();
                    short y1=dais.readShort();
                    memap.add(new GameMapKv(texname, 0, 0, svp, x0, y0, x1, y1, 0, false, false));
                }
                dais.close();
                sendmapdataudp(cli);
                Thread.sleep(10);
                dais=new DataInputStream(new FileInputStream(obfile));
                dais.readByte();//gameversion
                dais.readUTF();//timestamp
                while (dais.available()>0){
                    byte obtip=dais.readByte();
                    short x=dais.readShort();
                    short y=dais.readShort();
                    meob.add(new GameObject(obtip, x, y));
                }
                dais.close();
                sendobdataudp(cli);
                Thread.sleep(10);
                sendsavecustommapudp(cli, mapuid);
                memap.clear();
                meob.clear();
            }catch(Exception e){
                e.printStackTrace();
            }
        }
    }

