    // буферы для task1
    private final float[] task1_xo = new float[9];
    private final float[] task1_yo = new float[9];
    private final int[] task1_oo = new int[9];
    private final int[] task1_uob = new int[maxuslot];
    private final boolean[] task1_slotok = new boolean[maxuslot];
