    boolean t2_prov(int razd2, int fx, int fy, boolean mode1){//проверка возможности нахождения юнита в данных координатах
        int nx=fx-razd2;
        int ny=fy-razd2;
        int kx=fx+razd2;
        int ky=fy+razd2;
        if (nx<0) return false;
        if (ny<0) return false;
        if (kx>=mapfw) return false;
        if (ky>=mapfh) return false;
        int t, fm;
        if (mode1){
            for (int i=nx; i<kx; i++){
                for (t=ny; t<ky; t++){
                    if (fmap[i][t]!=0) return false;
                }
            }
        }else{
            for (int i=nx; i<kx; i++){
                for (t=ny; t<ky; t++){
                    if (fmap[i][t]>0 && fmap[i][t]<10){
                        return false;
                    }else{
                        fm=fmap[i][t]-10;
                        if (fm>=0 && obtip[fm]!=0 && obtip[fm]!=45 && obtip[fm]!=49) {
                            return false;
                        }
                    }
                }
            }
        }
        return true;
    }

