    // закрытие соединения игры при потере связи с профильным сервером
    public void disconnectOnProfileServerLost() {
        new Thread(() -> {
            try {
                if (netgame) {
                    for (int i = 0; i < 3; i++) {
                        senddisconnect();
                    }
                }
                stopnetgame(true);
            } catch (Exception ignored) {}
            runOnUiThread(() -> {
                try {
                    finish();
                } catch (Exception ignored) {}
            });
        }).start();
    }

