    public void finish() {
        super.finish();
        overridePendingTransition(0, 0);
    }

    String filtername(String name){//ubiraet nedopustimie simvoli s imeni igroka
        int n;
        int txtlen=name.length();
        boolean res;
        String result=name;
        for (int i = 0; i < txtlen; i++) {
            n=name.charAt(i);
            res=false;
            for (int t = 0; t < maxchar; t++) {
                if (n==chid[t]){
                    res=true;
                    break;
                }
            }
            if (!res){
                result=result.substring(0, i)+"?"+result.substring(i+1);
            }
        }
        for (int i=0; i<pizdec.size(); i++) {
            n=result.toLowerCase().indexOf(pizdec.get(i).toLowerCase());
            while (n!=-1){
                result=result.substring(0, n)+"-"+result.substring(n+pizdec.get(i).length());
                n=result.toLowerCase().indexOf(pizdec.get(i).toLowerCase());
            }
        }
        return result;
    }

