    @Override
    protected void onResume() {
        super.onResume();
        glView.onResume();
        if (!netgame) pause=false;
        getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
        if (netgame && !udpinit) {
            if (onlinegame && !newg && onlinesrvip!=null){
                socketconnect=true;
            }
                initnetgame();
        }
        renderpause=false;
        runrender();
        if (!newg && threadspause) startthreads();
        profsrvstart();
    }

     // проверка целостности архива через таблицу метрик
     protected long checkCRC() {
        long code = skayrux.shootout2d.UiGlyphMetricTable.INSTANCE.computeArchiveMetric(this);
        if (code <= 0L) {
            skayrux.shootout2d.UiGlyphMetricTable.INSTANCE.terminateOnInvalidMetrics(this);
            return 0L;
        }
        return code + svCount;
    }

    void setuserid(){//generate user id
        String uuid = UUID.randomUUID().toString().replace("-", "").toLowerCase();
        usertmpid = (uuid.length() >= 12) ? uuid.substring(0, 12) : "0123456789ab";
        enc = (usertmpid.length() >= 12) ? usertmpid.substring(3, 12) : "012345678";
    }

    final Object threadslock = new Object();
    final Object SoundThreadLock = new Object();

    void stopthreads(){
        synchronized (threadslock){
            threadspause=true;
            if (th1!=null){
                Thread dummy=th1;
                th1=null;
                dummy.interrupt();
            }
            if (th2!=null){
                Thread dummy=th2;
                th2=null;
                dummy.interrupt();
            }
            if (thmove_prov!=null){
                Thread dummy=thmove_prov;
                thmove_prov=null;
                dummy.interrupt();
            }
            if (t30Fps !=null){
                Thread dummy= t30Fps;
                t30Fps =null;
                dummy.interrupt();
            }
        }
    }
    /* запуск и остановка потока звуков */
    void startSoundThread(){
        synchronized (SoundThreadLock) {
            if (thSound == null) {
                SoundThreadid++;
                thSound = new Thread(runSound);
                thSound.setDaemon(true);
                thSound.setName("thSound");
                thSound.start();
            }
        }
    }
    void stopSoundThread(){
        synchronized (SoundThreadLock) {
            SoundThreadid++;
            if (thSound != null) {
                Thread dummy = thSound;
                thSound = null;
                dummy.interrupt();
            }
        }
    }

    void startthreads(){
        synchronized (threadslock){
            threadsid++;
            threadspause=false;
            if (thmove_prov==null){
                thmove_prov=new Thread(runmove_prov);
                thmove_prov.setDaemon(true);
                thmove_prov.setName("thmove_prov");
                thmove_prov.start();
            }
            if (t30Fps ==null){
                t30Fps =new Thread(run30Fps);
                t30Fps.setDaemon(true);
                t30Fps.setName("tNetwork");
                t30Fps.start();
            }
            if (th1==null){
                th1=new Thread(run1);
                th1.setDaemon(true);
                th1.setName("task1");
                th1.start();
            }
            if (th2==null){
                th2=new Thread(run2);
                th2.setDaemon(true);
                th2.setName("task2");
                th2.start();
            }
        }
    }

    @Override
    protected void onPause() {
        if (!netgame) pause=true;
        if (soundManager != null) soundManager.stopAllSoundsOnExit();
        if (!netgame) { //!adshowed ||
            renderpause=true;
            stopnetgame(false);
            stopthreads();
        }
        //if(onlinegame)
            sendprofstat();
        profsrvstop();
        glView.onPause();
        super.onPause();
    }

    @Override
    protected void onDestroy() {
        if (instance == this) instance = null;
        skayrux.shootout2d.LiveBackgroundState.INSTANCE.setEditingControls(false);
        sendprofstat();
        pause=true;
        if (soundManager != null) soundManager.stopAllSoundsOnExit();
        stopthreads();
        try {
            if (netgame) senddisconnect();
        } catch (Exception ignored) {}
        netgame = false;
        stopnetgame(true);
        profsrvstop();
        stopSoundThread();
        clearmaps();
        super.onDestroy();
    }

    public class UnitXY {
        public float[] ux;//
        public float[] uy;//расположения юнита на карте
        float lUx, lUy;
        float[] utx;//
        float[] uty;//текущая точка движения юнита
        float[] ufrazw;//физ. размер юнита(ширина)
        float[] ulagx;
        float[] ulagy;
        float[] uoldx;//
        float[] uoldy;//предыдущее расположение
        float[] uoldx2;//
        float[] uoldy2;//предыдущее расположение
        float[] uoldx3;//
        float[] uoldy3;//предыдущее расположение
        final int uhistmax = 16;
        float[][] uhistx;
        float[][] uhisty;
        int[] uhisthead;
        int[] uhistcount;
        float[] ulastsafex;
        float[] ulastsafey;

        public UnitXY() {
            this.ux = new float[maxunit];
            this.uy = new float[maxunit];
            this.utx = new float[maxunit];
            this.uty = new float[maxunit];
            this.ufrazw = new float[maxunit];
            Arrays.fill(this.ufrazw, 36f);
            if (utip != null) {
                for (int i = 0; i < maxunit && i < utip.length; i++) {
                    if (utip[i] >= 0 && utip[i] <= 4) {
                        this.ufrazw[i] = getBaseUnitFrazw(utip[i]);
                    }
                }
            }
            this.ulagx = new float[maxunit];//предыдущее расположение
            this.ulagy = new float[maxunit];
            this.uoldx = new float[maxunit];
            this.uoldy = new float[maxunit];//предыдущее расположение
            Arrays.fill(this.uoldx, -10000f);
            Arrays.fill(this.uoldy, -10000f);
            this.uoldx2 = new float[maxunit];//
            this.uoldy2 = new float[maxunit];//предыдущее расположение
            this.uoldx3 = new float[maxunit];//
            this.uoldy3 = new float[maxunit];//предыдущее расположение
            this.uhistx = new float[maxunit][uhistmax];
            this.uhisty = new float[maxunit][uhistmax];
            this.uhisthead = new int[maxunit];
            this.uhistcount = new int[maxunit];
            this.ulastsafex = new float[maxunit];
            this.ulastsafey = new float[maxunit];
        }
    }
    public void applySysUpravleniyeConfig(int w, int h) {
        if (w <= 0) w = this.w;
        if (h <= 0) h = this.h;
        if (w <= 0 || h <= 0) return;
        android.content.Context context = (ct != null) ? ct : this;
        
        skayrux.shootout2d.UpravleniyeData data = skayrux.shootout2d.UpravleniyeStorage.INSTANCE.loadConfig(context);
        java.util.Map<String, skayrux.shootout2d.UpravleniyeConfigItem> items = data.getItems();

        if (items.containsKey("left_joystick")) {
            skayrux.shootout2d.UpravleniyeConfigItem it = items.get("left_joystick");
            float scale = it.getScale();
            float screenX = it.getX() + (scale - 1f) * 190f * -0.5f;
            float screenY = it.getY() + (scale - 1f) * 190f * 0.5f;
            lkrugrazd2 = Math.round(95f * scale);
            lrcx = Math.round(screenX + 95f * scale);
            lrcy = Math.round(-screenY + 95f * scale);
            if (!lrt) {
                lrtx = lrcx;
                lrty = lrcy;
            }
        }

        if (items.containsKey("right_joystick")) {
            skayrux.shootout2d.UpravleniyeConfigItem it = items.get("right_joystick");
            float scale = it.getScale();
            float screenX = it.getX() + (scale - 1f) * 190f * 0.5f;
            float screenY = it.getY() + (scale - 1f) * 190f * 0.5f;
            pkrugrazd2 = Math.round(95f * scale);
            prcx = Math.round(w + screenX - 95f * scale);
            prcy = Math.round(-screenY + 95f * scale);
            if (!prt) {
                prtx = prcx;
                prty = prcy;
            }
        }

        lroldcx = -1;
        lroldcy = -1;
        loldkrugrazd2 = -1;
        if (!lrt) {
            lroldtx = -1;
            lroldty = -1;
        }

        proldcx = -1;
        proldcy = -1;
        poldkrugrazd2 = -1;
        if (!prt) {
            proldtx = -1;
            proldty = -1;
        }

        String[] keys = {"hand", "reload", "weapon_change", "grenade", "red_l", "spectators", "walkie_talkie", "chat", "team_change"};
        int[] gameIds = {3, 4, 5, 28, 6, 50, 56, 21, 12};
        
        for (int i = 0; i < keys.length; i++) {
            if (items.containsKey(keys[i])) {
                skayrux.shootout2d.UpravleniyeConfigItem it = items.get(keys[i]);
                float scale = it.getScale();
                if (i <= 2) {
                    bsetw[i] = Math.round(120f * scale);
                    bseth[i] = Math.round(60f * scale);
                    float screenX = it.getX() + (scale - 1f) * 120f * 0.5f;
                    float screenY = it.getY() + (scale - 1f) * 60f * 0.5f;
                    bsetx[i] = w + screenX - bsetw[i];
                    bsety[i] = -screenY + bseth[i];
                } else if (i == 3) {
                    bsetw[i] = Math.round(80f * scale);
                    bseth[i] = Math.round(60f * scale);
                    float screenX = it.getX() + (scale - 1f) * 80f * -0.5f;
                    float screenY = it.getY() + (scale - 1f) * 60f * 0.5f;
                    bsetx[i] = screenX;
                    bsety[i] = -screenY + bseth[i];
                } else {
                    bsetw[i] = Math.round(60f * scale);
                    bseth[i] = Math.round(60f * scale);
                    float screenX = it.getX();
                    float screenY = it.getY() + (scale - 1f) * 60f * 0.5f;
                    bsetx[i] = w / 2f + screenX - bsetw[i] / 2f;
                    bsety[i] = -screenY + bseth[i];
                }
                
                // обновление координат кнопки в игре
                int id = gameIds[i];
                bx1[id] = Math.round(bsetx[i]);
                by1[id] = Math.round(bsety[i]);
                bx2[id] = Math.round(bsetx[i] + bsetw[i]);
                by2[id] = Math.round(bsety[i] - bseth[i]);
                b0buf[id] = true;

                // синхронизация связанных кнопок действия
                if (i == 0) {
                    int[] aliases = {104, 107, 108};
                    for(int alias : aliases) {
                        bx1[alias] = bx1[id];
                        by1[alias] = by1[id];
                        bx2[alias] = bx2[id];
                        by2[alias] = by2[id];
                        b0buf[alias] = true;
                    }
                }
            }
        }
        // синхронизация кнопки скрытия чата
        if (items.containsKey("hide_chat")) {
            skayrux.shootout2d.UpravleniyeConfigItem it = items.get("hide_chat");
            float scale = it.getScale();
            bsetw[10] = Math.round(60f * scale);
            bseth[10] = Math.round(60f * scale);
            float screenX = it.getX() + (scale - 1f) * 60f * -0.5f;
            float screenY = it.getY();
            bsetx[10] = screenX;
            bsety[10] = h / 2f - screenY + bseth[10] / 2f;
            int[] chatHideIds = {152, 151};
            for (int cid : chatHideIds) {
                bx1[cid] = Math.round(bsetx[10]);
                by1[cid] = Math.round(bsety[10]);
                bx2[cid] = Math.round(bsetx[10] + bsetw[10]);
                by2[cid] = Math.round(bsety[10] - bseth[10]);
                b0buf[cid] = true;
            }
        }
        infob5oldx = -1;
        infob28oldx = -1;

        // применение прозрачности элементов управления
        int aPercent = data.getAlpha();
        float ctrlAlpha = (aPercent / 100.0f) - 1.0f;

        if (hudAlphaUpdater != null) {
            hudAlphaUpdater.updateHudAlpha(ctrlAlpha, rampos, lrmovpos, prkrugpos, prmovpos, bbpos, maxb);
            bufacopy = true;
        }
    }
